local function StopTween()
    if _G.StopTween then
        return
    end
    
    _G.StopTween = true
    wait()
    local player = game.Players.LocalPlayer
    local character = player.Character
    if character and character:IsDescendantOf(game.Workspace) then
        local humanoidRootPart = character:WaitForChild("HumanoidRootPart")
        if humanoidRootPart then
            humanoidRootPart.CFrame = humanoidRootPart.CFrame
        end
    end
    wait()    
    if character:FindFirstChild("BodyClip") then
        character.BodyClip:Destroy()
    end
    if character:FindFirstChild("PartTele") then
        character.PartTele:Destroy()
    end
    _G.StopTween = false
end

MatsuneA1["4"].MouseButton1Click:Connect(function()
    StopTween()
end)

-- A Seat (boat, chair, or a map seat a route happens to land on) leaves the
-- character Seated, which freezes movement and blocks every attack.  The
-- current client has no remote for this - Sit is a plain Humanoid property -
-- so clear it locally and break the weld the seat created.
task.spawn(function()
    while task.wait(5) do
        pcall(function()
            local character = game:GetService("Players").LocalPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not (humanoid and humanoid.Sit) then
                return
            end
            local seat = humanoid.SeatPart
            humanoid.Sit = false
            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
            if seat then
                local weld = seat:FindFirstChild("SeatWeld")
                if weld then
                    weld:Destroy()
                end
            end
        end)
    end
end)

_G.FastAttack = true

if _G.FastAttack then
    local _ENV = (getgenv or getrenv or getfenv)()

    local function SafeWaitForChild(parent, childName)
        local success, result = pcall(function()
            return parent:WaitForChild(childName)
        end)
        if not success or not result then
            warn("noooooo: " .. childName)
        end
        return result
    end

    local function WaitChilds(path, ...)
        local last = path
        for _, child in {...} do
            last = last:FindFirstChild(child) or SafeWaitForChild(last, child)
            if not last then break end
        end
        return last
    end

    local VirtualInputManager = game:GetService("VirtualInputManager")
    local CollectionService = game:GetService("CollectionService")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local TeleportService = game:GetService("TeleportService")
    local RunService = game:GetService("RunService")
    local Players = game:GetService("Players")
    local Player = Players.LocalPlayer

    if not Player then
        warn("Không tìm thấy người chơi cục bộ.")
        return
    end

    local Remotes = SafeWaitForChild(ReplicatedStorage, "Remotes")
    if not Remotes then return end

    local Validator = SafeWaitForChild(Remotes, "Validator")
    local CommF = SafeWaitForChild(Remotes, "CommF_")
    local CommE = SafeWaitForChild(Remotes, "CommE")

    local ChestModels = SafeWaitForChild(workspace, "ChestModels")
    local WorldOrigin = SafeWaitForChild(workspace, "_WorldOrigin")
    local Characters = SafeWaitForChild(workspace, "Characters")
    local Enemies = SafeWaitForChild(workspace, "Enemies")
    local Map = SafeWaitForChild(workspace, "Map")

    local EnemySpawns = SafeWaitForChild(WorldOrigin, "EnemySpawns")
    local Locations = SafeWaitForChild(WorldOrigin, "Locations")

    local RenderStepped = RunService.RenderStepped
    local Heartbeat = RunService.Heartbeat
    local Stepped = RunService.Stepped

    local Modules = SafeWaitForChild(ReplicatedStorage, "Modules")
    local Net = SafeWaitForChild(Modules, "Net")

    local sethiddenproperty = sethiddenproperty or function(...) return ... end
    local setupvalue = setupvalue or (debug and debug.setupvalue)
    local getupvalue = getupvalue or (debug and debug.getupvalue)

    local Settings = {
        AutoClick = true,
        ClickDelay = 0
    }

    local Module = {}

    Module.FastAttack = (function()
        if _ENV.rz_FastAttack then
            -- One-time migration: stop the experimental supervised worker so
            -- this restored baseline creates the original Fast Attack again.
            if _ENV.rz_FastAttack._xyraxWorkerVersion then
                _ENV.rz_FastAttack._xyraxWorkerRunning = false
                _ENV.rz_FastAttack = nil
            else
                return _ENV.rz_FastAttack
            end
        end
        if _ENV.rz_FastAttack then
            return _ENV.rz_FastAttack
        end

        local FastAttack = {
            Distance = 100,
            attackMobs = true,
            attackPlayers = true,
            Equipped = nil
        }

        local RegisterAttack = SafeWaitForChild(Net, "RE/RegisterAttack")
        local RegisterHit = SafeWaitForChild(Net, "RE/RegisterHit")

        local function IsAlive(character)
            return character and character:FindFirstChild("Humanoid") and character.Humanoid.Health > 0
        end

        local function ProcessEnemies(OthersEnemies, Folder)
            local BasePart = nil
            for _, Enemy in Folder:GetChildren() do
                local Head = Enemy:FindFirstChild("Head")
                if Head and IsAlive(Enemy) and Player:DistanceFromCharacter(Head.Position) < FastAttack.Distance then
                    if Enemy ~= Player.Character then
                        table.insert(OthersEnemies, { Enemy, Head })
                        BasePart = Head
             end
         end

     end
            return BasePart
        end

        -- Fast Attack used to scan Enemies + Characters on every scheduler
        -- tick, including while travelling or waiting for a spawn.  Keep the
        -- zero-delay attack cadence once a target is found, but let the idle
        -- pass yield so it does not consume a core while there is nothing to
        -- hit.
        local function ShouldScanForFastAttack()
            local tween = _G.TweenCache
            if tween and tween.PlaybackState == Enum.PlaybackState.Playing then
                return false
            end

            local environment = (getgenv and getgenv()) or _G
            local automation = environment and environment.XyraxAutomation
            -- Auto Raid's HP watchdog has moved the player to safety.  Do
            -- not keep sending combat hits while that state is active.
            if automation and automation.RaidFleeing then
                return false
            end
            local activeJob = automation and automation.ActiveJob

            -- Auto Raid's own combat (attackNearbyEnemies) now runs a
            -- Health=0 kill on the last two raid islands (4 and 5) instead
            -- of relying on this shared aura, so it must never race that
            -- logic for the kill there.  Islands 1-3 (and everywhere else
            -- Auto Raid is active - travelling, buying a Chip, etc.) are
            -- unaffected and keep firing exactly as before.
            if activeJob == "Auto Raid" or _G.AutoRaid == true then
                local onFinalRaidIslands = type(IsIslandRaid) == "function"
                    and (IsIslandRaid(4) or IsIslandRaid(5)) ~= nil
                return not onFinalRaidIslands
            end

            -- Both Progression Boss job names carry the boss label after a
            -- colon (e.g. "Auto Progression Boss: Vice Admiral"), so the
            -- old exact-match check here never actually matched either one
            -- - Fast Attack silently sat out every Progression Boss fight
            -- until this was a prefix check.  Race V3 and Midnight Blade
            -- are exact names (added when those systems were built).
            local isProgressionBossJob = type(activeJob) == "string"
                and string.sub(activeJob, 1, #"Auto Progression Boss") == "Auto Progression Boss"
            local isProgressionBossSea2Job = type(activeJob) == "string"
                and string.sub(activeJob, 1, #"Auto Sea2 Progression Boss") == "Auto Sea2 Progression Boss"
            if activeJob == "Farm Level" or activeJob == "Auto Farm Boss"
                or isProgressionBossJob or isProgressionBossSea2Job
                or activeJob == "Auto Race V2" or activeJob == "Auto Race V3"
                or activeJob == "Auto Saber" or activeJob == "Auto Pole"
                or activeJob == "Auto Saw" or activeJob == "Auto Warden"
                or activeJob == "Auto Trident"
                or activeJob == "Auto Second Sea"
                or activeJob == "Auto Lightning Bolt" then
                return true
            end

            return _G.AutoFarm == true
                or _G.AutoBoss == true
                or _G.AutoProgressionBoss == true
                or _G.AutoProgressionBossSea2 == true
                or _G.XyraxSea1WeaponBoss ~= nil
                or AutoSaber == true
                or _G.AutoSecondSea == true
                or _G.AutoRaceV3 == true
                or _G.AutoLightningBolt == true
        end

        function FastAttack:Attack(BasePart, OthersEnemies)
            if not BasePart or #OthersEnemies == 0 then return end
            RegisterAttack:FireServer(Settings.ClickDelay or 0)
            RegisterHit:FireServer(BasePart, OthersEnemies)
        end

        function FastAttack:AttackNearest()
            local OthersEnemies = {}
            local Part1 = ProcessEnemies(OthersEnemies, Enemies)
            local Part2 = ProcessEnemies(OthersEnemies, Characters)

            local character = Player.Character
            if not character then return false end
            local equippedWeapon = character:FindFirstChildOfClass("Tool")

            if equippedWeapon and equippedWeapon:FindFirstChild("LeftClickRemote") then
                for _, enemyData in ipairs(OthersEnemies) do
                    local enemy = enemyData[1]
                    local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                    if enemyRoot then
                        local direction = (enemyRoot.Position - character:GetPivot().Position).Unit
                        pcall(function()
                            equippedWeapon.LeftClickRemote:FireServer(direction, 1)
                        end)
                    end
                end
            elseif #OthersEnemies > 0 then
                self:Attack(Part1 or Part2, OthersEnemies)
            end

            return #OthersEnemies > 0
        end

        function FastAttack:BladeHits()
            local Equipped = IsAlive(Player.Character) and Player.Character:FindFirstChildOfClass("Tool")
            if Equipped and Equipped.ToolTip ~= "Gun" then
                return self:AttackNearest()
            end
            return false
        end

        task.spawn(function()
            while true do
                local hitTarget = false
                if Settings.AutoClick and ShouldScanForFastAttack() then
                    hitTarget = FastAttack:BladeHits() == true
                end

                task.wait(hitTarget and (Settings.ClickDelay or 0) or 0.12)
            end
        end)

        _ENV.rz_FastAttack = FastAttack
        return FastAttack
    end)()
end
   
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")
if not player.Team then
    if getgenv().Team == "Marines" then
        ReplicatedStorage.Remotes.CommF_:InvokeServer("SetTeam", "Marines")
    elseif getgenv().Team == "Pirates" then
        ReplicatedStorage.Remotes.CommF_:InvokeServer("SetTeam", "Pirates")
    end
    repeat
        task.wait(1)
        local chooseTeam = playerGui:FindFirstChild("ChooseTeam", true)
        local uiController = playerGui:FindFirstChild("UIController", true)
        if chooseTeam and chooseTeam.Visible and uiController then
            for _, v in pairs(getgc(true)) do
                if type(v) == "function" and getfenv(v).script == uiController then
                    local constant = getconstants(v)
                    pcall(function()
                        if (constant[1] == "Pirates" or constant[1] == "Marines") and #constant == 1 then
                            if constant[1] == getgenv().Team then
                                v(getgenv().Team)
                            end
                        end
                    end)
                end
            end
        end
    until player.Team
end   
   
-- `Effect` is now a ModuleScript.  Require it before reading the functions it
-- exports; accessing `.Container` directly on the instance aborts the script
-- (and prevents the UI below from being created).
local function disableEffectCallbacks()
    local effectModule = game:GetService("ReplicatedStorage"):FindFirstChild("Effect")
    if not effectModule or not effectModule:IsA("ModuleScript") then
        return
    end

    local loaded, effect = pcall(require, effectModule)
    if not loaded or type(effect) ~= "table" then
        return
    end

    local container = effect.Container
    if type(container) ~= "table" then
        return
    end

    for _, callbackName in ipairs({"Death", "Respawn"}) do
        local callback = container[callbackName]
        if type(callback) == "function" then
            pcall(hookfunction, callback, function() end)
        end
    end
end

disableEffectCallbacks()

