    function EquipWeapon(ToolSe)
        -- Auto Saber temporarily reserves Torch/Relic.  Several legacy farm
        -- workers also call EquipWeapon(_G.SelectWeapon), which otherwise
        -- swaps the quest item back to Black Step before its touch registers.
        local saberLockedTool = _G.XyraxSaberLockedTool
        if AutoSaber and saberLockedTool then
            ToolSe = saberLockedTool
        end
        if not ToolSe then
            return false
        end
        if not _G.NotAutoEquip then
            local player = game.Players.LocalPlayer
            local character = player.Character
            local backpack = player:FindFirstChild("Backpack")
            -- The selected style may already be equipped.  Treat that as
            -- success instead of looking only in Backpack and doing nothing.
            if character and character:FindFirstChild(ToolSe) then
                return true
            end
            if backpack and backpack:FindFirstChild(ToolSe) then
                Tool = backpack:FindFirstChild(ToolSe)
                wait(.1)
                character.Humanoid:EquipTool(Tool)
                return true
            end
        end
        return false
    end
    
