-- `topos` is declared before the local XyraxAutomation table below.  Resolve
-- the shared table lazily through the same environment that publishes it.
local function xyraxGetSharedAutomation()
    local environment = (getgenv and getgenv()) or _G
    return environment and environment.XyraxAutomation or nil
end

local block = Workspace:FindFirstChild("Rip_Indra")
if not block then
    block = Instance.new("Part", Workspace)
    block.Size = Vector3.new(1, 1, 1)
    block.Name = "Rip_Indra"
    block.Anchored = true
    block.CanCollide = false
    block.CanTouch = false
    block.Transparency = 1
end
local shouldTween = true

task.spawn(function()
    repeat task.wait() until lp.Character and lp.Character.PrimaryPart
    block.CFrame = lp.Character.PrimaryPart.CFrame
    while task.wait() do
        pcall(function()
            local b = lp.Character and lp.Character.PrimaryPart
            local automation = xyraxGetSharedAutomation()
            local fleeCFrame = automation and automation.RaidFleeCFrame
            -- Raid flee owns the shared movement proxy regardless of the
            -- normal tween state.  Reassert the saved CFrame every pass so
            -- an old or concurrent tween cannot pull the player to combat.
            if b and automation and automation.RaidFleeing and fleeCFrame
                and not automation.RaidFleeTweening then
                block.CFrame = fleeCFrame
                b.CFrame = fleeCFrame
                b.Anchored = true
                return
            end
            -- During the flee tween, let the existing movement proxy carry
            -- the character at the tween's current position.  Do not run the
            -- normal >200-stud proxy reset here: another direct CFrame writer
            -- must not be able to steal the flee route from block.
            if b and automation and automation.RaidFleeing and automation.RaidFleeTweening then
                b.CFrame = block.CFrame
                return
            end
            if shouldTween then
                if b and (b.Position - block.Position).Magnitude <= 200 then
                    b.CFrame = block.CFrame
                else
                    block.CFrame = b.CFrame
                end
                for _, e in pairs(lp.Character:GetChildren()) do
                    if e:IsA("BasePart") then e.CanCollide = false end
                end
            else
                for _, e in pairs(lp.Character:GetChildren()) do
                    if e:IsA("BasePart") then e.CanCollide = true end
                end
            end
        end)
    end
end)

function topos(target)
    local gg
    if typeof(target) == "Vector3" then gg = CFrame.new(target)
    elseif typeof(target) == "CFrame" then gg = target
    else gg = target and target.CFrame end
    if not gg then
        return
    end

    -- GhostShip is Lv.1000+ content (the water around it damages anyone
    -- below that, confirmed live) and every feature shares this one tween
    -- function.  Block landing there below the level requirement instead of
    -- patching each feature (Superhuman/RaceV2/Midnight Blade/etc.)
    -- individually - this is the single choke point all of them go through.
    local automation = xyraxGetSharedAutomation()
    local blockLevelValue = lp:FindFirstChild("Data") and lp.Data:FindFirstChild("Level")
    local blockLevel = blockLevelValue and blockLevelValue.Value or 0
    if blockLevel < 1000 and type(automation) == "table"
        and type(automation.IsOnGhostShip) == "function"
        and automation.IsOnGhostShip(gg.Position) then
        warn("[BfRef Safety] blocked a tween into GhostShip (Lv." .. blockLevel .. "/1000)")
        return
    end

    local character = lp.Character
    if not character or not character:FindFirstChild("HumanoidRootPart") then
        return
    end
    local rootPart = character.HumanoidRootPart
    local fleeCFrame = automation and automation.RaidFleeCFrame
    -- While fleeing, only the watchdog's explicitly-marked tween request may
    -- enter the shared movement system.  All other callers are denied so they
    -- cannot replace the route to safety or the later locked flee position.
    if automation and automation.RaidFleeing and fleeCFrame then
        if type(automation.FleeDebugMovementRequest) == "function" then
            automation.FleeDebugMovementRequest("topos", gg, rootPart)
        end
        if not automation.RaidFleeTweenRequest then
            if not automation.RaidFleeTweening then
                rootPart.CFrame = fleeCFrame
                rootPart.Anchored = true
                block.CFrame = fleeCFrame
            end
            return
        end
    end

    local distance = (gg.Position - rootPart.Position).Magnitude
    local tweenInfo = TweenInfo.new(distance / 165, Enum.EasingStyle.Linear)
    local tw = TweenService:Create(block, tweenInfo, {CFrame = gg})
    _G.TweenCache = tw

    if character.Humanoid.Sit then
        block.CFrame = CFrame.new(block.Position.X, gg.Y, block.Position.Z)
    end

    tw:Play()

    task.spawn(function()
        while tw.PlaybackState == Enum.PlaybackState.Playing do
            if not shouldTween then tw:Cancel(); break end
            task.wait(0.1)
        end
    end)

    return tw 
end
