--[[
    Xyrax Hub UI
    Obsidian-style, self-contained compatibility layer.  The feature code
    below intentionally keeps its original Window:Tab / Section control calls
    so callbacks, globals, tasks and feature initialization order stay intact.
]]
local function CreateXyraxHubWindow()
    local Players = game:GetService("Players")
    local UserInputService = game:GetService("UserInputService")
    local TweenService = game:GetService("TweenService")
    local parent = (gethui and gethui()) or game:GetService("CoreGui")
    local oldGui = parent:FindFirstChild("XyraxHubObsidian")
    if oldGui then
        oldGui:Destroy()
    end

    local function make(className, properties, instanceParent)
        local instance = Instance.new(className)
        for property, value in pairs(properties or {}) do
            instance[property] = value
        end
        instance.Parent = instanceParent
        return instance
    end

    local function corner(instance, radius)
        return make("UICorner", {CornerRadius = UDim.new(0, radius or 6)}, instance)
    end

    local function stroke(instance, color, thickness)
        return make("UIStroke", {Color = color, Thickness = thickness or 1, Transparency = 0.25}, instance)
    end

    local palette = {
        Background = Color3.fromRGB(6, 6, 6),
        Surface = Color3.fromRGB(16, 16, 16),
        SurfaceHover = Color3.fromRGB(30, 30, 30),
        Border = Color3.fromRGB(185, 185, 185),
        Text = Color3.fromRGB(255, 255, 255),
        Muted = Color3.fromRGB(178, 178, 178),
        Accent = Color3.fromRGB(238, 238, 238),
        AccentHover = Color3.fromRGB(255, 255, 255),
        AccentText = Color3.fromRGB(8, 8, 8),
        ToggleOff = Color3.fromRGB(58, 58, 58),
    }

    local gui = make("ScreenGui", {
        Name = "XyraxHubObsidian",
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
    }, parent)

    local mainFrame = make("Frame", {
        Name = "Main",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(900, 560),
        BackgroundColor3 = palette.Background,
        BorderSizePixel = 0,
    }, gui)
    corner(mainFrame, 10)
    stroke(mainFrame, palette.Border, 1)

    -- Status display: the old "AutomationStatus" statusHud frame (Xyrax Hub
    -- title + "กำลังทำ: ..." text block) is replaced by the Xyrax status
    -- panel merged in above (XyraxCreateStatusPanel) - same RightControl
    -- toggle, same data (current job + Level/Beli/Fragments), nicer look.
--[[
    Xyrax status panel - merged in verbatim from uix.lua (the old
