	local function addStatus(txt, val, order)
		local row = Instance.new("Frame")
		row.BackgroundTransparency = 1
		row.LayoutOrder = order
		row.ZIndex = 2
		row.Parent = list

		local key = Instance.new("TextLabel")
		key.Size = UDim2.new(0.55,0,1,0)
		key.BackgroundTransparency = 1
		key.Text = txt
		key.TextColor3 = Color3.fromRGB(160,165,178)
		key.Font = Enum.Font.GothamMedium
		key.TextSize = 15
		key.TextXAlignment = Enum.TextXAlignment.Left
		key.TextYAlignment = Enum.TextYAlignment.Center
		key.ZIndex = 2
		key.Parent = row

		local v = Instance.new("TextLabel")
		v.Size = UDim2.new(0.45,0,1,0)
		v.Position = UDim2.new(0.55,0,0,0)
		v.BackgroundTransparency = 1
		v.Text = val
		v.TextColor3 = Color3.new(1,1,1)
		v.Font = Enum.Font.GothamBold
		v.TextSize = 15
		v.TextXAlignment = Enum.TextXAlignment.Right
		v.TextYAlignment = Enum.TextYAlignment.Center
		v.ZIndex = 2
		v.Parent = row

		return v
	end

	local lvlVal = addStatus("Level", "1", 1)
	local coinVal = addStatus("Coins", "0", 2)
	local fragVal = addStatus("Fragments", "0", 3)
	local statusVal = addStatus("Status", "Idle", 4)
	local superhumanVal = addStatus("Superhuman", "❌", 5)
	local deathStepVal = addStatus("Death Step", "❌", 6)
	local sharkmanVal = addStatus("Sharkman Karate", "❌", 7)
	local electricClawVal = addStatus("Electric Claw", "❌", 8)
	local dragonTalonVal = addStatus("Dragon Talon", "❌", 9)
	local godhumanVal = addStatus("Godhuman", "❌", 10)

	local function animateValue(label, newValue)
		local newNum = tonumber(newValue)
		local oldNum = tonumber(label.Text)

		if newNum and oldNum and newNum ~= oldNum then
			local steps = 14
			for i = 1, steps do
				local t = i / steps
				local shown = math.floor(oldNum + (newNum - oldNum) * t + 0.5)
				label.Text = tostring(shown)
				wait(0.02)
			end
		end

		label.Text = tostring(newValue)

		local original = label.TextColor3
		label.TextColor3 = Color3.fromRGB(255, 215, 90)
		TweenService:Create(label, TweenInfo.new(0.6, Enum.EasingStyle.Quad), {
			TextColor3 = original
		}):Play()
	end

	main.BackgroundTransparency = 1
	stroke.Transparency = 1
	TweenService:Create(main, TweenInfo.new(0.4, Enum.EasingStyle.Quart), {BackgroundTransparency = 0.08}):Play()
	TweenService:Create(stroke, TweenInfo.new(0.4), {Transparency = 0.85}):Play()
	TweenService:Create(dim, TweenInfo.new(0.4, Enum.EasingStyle.Quart), {BackgroundTransparency = 0.55}):Play()
	TweenService:Create(mainScale, TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()

	spawn(function()
		wait(0.6)
		local basePos = main.Position
		TweenService:Create(main, TweenInfo.new(2.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
			Position = basePos + UDim2.new(0,0,0,7)
		}):Play()
	end)

	local Xyrax = {}

	function Xyrax.Set(field, value)
		local label
		if field == "Level" then
			label = lvlVal
		elseif field == "Coins" then
			label = coinVal
		elseif field == "Fragments" then
			label = fragVal
		elseif field == "Status" then
			label = statusVal
		elseif field == "Superhuman" then
			label = superhumanVal
		elseif field == "Death Step" then
			label = deathStepVal
		elseif field == "Sharkman Karate" then
			label = sharkmanVal
		elseif field == "Electric Claw" then
			label = electricClawVal
		elseif field == "Dragon Talon" then
			label = dragonTalonVal
		elseif field == "Godhuman" then
			label = godhumanVal
		end

		if label then
			spawn(function()
				animateValue(label, value)
			end)
		end
	end

	function Xyrax.Show()
		main.Visible = true
		dim.Visible = true
		TweenService:Create(main, TweenInfo.new(0.3), {BackgroundTransparency = 0.08}):Play()
		TweenService:Create(dim, TweenInfo.new(0.3), {BackgroundTransparency = 0.55}):Play()
	end

	function Xyrax.Hide()
		TweenService:Create(main, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
		local t = TweenService:Create(dim, TweenInfo.new(0.3), {BackgroundTransparency = 1})
		t:Play()
		t.Completed:Wait()
		main.Visible = false
		dim.Visible = false
	end

	return Xyrax
end

    local Xyrax = XyraxCreateStatusPanel()
    Xyrax.Hide()

    task.spawn(function()
        while gui.Parent do
            local player = Players.LocalPlayer
            local data = player and player:FindFirstChild("Data")
            local level = data and data:FindFirstChild("Level")
            local beli = data and (data:FindFirstChild("Beli") or data:FindFirstChild("Money"))
            local fragments = data and data:FindFirstChild("Fragments")
            local environment = (getgenv and getgenv()) or _G
            local schedulerState = environment.XyraxSchedulerStatus or "Initializing"
            Xyrax.Set("Level", tostring(level and level.Value or 0))
            Xyrax.Set("Coins", tostring(beli and beli.Value or 0))
            Xyrax.Set("Fragments", tostring(fragments and fragments.Value or 0))
            Xyrax.Set("Status", schedulerState)

            -- Same ownership checks the automation itself already relies on
            -- (XyraxAutomation.SuperhumanBought/DeathStepOwned/
            -- OwnsSharkmanKarate, xyraxOwnsTool as fallback where no
            -- dedicated check exists) - reused via XyraxEnvironment since
            -- this loop is defined earlier in the chunk than those locals,
            -- same reason it already reads XyraxSchedulerStatus that way.
            local xyraxAuto = environment.XyraxAutomation
            local ownsTool = environment.xyraxOwnsTool
            local superhumanOwned = (xyraxAuto and xyraxAuto.SuperhumanBought)
                or (ownsTool and ownsTool("superhuman")) or false
            local deathStepOwned = (xyraxAuto and xyraxAuto.DeathStepOwned)
                or (ownsTool and ownsTool("death step")) or false
            local sharkmanOwned = (xyraxAuto and type(xyraxAuto.OwnsSharkmanKarate) == "function"
                and xyraxAuto.OwnsSharkmanKarate()) or false
            local electricClawOwned = (ownsTool and ownsTool("electric claw")) or false
            local dragonTalonOwned = (ownsTool and ownsTool("dragon talon")) or false
            local godhumanOwned = (ownsTool and (ownsTool("godhuman") or ownsTool("god human"))) or false

            Xyrax.Set("Superhuman", superhumanOwned and "✅" or "❌")
            Xyrax.Set("Death Step", deathStepOwned and "✅" or "❌")
            Xyrax.Set("Sharkman Karate", sharkmanOwned and "✅" or "❌")
            Xyrax.Set("Electric Claw", electricClawOwned and "✅" or "❌")
            Xyrax.Set("Dragon Talon", dragonTalonOwned and "✅" or "❌")
            Xyrax.Set("Godhuman", godhumanOwned and "✅" or "❌")

            task.wait(0.25)
        end
    end)

