        function section:Toggle(name, default, callback)
            callback = callback or function() end
            local state = default and true or false
            local row = addControlFrame("Toggle", 34)
            local titleLabel = make("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(10, 0),
                Size = UDim2.new(1, -62, 1, 0),
                Font = Enum.Font.Gotham,
                Text = tostring(name),
                TextColor3 = palette.Text,
                TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Left,
            }, row)
            local switch = make("TextButton", {
                BackgroundColor3 = state and palette.Accent or palette.ToggleOff,
                BorderSizePixel = 0,
                Position = UDim2.new(1, -44, 0.5, -10),
                Size = UDim2.fromOffset(34, 20),
                Text = "",
                AutoButtonColor = false,
            }, row)
            corner(switch, 10)
            local knob = make("Frame", {
                BackgroundColor3 = state and palette.Background or palette.Text,
                BorderSizePixel = 0,
                Position = UDim2.new(state and 1 or 0, state and -18 or 2, 0.5, -8),
                Size = UDim2.fromOffset(16, 16),
            }, switch)
            corner(knob, 8)
            local result = {}
            function result:Update(newState)
                state = newState and true or false
                TweenService:Create(switch, TweenInfo.new(0.12), {BackgroundColor3 = state and palette.Accent or palette.ToggleOff}):Play()
                TweenService:Create(knob, TweenInfo.new(0.12), {
                    Position = UDim2.new(state and 1 or 0, state and -18 or 2, 0.5, -8),
                    BackgroundColor3 = state and palette.Background or palette.Text,
                }):Play()
                callback(state)
            end
            result.Set = result.Update
            switch.Activated:Connect(function()
                result:Update(not state)
            end)
            -- The old library calls the callback during creation only for a
            -- truthy default.  Preserve that initialization behavior.
            if default then
                callback(true)
            end
            return result
        end

        local function createDropdown(name, list, default, callback, multi)
            callback = callback or function() end
            local values = {}
            for _, value in pairs(list or {}) do
                table.insert(values, value)
            end
            local selected = multi and {} or nil
            local row = make("Frame", {
                Name = multi and "MultiDropdown" or "Dropdown",
                BackgroundColor3 = palette.Background,
                BorderSizePixel = 0,
                Size = UDim2.new(1, 0, 0, 31),
                AutomaticSize = Enum.AutomaticSize.Y,
            }, controls)
            corner(row, 5)
            local header = make("TextButton", {
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Size = UDim2.new(1, 0, 0, 31),
                Font = Enum.Font.Gotham,
                Text = tostring(name),
                TextColor3 = palette.Text,
                TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Left,
                AutoButtonColor = false,
            }, row)
            make("UIPadding", {PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10)}, header)
            local arrow = make("TextLabel", {
                BackgroundTransparency = 1,
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -10, 0.5, 0),
                Size = UDim2.fromOffset(14, 20),
                Font = Enum.Font.GothamBold,
                Text = "+",
                TextColor3 = palette.Muted,
                TextSize = 15,
            }, header)
            local options = make("Frame", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(7, 34),
                Size = UDim2.new(1, -14, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                Visible = false,
            }, row)
            make("UIPadding", {PaddingBottom = UDim.new(0, 7)}, options)
            make("UIListLayout", {Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder}, options)
            local open = false
            local result = {}

            local function updateHeader()
                if multi then
                    header.Text = tostring(name) .. " : " .. table.concat(selected, ", ")
                elseif selected ~= nil then
                    header.Text = tostring(name) .. " : " .. tostring(selected)
                else
                    header.Text = tostring(name)
                end
            end

            local function refresh()
                for _, child in pairs(options:GetChildren()) do
                    if child:IsA("TextButton") then
                        child:Destroy()
                    end
                end
                for _, value in ipairs(values) do
                    local option = make("TextButton", {
                        BackgroundColor3 = palette.SurfaceHover,
                        BorderSizePixel = 0,
                        Size = UDim2.new(1, 0, 0, 25),
                        Font = Enum.Font.Gotham,
                        Text = tostring(value),
                        TextColor3 = palette.Text,
                        TextSize = 11,
                        AutoButtonColor = false,
                    }, options)
                    corner(option, 4)
                    option.Activated:Connect(function()
                        if multi then
                            local foundIndex = table.find(selected, value)
                            if foundIndex then
                                table.remove(selected, foundIndex)
                            else
                                table.insert(selected, value)
                            end
                            callback(selected, value)
                        else
                            selected = value
                            callback(value)
                            open = false
                            options.Visible = false
                            arrow.Text = "+"
                        end
                        updateHeader()
                    end)
                end
            end

            function result:Clear()
                table.clear(values)
                if multi then
                    table.clear(selected)
                else
                    selected = nil
                end
                updateHeader()
                refresh()
            end
            function result:Add(value)
                table.insert(values, value)
                refresh()
            end
            function result:TogglePanel(newState)
                open = newState and true or false
                options.Visible = open
                arrow.Text = open and "−" or "+"
            end
            header.Activated:Connect(function()
                result:TogglePanel(not open)
            end)

            -- Match the previous library: a string default is initialized;
            -- table defaults are only visual input until a user selects one.
            if type(default) == "string" and table.find(values, default) then
                selected = multi and {default} or default
                callback(selected)
            end
            updateHeader()
            refresh()
            return result
        end

        function section:Dropdown(name, list, default, callback)
            return createDropdown(name, list, default, callback, false)
        end

        function section:MultiDropdown(name, list, default, callback)
            return createDropdown(name, list, default, callback, true)
        end

