        function section:Slider(text, floor, min, max, default, callback)
            callback = callback or function() end
            local value = default or min or 0
            local row = addControlFrame("Slider", 55)
            make("TextLabel", {
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(10, 4),
                Size = UDim2.new(0.68, 0, 0, 18),
                Font = Enum.Font.Gotham,
                Text = tostring(text),
                TextColor3 = palette.Text,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
            }, row)
            local valueBox = make("TextBox", {
                BackgroundColor3 = palette.SurfaceHover,
                BorderSizePixel = 0,
                Position = UDim2.new(1, -65, 0, 4),
                Size = UDim2.fromOffset(55, 18),
                Font = Enum.Font.Gotham,
                Text = tostring(value),
                TextColor3 = palette.Text,
                TextSize = 11,
                ClearTextOnFocus = false,
            }, row)
            corner(valueBox, 4)
            local bar = make("TextButton", {
                BackgroundColor3 = palette.ToggleOff,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(10, 34),
                Size = UDim2.new(1, -20, 0, 8),
                Text = "",
                AutoButtonColor = false,
            }, row)
            corner(bar, 4)
            local fill = make("Frame", {BackgroundColor3 = palette.Accent, BorderSizePixel = 0, Size = UDim2.new(0, 0, 1, 0)}, bar)
            corner(fill, 4)
            local function setValue(newValue, invoke)
                newValue = math.clamp(tonumber(newValue) or value, min or 0, max or 100)
                if floor then newValue = math.floor(newValue) end
                value = newValue
                valueBox.Text = tostring(value)
                local range = (max or 100) - (min or 0)
                fill.Size = UDim2.new(range > 0 and (value - (min or 0)) / range or 0, 0, 1, 0)
                if invoke then callback(value) end
            end
            bar.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    local ratio = math.clamp((input.Position.X - bar.AbsolutePosition.X) / bar.AbsoluteSize.X, 0, 1)
                    setValue((min or 0) + ((max or 100) - (min or 0)) * ratio, true)
                end
            end)
            valueBox.FocusLost:Connect(function()
                setValue(valueBox.Text, true)
            end)
            setValue(value, false)
            return {Set = function(_, newValue) setValue(newValue, true) end}
        end

        return section
    end

