-- Keep the UI category separate from the actual Tool name used by all legacy
-- combat calls.  We inspect only direct children of Character/Backpack, so
-- this remains cheap even while the farm attack loop is running.
local xyraxWeaponToolTips = {
    ["Melee"] = "Melee",
    ["Sword"] = "Sword",
    ["Gun"] = "Gun",
    ["Blox Fruit"] = "Blox Fruit",
}
local function xyraxFindSelectedWeapon()
    local player = game:GetService("Players").LocalPlayer
    local expectedToolTip = xyraxWeaponToolTips[XyraxAutomation.SelectedWeaponType]
    if not expectedToolTip then
        return nil
    end

    local containers = {player.Character, player:FindFirstChild("Backpack")}
    local preferred = XyraxAutomation.SelectedWeaponType == "Melee"
        and XyraxAutomation.PreferredMeleeAliases
        or nil
    if preferred then
        for _, alias in ipairs(preferred) do
            for _, container in ipairs(containers) do
                if container then
                    local tool = container:FindFirstChild(alias)
                    if tool and tool:IsA("Tool") and tool.ToolTip == expectedToolTip then
                        return tool
                    end
                end
            end
        end
    end

    -- Prefer an already-equipped matching Tool, then a Backpack Tool.  This
    -- prevents a new purchase from being missed merely because the previous
    -- style is temporarily equipped during the scan.
    for _, container in ipairs(containers) do
        if container then
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and tool.ToolTip == expectedToolTip then
                    return tool
                end
            end
        end
    end
    return nil
end

