    end)

    -- The quest UI updates asynchronously.  Without a cooldown, the loop
    -- below can send AbandonQuest/StartQuest every frame while it is updating.
    local lastQuestRequest = 0
    local function requestQuestAction(...)
        if os.clock() - lastQuestRequest < 1 then
            return false
        end

        lastQuestRequest = os.clock()
        return game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer(...)
    end

    -- The current client publishes the authoritative quest state and quest
    -- giver instances through GuideModule (see the Sea 1 client scripts).
    local guideLoaded, GuideModule = pcall(require, game:GetService("ReplicatedStorage"):WaitForChild("GuideModule"))
    local function getGuideQuestData()
        if guideLoaded and type(GuideModule) == "table" and type(GuideModule.Data) == "table" then
            return GuideModule.Data.QuestData
        end
        return nil
    end

    local function findQuestGiver(questName)
        if not guideLoaded or type(GuideModule) ~= "table" or type(GuideModule.Data) ~= "table" or type(GuideModule.Data.NPCList) ~= "table" then
            return nil
        end

        for npc, info in pairs(GuideModule.Data.NPCList) do
            if type(info) == "table" and info.InternalQuestName == questName and typeof(npc) == "Instance" then
                if npc:IsA("BasePart") then
                    return npc
                elseif npc:IsA("Model") then
                    return npc.PrimaryPart or npc:FindFirstChild("HumanoidRootPart") or npc:FindFirstChildWhichIsA("BasePart")
                end
            end
        end
        return nil
    end

    -- Update 30's Escape from Alcatraz event can spawn an Escaped Prisoner
    -- alongside the normal PrisonerQuest enemy.  Its model is registered in
    -- BonusMoments and cannot take damage before an unrelated dialogue, so it
    -- must never be selected as Auto Farm's level target.
    local xyraxBonusMomentsLoaded, xyraxBonusMomentsController = pcall(require, game.ReplicatedStorage.Controllers:WaitForChild("BonusMomentsController"))
    local function xyraxIsEscapedPrisoner(enemy)
        if Mon ~= "Prisoner" or not xyraxBonusMomentsLoaded then
            return false
        end
        local getLoadedMoments = xyraxBonusMomentsController.GetLoadedMoments
        local loadedMoments = type(getLoadedMoments) == "function" and getLoadedMoments() or nil
        local alcatraz = type(loadedMoments) == "table" and loadedMoments["Escape from Alcatraz"]
        local prisoners = alcatraz and alcatraz.MiscData and alcatraz.MiscData.Prisoners
        if type(prisoners) ~= "table" then
            return false
        end
        for _, prisonerData in pairs(prisoners) do
            if type(prisonerData) == "table" and prisonerData.Model == enemy then
                return true
            end
        end
        return false
    end

    -- Escape from Alcatraz starts its forced "Confront" dialogue merely by
    -- being within 16 studs of an event prisoner; it does not require an
    -- attack.  Keep Auto Farm well outside that trigger radius whenever its
    -- normal level target is Prisoner.
    local function xyraxIsEscapeConfrontRisk(position, radius)
        if Mon ~= "Prisoner" or not xyraxBonusMomentsLoaded then
            return false
        end
        local getLoadedMoments = xyraxBonusMomentsController.GetLoadedMoments
        local loadedMoments = type(getLoadedMoments) == "function" and getLoadedMoments() or nil
        local alcatraz = type(loadedMoments) == "table" and loadedMoments["Escape from Alcatraz"]
        local prisoners = alcatraz and alcatraz.MiscData and alcatraz.MiscData.Prisoners
        if type(prisoners) ~= "table" then
            return false
        end
        for _, prisonerData in pairs(prisoners) do
            local model = type(prisonerData) == "table" and prisonerData.Model
            local eventRoot = model and (model.PrimaryPart or model:FindFirstChild("HumanoidRootPart"))
            if eventRoot and eventRoot:IsA("BasePart")
                and (eventRoot.Position - position).Magnitude <= (radius or 40) then
                return true
            end
        end
        return false
    end

    -- A replicated enemy can occasionally look alive but reject every hit.
    -- Do not leave the character hovering over that "ghost" forever: only
    -- start this timer once we are actually in combat range, and temporarily
    -- skip the model if its HP never changes.
    XyraxAutomation.DamageWatchRecords = XyraxAutomation.DamageWatchRecords or setmetatable({}, {__mode = "k"})
    XyraxAutomation.DamageIgnoredUntil = XyraxAutomation.DamageIgnoredUntil or setmetatable({}, {__mode = "k"})
    XyraxAutomation.DamageBlockedBosses = XyraxAutomation.DamageBlockedBosses or {}
    -- A boss that rejects two full attack windows is usually a stale/ghost
    -- model, not a normal cooldown.  Keep it out of the scheduler long
    -- enough for Farm Level to remain stable instead of bouncing back.
    XyraxAutomation.DamageBossBlockSeconds = 1800

    XyraxAutomation.DamageDebug = function(message)
        if XyraxAutomation.DamageWatchDebug ~= false then
            print("[BfRef DamageWatch] " .. message)
        end
    end

    XyraxAutomation.IsDamageIgnored = function(enemy)
        local untilAt = enemy and XyraxAutomation.DamageIgnoredUntil[enemy]
        if untilAt and os.clock() < untilAt then
            return true
        end
        if enemy and untilAt then
            XyraxAutomation.DamageIgnoredUntil[enemy] = nil
        end
        return false
    end

    XyraxAutomation.IgnoreDamageTarget = function(enemy, context, seconds)
        if not enemy then
            return
        end
        local hold = seconds or 20
        XyraxAutomation.DamageIgnoredUntil[enemy] = os.clock() + hold
        XyraxAutomation.DamageWatchRecords[enemy] = nil
        XyraxAutomation.DamageDebug(context .. " | " .. enemy.Name .. " HP did not change; skipping this target for " .. hold .. "s")
    end

    XyraxAutomation.DamageBossBlocked = function(key)
        local untilAt = key and XyraxAutomation.DamageBlockedBosses[key]
        if untilAt and os.clock() < untilAt then
            return true
        end
        if key and untilAt then
            XyraxAutomation.DamageBlockedBosses[key] = nil
        end
        return false
    end

    XyraxAutomation.BlockDamageBoss = function(key, context, seconds)
        local hold = seconds or XyraxAutomation.DamageBossBlockSeconds or 1800
        XyraxAutomation.DamageBlockedBosses[key] = os.clock() + hold
        XyraxAutomation.DamageDebug(context .. " | no HP change after retry; yielding this boss for " .. hold .. "s")
    end

    -- Returns "ok", "retry", or "abandon".  `retries` is one for bosses
    -- (re-equip/reposition once) and zero for regular mobs (pick another).
    XyraxAutomation.WatchDamage = function(enemy, context, graceSeconds, retries)
        local humanoid = enemy and enemy:FindFirstChild("Humanoid")
        local enemyRoot = enemy and enemy:FindFirstChild("HumanoidRootPart")
        local character = game:GetService("Players").LocalPlayer.Character
        local playerRoot = character and character:FindFirstChild("HumanoidRootPart")
        if not (humanoid and enemyRoot and playerRoot) then
            return "ok"
        end
        if (playerRoot.Position - enemyRoot.Position).Magnitude > 75 then
            return "ok"
        end

        local now = os.clock()
        local record = XyraxAutomation.DamageWatchRecords[enemy]
        if not record or record.Humanoid ~= humanoid or record.Context ~= context then
            XyraxAutomation.DamageWatchRecords[enemy] = {
                Humanoid = humanoid,
                Context = context,
                HP = humanoid.Health,
                LastDamageAt = now,
                Failures = 0,
                Verified = false,
            }
            XyraxAutomation.DamageDebug(context .. " | watching " .. enemy.Name .. " (HP " .. math.floor(humanoid.Health) .. ")")
            return "ok"
        end

        if humanoid.Health < record.HP then
            record.HP = humanoid.Health
            record.LastDamageAt = now
            record.Failures = 0
            if not record.Verified then
                record.Verified = true
                XyraxAutomation.DamageDebug(context .. " | damage confirmed on " .. enemy.Name)
            end
            return "ok"
        end

        if now - record.LastDamageAt < (graceSeconds or 6) then
            return "ok"
        end

        record.Failures = record.Failures + 1
        record.LastDamageAt = now
        if record.Failures <= (retries or 0) then
            XyraxAutomation.DamageDebug(context .. " | " .. enemy.Name .. " took no damage for " .. math.floor(graceSeconds or 6) .. "s; resetting combat (retry " .. record.Failures .. ")")
            return "retry"
        end
        return "abandon"
    end

    XyraxAutomation.ResetDamageCombat = function()
        StartBring = false
        local tween = _G.TweenCache
        if tween and tween.PlaybackState == Enum.PlaybackState.Playing then
            pcall(function()
                tween:Cancel()
            end)
        end
    end

    -- Black Leg is the runtime Tool name for Dark Step (confirmed by the
    -- current Moveset dump).  Keep its flame skill refreshed independently
    -- of Farm/Boss state, but never auto-equip it over a selected Sword/Gun.
    XyraxAutomation.DarkStepVNextAt = XyraxAutomation.DarkStepVNextAt or 0
    XyraxAutomation.TryDarkStepV = function(context, enemy)
        if AutoSaber and _G.XyraxSaberLockedTool then
            return false
        end
        local character = game:GetService("Players").LocalPlayer.Character
        local playerRoot = character and character:FindFirstChild("HumanoidRootPart")
        local enemyRoot = enemy and enemy:FindFirstChild("HumanoidRootPart")
        if not (character and playerRoot) then
            return false
        end
        if enemyRoot and (playerRoot.Position - enemyRoot.Position).Magnitude > 75 then
            return false
        end

        local blackLegTool = nil
        for _, tool in ipairs(character:GetChildren()) do
            if tool:IsA("Tool") and tool.ToolTip == "Melee" then
                local name = string.lower(tool.Name)
                if string.find(name, "black leg", 1, true)
                    or string.find(name, "dark step", 1, true)
                    or string.find(name, "black step", 1, true) then
                    blackLegTool = tool
                    break
                end
            end
        end
        local mastery = blackLegTool and blackLegTool:FindFirstChild("Level")
        local masteryValue = mastery and mastery.Value or 0
        if not blackLegTool
            or masteryValue < 150
            or os.clock() < XyraxAutomation.DarkStepVNextAt then
            return false
        end

        XyraxAutomation.DarkStepVNextAt = os.clock() + 15
        local input = game:GetService("VirtualInputManager")
        input:SendKeyEvent(true, Enum.KeyCode.V, false, game)
        task.delay(0.05, function()
            input:SendKeyEvent(false, Enum.KeyCode.V, false, game)
        end)
        print("[BfRef DarkStep] V sent | " .. tostring(context))
        return true
    end

    -- This is intentionally a single guarded worker.  Re-executing the hub
    -- reuses XyraxAutomation, so it cannot create a second V loop per client.
    if not XyraxAutomation.DarkStepVLoopStarted then
        XyraxAutomation.DarkStepVLoopStarted = true
        task.spawn(function()
            while XyraxAutomation.DarkStepVLoopStarted do
                task.wait(0.5)
                XyraxAutomation.TryDarkStepV("15 second refresh")
            end
        end)
    end

    -- Enemies are named like "Bandit [Lv. 5]", while CheckQuest stores just
    -- "Bandit" in Mon.  Match the base name so Auto Farm can find its target.
    local function isQuestTarget(enemy)
        if not enemy or not enemy:IsA("Model") or type(Mon) ~= "string" then
            return false
        end

        local baseName = enemy.Name:match("^(.-)%s*%[") or enemy.Name
        local targetRoot = enemy:FindFirstChild("HumanoidRootPart")
        if baseName == Mon and targetRoot and CFrameMon
            and (Mon == "Ship Deckhand" or Mon == "Ship Engineer"
                or Mon == "Ship Steward" or Mon == "Ship Officer")
            and (targetRoot.Position - CFrameMon.Position).Magnitude > 5000 then
            -- Same wrong-zone duplicate the EnemySpawns marker fix already
            -- handles (getQuestSpawnCFrame, ~BfRef.lua:6784) - this time it
            -- is a live "Ship X" Model in Workspace.Enemies itself, not just
            -- a spawn marker, sitting in the same far-away zone (confirmed
            -- live: tag "target:Ship Deckhand" reproduced the identical
            -- ~32,600-stud round-trip after the marker fix). Same 5000-stud
            -- threshold, same reasoning (ship's own CFrameMon cluster is
            -- <=~700 studs wide). Reject it here so Farm Level just keeps
            -- waiting at the real spawn point (hasQuestTarget() below stays
            -- false) until the genuine nearby enemy streams in, instead of
            -- treating this wrong-zone one as a valid target.
            if os.clock() - (XyraxCursedShipWrongEnemyLastLoggedAt or 0) > 5 then
                XyraxCursedShipWrongEnemyLastLoggedAt = os.clock()
                print("[CursedShip] Rejected wrong-zone enemy instance")
            end
            return false
        end
        return baseName == Mon and not XyraxAutomation.IsDamageIgnored(enemy) and not xyraxIsEscapedPrisoner(enemy)
            -- Do not hover above a normal Prisoner that spawned beside an
            -- Escape-event prisoner: physical proximity alone opens Confront.
            and not (targetRoot and xyraxIsEscapeConfrontRisk(targetRoot.Position, 40))
    end

    local function hasQuestTarget()
        for _, enemy in pairs(game:GetService("Workspace").Enemies:GetChildren()) do
            if isQuestTarget(enemy) and not XyraxAutomation.IsDamageIgnored(enemy) and enemy:FindFirstChild("Humanoid") and enemy:FindFirstChild("HumanoidRootPart") and enemy.Humanoid.Health > 0 then
                return true
            end
        end
        return false
    end

    -- Update 30 exposes current mob spawn markers here.  Use them instead of
    -- relying solely on old hard-coded coordinates, so Auto Farm approaches a
    -- valid streamed spawn even if the map layout changes.
    local function getQuestSpawnCFrame()
        local worldOrigin = workspace:FindFirstChild("_WorldOrigin")
        local enemySpawns = worldOrigin and worldOrigin:FindFirstChild("EnemySpawns")
        local character = game.Players.LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local nearestSpawn, nearestDistance

        if enemySpawns and type(Mon) == "string" then
            for _, marker in pairs(enemySpawns:GetChildren()) do
                if marker:IsA("BasePart") then
                    local markerName = marker.Name:match("^(.-)%s*%[") or marker.Name
                    if markerName == Mon and not xyraxIsEscapeConfrontRisk(marker.Position, 40) then
                        local distance = root and (root.Position - marker.Position).Magnitude or 0
                        if not nearestSpawn or distance < nearestDistance then
                            nearestSpawn = marker
                            nearestDistance = distance
                        end
                    end
                end
            end
        end

        if nearestSpawn then
            -- Cursed Ship interior targets (Ship Deckhand/Engineer/Steward/
            -- Officer) share this same _WorldOrigin.EnemySpawns folder with a
            -- same-named marker that sits in a completely different zone -
            -- confirmed live via CursedShipEntranceDebug at ~32,600-32,645
            -- studs from CFrameMon, while the ship's own 4 CFrameMon points
            -- are all within ~700 studs of each other (BfRef.lua:834-869).
            -- Picking that wrong marker drags Farm Level back out of the
            -- ship every time the live enemy hasn't streamed in yet.  Reject
            -- it ONLY for these 4 names, only when the marker is far past
            -- the ship's own interior spread - 5000 studs gives a ~7x
            -- margin above that spread and is still two orders of magnitude
            -- below the wrong marker's real distance, so this can only ever
            -- reject a marker that is genuinely in a different zone.  Once a
            -- live "Ship X" enemy actually streams in, hasQuestTarget()
            -- above already returns true and this function is never called
            -- at all - this only ever affects the "no live enemy yet"
            -- fallback path.
            local isCursedShipMon = Mon == "Ship Deckhand" or Mon == "Ship Engineer"
                or Mon == "Ship Steward" or Mon == "Ship Officer"
            if isCursedShipMon and CFrameMon
                and (nearestSpawn.Position - CFrameMon.Position).Magnitude > 5000 then
                if os.clock() - (XyraxCursedShipWrongSpawnLastLoggedAt or 0) > 5 then
                    XyraxCursedShipWrongSpawnLastLoggedAt = os.clock()
                    print("[CursedShip] Rejected wrong-zone spawn marker")
                end
                nearestSpawn = nil
            end
        end

        if nearestSpawn then
            -- Stand just above the marker so the client streams the active
            -- enemy Model into Workspace.Enemies without clipping into terrain.
            return nearestSpawn.CFrame * CFrame.new(0, 20, 0), "EnemySpawns"
        end
        if Mon == "Prisoner" and xyraxIsEscapeConfrontRisk(CFrameMon.Position, 40) then
            -- All known Prisoner markers are inside the event safety radius.
            -- Waiting is preferable to walking into a forced dialogue.
            return nil, "Escape from Alcatraz safety hold"
        end
        return CFrameMon, "hardcoded fallback"
    end

    -- Auto Farm used to recreate the same Tween every frame while waiting for
    -- a spawn.  `topos` moves through one shared proxy part, so those repeated
    -- Tweens can fight each other and leave the character suspended in air.
    -- Keep the original destination/TP method, but only refresh a still-moving
    -- destination at a controlled interval.
    local xyraxFarmMoveTag = nil
    local xyraxFarmMoveAt = 0
    local function xyraxFarmMove(destination, tag)
        local character = game.Players.LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not (root and destination) then
            return
        end

        local targetCFrame = typeof(destination) == "CFrame" and destination
            or (typeof(destination) == "Vector3" and CFrame.new(destination))
            or (destination.CFrame)
        if not targetCFrame or (root.Position - targetCFrame.Position).Magnitude <= 12 then
            return
        end

        local currentTween = _G.TweenCache
        local tweenPlaying = currentTween and currentTween.PlaybackState == Enum.PlaybackState.Playing
        local now = os.clock()
        if tag ~= xyraxFarmMoveTag or not tweenPlaying or now - xyraxFarmMoveAt >= 0.8 then
            xyraxFarmMoveTag = tag
            xyraxFarmMoveAt = now
            -- TEMP DEBUG (TransitionDebug): every real TP1 call this
            -- function makes, tagged with ActiveJob/_G.AutoFarm at that
            -- instant.  If this keeps firing with ActiveJob no longer
            -- "Farm Level", Farm's own loop is still driving the shared
            -- tween proxy after the scheduler switched jobs.  Remove once
            -- diagnosed.
            print(string.format(
                "[BfRef TransitionDebug] xyraxFarmMove->TP1 | t=%.2f tag=%s ActiveJob=%s AutoFarm=%s",
                now, tostring(tag), tostring(XyraxAutomation and XyraxAutomation.ActiveJob),
                tostring(_G.AutoFarm)))
            TP1(targetCFrame)
            return _G.TweenCache
        end
    end

    -- The five Saber Jungle plates used direct HumanoidRootPart.CFrame writes.
    -- Move through the same TP1 -> topos Tween route as Auto Farm instead,
    -- while waiting for each button before continuing to the next one.
    local xyraxSaberPlateMoveTag = nil
    local xyraxSaberPlateMoveAt = 0
    local function xyraxTweenSaberPlate(destination, plateName)
        while AutoSaber do
            local character = game.Players.LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if not root then
                return false
            end
            if (root.Position - destination.Position).Magnitude <= 4 then
                return true
            end

            local currentTween = _G.TweenCache
            local tweenPlaying = currentTween and currentTween.PlaybackState == Enum.PlaybackState.Playing
            local now = os.clock()
            if plateName ~= xyraxSaberPlateMoveTag or not tweenPlaying or now - xyraxSaberPlateMoveAt >= 0.8 then
                xyraxSaberPlateMoveTag = plateName
                xyraxSaberPlateMoveAt = now
                TP1(destination)
            end
            task.wait()
        end
        return false
    end

    local function xyraxPressSaberPlate(button, plateName)
        if not xyraxTweenSaberPlate(button.CFrame, plateName) then
            return false
        end

        -- The current Jungle buttons expose TouchTransmitter/TouchInterest
        -- (verified in the map dump).  Tweening near a button while BodyClip
        -- is active is not guaranteed to emit a physical touch, so fire its
        -- touch pair once after arrival.  This is not a quest Remote.
        local character = game.Players.LocalPlayer.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if root and type(firetouchinterest) == "function" then
            pcall(function()
                firetouchinterest(root, button, 0)
                task.wait(0.1)
                firetouchinterest(root, button, 1)
            end)
        end
        task.wait(0.35)
        return AutoSaber
    end

    -- Blox Fruits now renders normal quests in PlayerGui.TrackedQuestFrame,
    -- while older servers use PlayerGui.Main.Quest.  Looking only at the old
    -- frame makes Auto Farm believe it has no quest and stay at the quest NPC.
    local function guiContainsText(gui, text)
        if not gui or type(text) ~= "string" then
            return false
        end

        for _, descendant in pairs(gui:GetDescendants()) do
            if (descendant:IsA("TextLabel") or descendant:IsA("TextButton")) and string.find(descendant.Text, text, 1, true) then
                return true
            end
        end
        return false
    end

        spawn(function()
