                    local legacyTitle = legacyQuestVisible and legacyQuest.Container.QuestTitle.Title.Text or ""
                    local legacyQuestMatches = legacyQuestVisible and type(NameMon) == "string" and string.find(legacyTitle, NameMon, 1, true) ~= nil

                    local trackedQuest = playerGui:FindFirstChild("TrackedQuestFrame")
                    local trackedQuestVisible = trackedQuest and trackedQuest.Parent ~= nil
                    local trackedQuestMatches = trackedQuestVisible and guiContainsText(trackedQuest, NameMon)
                    local guideQuestData = getGuideQuestData()
                    local guideQuestVisible = type(guideQuestData) == "table"
                    local guideQuestMatches = guideQuestVisible and ((type(guideQuestData.Task) == "table" and guideQuestData.Task[NameMon] ~= nil) or guideQuestData.InternalQuestName == NameQuest)
                    local questVisible = legacyQuestVisible or trackedQuestVisible or guideQuestVisible
                    local hasCorrectQuest = legacyQuestMatches or trackedQuestMatches or guideQuestMatches
                    local root = game.Players.LocalPlayer.Character and game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")

