			    if (game.Players.LocalPlayer.Character.HumanoidRootPart.Position - questPosition.Position).Magnitude <= 20 then
                            if tweenQuest then tweenQuest:Cancel() end
				    local startQuestResult = requestQuestAction("StartQuest", NameQuest, LevelQuest)
				    print("[BfRef QuestDebug] START QUEST FIRED | NameQuest=" .. tostring(NameQuest)
					.. " LevelQuest=" .. tostring(LevelQuest) .. " result=" .. tostring(startQuestResult))
                        end
                    elseif hasCorrectQuest then
                        if string.find(legacyTitle, "kissed") then
                            for i,v in pairs(game:GetService("Workspace").Enemies:GetChildren()) do
                                if string.find(v.Name,"kissed Warrior") then
                                    if v:FindFirstChild("HumanoidRootPart") and v:FindFirstChild("Humanoid") and v.Humanoid.Health > 0 then
