                                        TP1(game:GetService("ReplicatedStorage"):FindFirstChild(Mon).HumanoidRootPart.CFrame * CFrame.new(0,20,0))
                                    end
                                end
                            end
                        else
                            local targetFound = hasQuestTarget()
                            if targetFound then
                                for i,v in pairs(game:GetService("Workspace").Enemies:GetChildren()) do
                                    if v:FindFirstChild("HumanoidRootPart") and v:FindFirstChild("Humanoid") and v.Humanoid.Health > 0 then
                                            if isQuestTarget(v) and not XyraxAutomation.IsDamageIgnored(v) then
                                            if hasCorrectQuest then
                                                local targetToken = _G.XyraxFarmTargetToken
                                                local targetRefreshAt = 0
                                                repeat task.wait()
                                                -- Re-evaluate the level quest a few times per second
                                                -- while fighting.  If this enemy grants a level that
                                                -- changes Gorilla -> Pirate (or any later band), the
                                                -- old repeat loop exits immediately.
                                                if os.clock() >= targetRefreshAt then
