                                                    CheckQuest()
                                                    if targetToken ~= _G.XyraxFarmTargetToken then
                                                        break
                                                    end
                                                end
                                                EquipWeapon(_G.SelectWeapon)
                                                AutoHaki()
                                                PosMon = v.HumanoidRootPart.CFrame
                                                xyraxFarmMove(v.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0), "target:" .. v.Name)
                                                XyraxAutomation.TryDarkStepV("Farm Level", v)
                                                local damageState = XyraxAutomation.WatchDamage(v, "Farm Level", 6, 0)
                                                if damageState == "abandon" then
                                                    XyraxAutomation.IgnoreDamageTarget(v, "Farm Level", 20)
                                                    XyraxAutomation.ResetDamageCombat()
                                                    break
                                                end
                                                    v.HumanoidRootPart.CanCollide = false
                                                    v.Humanoid.WalkSpeed = 0
                                                    v.Head.CanCollide = false
                                                    StartBring = true
                                                    MonFarm = v.Name
                                                    game:GetService'VirtualUser':CaptureController()
                                                    game:GetService'VirtualUser':Button1Down(Vector2.new(1280, 672))
                                                until not _G.AutoFarm or targetToken ~= _G.XyraxFarmTargetToken
                                                    or v.Humanoid.Health <= 0 or not v.Parent or XyraxAutomation.IsDamageIgnored(v)
                                            else
                                                StartBring = false
                                                requestQuestAction("AbandonQuest")
                                            end
                                        end
                                    end
                                end
                            else
                                StartBring = false
                                -- A defeated enemy may have been dragged far
                                -- from its natural spawn.  Wait at the live
                                -- EnemySpawns marker instead of above its last
                                -- position, so the next wave streams reliably.
                                local spawnCFrame, spawnSource = getQuestSpawnCFrame()
                                -- A spawn marker and the ReplicatedStorage
                                -- template are two different destinations.
