local function xyraxFindLiveEnemyByNames(names)
    for _, name in ipairs(names) do
        local enemy = xyraxFindLiveEnemy(name)
        if enemy then
            return enemy
        end
    end
    return nil
end

-- A distant active boss may be moved under ReplicatedStorage by Streaming
-- while retaining its Humanoid, HP and HumanoidRootPart.  This is different
-- from a name-only asset: require all three runtime pieces and cache each
-- scan for one second so the scheduler never traverses ReplicatedStorage on
-- every tick.
local function xyraxFindDistantEnemyByNames(names)
    local now = os.clock()
    local replicatedStorage = game:GetService("ReplicatedStorage")
    local snapshot = XyraxAutomation.DistantBossScan
    if not snapshot or now - snapshot.At >= 3 then
        snapshot = {At = now, Models = {}}
        -- One complete scan serves every enabled boss job for three seconds.
        -- This prevents Pole/Saw/Warden/Trident from each doing their own
        -- expensive ReplicatedStorage:GetDescendants() traversal.
        for _, model in ipairs(replicatedStorage:GetDescendants()) do
            if model:IsA("Model") then
                local baseName = model.Name:match("^(.-)%s*%[") or model.Name
                local humanoid = model:FindFirstChild("Humanoid")
                local root = model:FindFirstChild("HumanoidRootPart")
                if humanoid and humanoid:IsA("Humanoid")
                    and root and root:IsA("BasePart") and humanoid.Health > 0 then
                    snapshot.Models[baseName] = model
                end
            end
        end
        XyraxAutomation.DistantBossScan = snapshot
    end

    for _, expectedName in ipairs(names) do
        local model = snapshot.Models[expectedName]
        local humanoid = model and model:FindFirstChild("Humanoid")
        local root = model and model:FindFirstChild("HumanoidRootPart")
        if model and model:IsDescendantOf(replicatedStorage)
            and humanoid and humanoid:IsA("Humanoid")
            and root and root:IsA("BasePart") and humanoid.Health > 0 then
            return model, "ReplicatedStorage"
        end
    end
    return nil, nil
end

local function xyraxFindEnemyByNames(names)
    local live = xyraxFindLiveEnemyByNames(names)
    if live then
        return live, "Workspace"
    end
    return xyraxFindDistantEnemyByNames(names)
end

