    Pole = {Job = "Auto Pole", Aliases = {"Lightning God", "Thunder God"}, FastAttack = false},
    Saw = {Job = "Auto Saw", Aliases = {"The Saw"}, FastAttack = true},
    -- Current First Sea map spawns Warden [Lv. 230] [Boss].  Keep Chief
    -- Warden as a legacy alias, but do not require the removed model name.
    Warden = {Job = "Auto Warden", Aliases = {"Warden", "Chief Warden"}, FastAttack = false},
    Trident = {Job = "Auto Trident", Aliases = {"Fishman Lord"}, FastAttack = false},
}

local function xyraxFindSea1WeaponBoss(key)
    local spec = xyraxSea1WeaponBosses[key]
    if not spec or XyraxAutomation.DamageBossBlocked("Weapon:" .. tostring(key)) then
        return nil, nil
    end
    return xyraxFindEnemyByNames(spec.Aliases)
end

local function xyraxGetSea1ProgressionBoss()
    if not World1 then
        return nil, nil
    end
    local player = game:GetService("Players").LocalPlayer
    local levelValue = player:FindFirstChild("Data") and player.Data:FindFirstChild("Level")
    local level = levelValue and levelValue.Value or 0
    for _, boss in ipairs(xyraxSea1ProgressionBosses) do
        if level >= boss.MinLevel and level <= boss.MaxLevel then
            if XyraxAutomation.DamageBossBlocked("Progression:" .. boss.Label) then
                return nil, nil
            end
            local enemy, source
            local defeated = XyraxAutomation.ProgressionBossDefeated
            if boss.StreamingAware and defeated and defeated.Label == boss.Label then
                -- ReplicatedStorage keeps a full Sky Warlord placeholder even
                -- after the live boss dies.  Ignore that placeholder until a
                -- fresh, living Workspace enemy proves the boss respawned.
                enemy = xyraxFindLiveEnemyByNames(boss.EnemyNames)
                if enemy then
                    XyraxAutomation.ProgressionBossDefeated = nil
                    source = "Workspace"
                else
                    return nil, nil
                end
            elseif boss.StreamingAware then
                enemy, source = xyraxFindEnemyByNames(boss.EnemyNames)
            else
                enemy = xyraxFindLiveEnemyByNames(boss.EnemyNames)
                source = enemy and "Workspace" or nil
            end
            if enemy then
                if boss.StreamingAware then
                    XyraxAutomation.ProgressionStreamLock = {
                        Label = boss.Label,
                        SeenAt = os.clock(),
                    }
                end
                return boss, enemy, source
            end

            -- Do not cancel an Upper-Sky boss route just because Streaming
            -- removed its model for one scheduler pass.  A true despawn still
            -- returns to Farm Level shortly after this bounded hold expires.
            local streamLock = XyraxAutomation.ProgressionStreamLock
            if boss.StreamingAware and streamLock and streamLock.Label == boss.Label
                and os.clock() - (streamLock.SeenAt or 0) < (boss.StreamHoldSeconds or 15) then
                return boss, nil, "StreamHold"
            end
            return nil, nil
        end
    end
    return nil, nil
end

