local xyraxSuperhumanBuyRetryAt = {}

local function xyraxFindSuperhumanTool(stage)
    local player = game:GetService("Players").LocalPlayer
    local containers = {player.Character, player:FindFirstChild("Backpack")}
    for _, container in ipairs(containers) do
        if container then
            for _, tool in pairs(container:GetChildren()) do
                if tool:IsA("Tool") then
                    local lowerName = string.lower(tool.Name)
                    for _, alias in ipairs(stage.Aliases) do
                        if lowerName == string.lower(alias) then
                            return tool
                        end
                    end
                end
            end
        end
    end
    return nil
end

-- Reads Mastery for a Fighting Style from its already-replicated
-- ItemReplicationService cache (KEYS.MASTERY), confirmed live (standalone
-- test): a local read of the LocalPlayer's own UserReplicationCache, no
-- remote fired, works regardless of whether the style is currently equipped.
-- Uses the same xyraxInventoryService/xyraxInventoryKeys this file already
-- loads for fruit-storage ownership - reused here, not reloaded.  Returns
-- nil (not a number) when the read fails or the style has no Mastery entry
-- yet (never owned), so callers can fall back to Tool.Level.
local function xyraxGetReplicatedMastery(stage)
    if not (xyraxInventoryServiceLoaded and xyraxInventoryKeysLoaded and stage.ItemId) then
        return nil
    end
    -- GetItems returns a table of {ItemId=..., Value=...} entries, not a
    -- table already keyed by ItemId - must scan entry.ItemId like
    -- XyraxAutomation.OwnsReplicatedItem does for IS_OWNED, not index
    -- straight into it.
    local bulkOk, bulkItems = pcall(function()
        return xyraxInventoryService:GetItems(xyraxInventoryKeys.MASTERY)
    end)
    if bulkOk and type(bulkItems) == "table" then
        for _, entry in pairs(bulkItems) do
            if type(entry) == "table" and entry.ItemId == stage.ItemId and type(entry.Value) == "number" then
                return entry.Value
            end
        end
    end
    local ok, value = pcall(function()
        return xyraxInventoryService:ReadItem(stage.ItemId, xyraxInventoryKeys.MASTERY, nil)
    end)
    if ok and type(value) == "number" then
        return value
    end
    return nil
end

-- The Lightning Bolt route needs an actual fighting style, but must not care
-- which one the account owns.  Every valid fighting-style Tool has
-- ToolTip == "Melee" (Combat, Black Leg, Dark Step, Electric, etc.).
local function xyraxFindCloudMeleeTool()
    local player = game:GetService("Players").LocalPlayer
    for _, container in ipairs({player.Character, player:FindFirstChild("Backpack")}) do
        if container then
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and tool.ToolTip == "Melee" then
                    return tool
                end
            end
        end
    end
    return nil
end

local function xyraxGetBeli()
    local player = game:GetService("Players").LocalPlayer
    local data = player:FindFirstChild("Data")
    local beli = data and (data:FindFirstChild("Beli") or data:FindFirstChild("Money"))
    return beli and beli.Value or 0
end

local function xyraxGetFragments()
    local player = game:GetService("Players").LocalPlayer
    local data = player:FindFirstChild("Data")
    local fragments = data and data:FindFirstChild("Fragments")
    return fragments and fragments.Value or 0
end

-- Electric's current dialogue requires a real Lightning Bolt before the
-- purchase can succeed.  Keep this check cheap and tolerant of the three
-- places the game can expose a material (Character, Backpack, or the
-- replicated Items inventory after a rejoin).
XyraxAutomation.LightningBolt = XyraxAutomation.LightningBolt or {
    HasAt = 0,
    Has = false,
    QuestAt = 0,
    QuestState = nil,
    ScanAt = 0,
    Target = nil,
    TargetUntil = 0,
    CloudHitAt = 0,
    CloudHitCount = 0,
    BoltCheckAt = 0,
    CloudAttackDebugAt = 0,
    LastDebug = nil,
    MoveAt = 0,
    MoveKey = nil,
    Scientist = nil,
    ScientistScanAt = 0,
    ScientistRetryAt = 0,
    -- Verified by the live ReplicatedStorage.NPCs.Mad Scientist template.
    ScientistDock = CFrame.new(-4628.888, 12.130, -355.718),
    Delivered = false,
}

function xyraxHasLightningBolt()
    local state = XyraxAutomation.LightningBolt
    local now = os.clock()
    if now - (state.HasAt or 0) < 3 then
        return state.Has == true
    end

    local player = game:GetService("Players").LocalPlayer
    local aliases = {"Lightning Bolt", "LightningBolt"}
    local found = false
    for _, container in ipairs({player.Character, player:FindFirstChild("Backpack")}) do
        if container then
            for _, item in ipairs(container:GetChildren()) do
                local itemName = string.lower(item.Name)
                if item:IsA("Tool") and (itemName == "lightning bolt" or itemName == "lightningbolt") then
                    found = true
                    break
                end
            end
        end
        if found then break end
    end

    if not found and type(XyraxAutomation.OwnsReplicatedItem) == "function" then
        local ok, owned = pcall(function()
            return XyraxAutomation.OwnsReplicatedItem(aliases)
        end)
        found = ok and owned == true
    end
    -- Material entries can arrive before ItemReplicationService exposes its
    -- ownership cache.  The dialogue's own inventory shape still includes
    -- the display name/Material id, so use it as a throttled fallback.
    if not found then
        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
        local commF = remotes and remotes:FindFirstChild("CommF_")
        local ok, inventory = pcall(function()
            return commF and commF:InvokeServer("getInventory")
        end)
        if ok and type(inventory) == "table" then
            for _, entry in pairs(inventory) do
                if type(entry) == "table" then
                    local label = string.lower(tostring(entry.Name or entry.ItemName or entry.ItemId or entry.Id or ""))
                    if string.find(label, "lightning bolt", 1, true) then
                        found = true
                        break
                    end
                end
            end
        end
    end
    state.HasAt = now
    state.Has = found
    return found
end

function xyraxFindMadScientist()
    local state = XyraxAutomation.LightningBolt
    if os.clock() - (state.ScientistScanAt or 0) < 1 then
        return nil
    end
    state.ScientistScanAt = os.clock()

    -- Prefer the streamed NPC when it is present, but never treat a far-away
    -- streamed map as proof that the NPC does not exist.  The template is
    -- always available in ReplicatedStorage.NPCs and provides the same live
    -- position for the travel route until Workspace streams it in.
    local scientist = workspace:FindFirstChild("Mad Scientist", true)
    if scientist and scientist:IsDescendantOf(workspace) then
        state.Scientist = scientist
        state.ScientistSource = "Workspace"
        return scientist
    end

    local replicatedStorage = game:GetService("ReplicatedStorage")
    local npcs = replicatedStorage:FindFirstChild("NPCs")
    scientist = npcs and npcs:FindFirstChild("Mad Scientist", true)
    if scientist then
        state.Scientist = scientist
        state.ScientistSource = "ReplicatedStorage"
        return scientist
    end

    state.Scientist = nil
    state.ScientistSource = nil
    return nil
end

function xyraxEnsureLightningQuest(canAccept)
    local state = XyraxAutomation.LightningBolt
    local now = os.clock()
    if not canAccept and now - (state.QuestAt or 0) < 8 then
        return state.QuestState
    end
    state.QuestAt = now
    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
    local commF = remotes and remotes:FindFirstChild("CommF_")
    if not commF then return nil end
    local ok, questState = pcall(function()
        return commF:InvokeServer("ElectroQuestState")
    end)
    if not ok then
        state.QuestState = nil
        return nil
    end
    state.QuestState = questState
    -- The manual dialogue only sends AcceptElectroQuest after the player has
    -- travelled to Mad Scientist and chosen "I'll get you one".  Keep that
    -- order here: a remote state check by itself must never start cloud work.
    if canAccept and (questState == 0 or questState == 5) then
        local accepted, result = pcall(function()
            return commF:InvokeServer("AcceptElectroQuest")
        end)
        if accepted and result == 1 then
            state.QuestState = 1
            state.LastDebug = "Mad Scientist quest accepted; scanning charged clouds"
            XyraxAutomation.SuperhumanStatus = state.LastDebug
            print("[BfRef Lightning Bolt] " .. state.LastDebug)
        end
    end
    return state.QuestState
end

function xyraxLightningBoltDelivered()
    local state = XyraxAutomation.LightningBolt
    if state.Delivered == true then
        return true
    end
    local questState = xyraxEnsureLightningQuest(false)
    -- 0/5 = needs accepting, 1 = collecting, 4 = return the held bolt.
    -- Any remaining numeric state is the post-delivery dialogue state.
    return type(questState) == "number"
        and questState ~= 0 and questState ~= 1
        and questState ~= 4 and questState ~= 5
end

function xyraxLightningPart(candidate)
    if not candidate then return nil end
    if candidate:IsA("BasePart") then return candidate end
    return candidate.PrimaryPart
        or candidate:FindFirstChild("HumanoidRootPart")
        or candidate:FindFirstChild("Root")
        or candidate:FindFirstChildWhichIsA("BasePart", true)
end

function xyraxFindChargedCloud()
    local state = XyraxAutomation.LightningBolt
    local now = os.clock()
    if state.Target and state.Target.Parent and now < (state.TargetUntil or 0) then
        return state.Target
    end
    if now - (state.ScanAt or 0) < 0.25 then
        return state.Target
    end
    state.ScanAt = now
    state.Target = nil
    local map = workspace:FindFirstChild("Map")
    local sky = map and map:FindFirstChild("Sky")
    if not sky then return nil end

    -- Live test: the quest cloud is an ordinary Workspace.Map.Sky.cloud whose
    -- Color briefly changes to dark grey/black (observed brightness 0.289).
    -- Do not target a normal white cloud or any ReplicatedStorage FX asset.
    for _, cloud in ipairs(sky:GetDescendants()) do
        if cloud:IsA("BasePart") and string.lower(cloud.Name) == "cloud" then
            local color = cloud.Color
            local brightness = (color.R + color.G + color.B) / 3
            if brightness <= 0.60 then
                state.Target = cloud
                state.TargetBrightness = brightness
                state.CloudHitCount = 0
                state.CloudHitAt = 0
                state.BoltCheckAt = 0
                -- A charged cloud flashes briefly. Keep this exact instance
                -- long enough for the character to reach and strike it.
                state.TargetUntil = now + 20
                break
            end
        end
    end
    return state.Target
end

function xyraxLightningDebug(message)
    local state = XyraxAutomation.LightningBolt
    if state.LastDebug ~= message then
        state.LastDebug = message
        XyraxAutomation.SuperhumanStatus = message
        print("[BfRef Lightning Bolt] " .. message)
    end
end

function xyraxGetLightningBoltAction()
    if not (World1 and XyraxAutomation.Desired.SuperhumanPhase1) then
        return nil
    end
    local state = XyraxAutomation.LightningBolt
    local questState = xyraxEnsureLightningQuest(false)
    local scientist = xyraxFindMadScientist()
    local scientistRoot = xyraxLightningPart(scientist)

    -- DeliverLightningBolt succeeded during this session.  Some inventory
    -- responses can remain cached briefly, so never let a stale Bolt result
    -- re-enter the delivery route and trap the player in a repeat loop.
    if state.Delivered then
        state.Target = nil
        state.TargetUntil = 0
        xyraxLightningDebug("Lightning Bolt delivered; continuing Electric purchase")
        return nil
    end

    -- A Lightning Bolt is a held prerequisite, not a reason to interrupt
    -- Black Step mastery farming.  Keeping it until Mastery 300 avoids
    -- delivering it too soon, losing the visible proof of progress, then
    -- having to repeat the cloud route later.
    local darkStep = xyraxSuperhumanStages[1]
    local darkStepTool = xyraxFindSuperhumanTool(darkStep)
    local masteryValue = darkStepTool and darkStepTool:FindFirstChild("Level")
    local darkStepMastery = masteryValue and masteryValue.Value or 0
    local boltPending = xyraxHasLightningBolt() or questState == 4

    -- Once Electric is owned the Bolt was already delivered and Dark Step is
    -- no longer the held style, so its Tool (and its mastery) is gone.  Do
    -- not read that absence as 0/300 and stall the route again.
    local electricOwned = XyraxAutomation.SuperhumanOwned
        and XyraxAutomation.SuperhumanOwned.Electric
    if boltPending and darkStepMastery < 300 and not electricOwned then
        state.Target = nil
        state.TargetUntil = 0
        XyraxAutomation.PreferredMeleeAliases = darkStep.Aliases
        xyraxLightningDebug(string.format(
            "Lightning Bolt secured; waiting for Black Step mastery (%d/300); Farm Level continues",
            darkStepMastery
        ))
        return nil
    end

    -- Missing Lightning Bolt is a real Lower Skylands quest.  Go to the NPC
    -- first, accept it there, then and only then look for a flashing cloud.
    if questState == 0 or questState == 5 or questState == nil then
        if os.clock() < (state.ScientistRetryAt or 0) then
            return nil
        end
        xyraxLightningDebug(scientistRoot
            and "Mad Scientist found in " .. tostring(state.ScientistSource) .. "; travelling to start Missing Lightning Bolt"
            or "Mad Scientist unavailable; travelling to Lower Skylands dock")
        return {
            Kind = "StartQuest",
            Target = scientist,
            Root = scientistRoot,
            Destination = scientistRoot and scientistRoot.CFrame or state.ScientistDock,
        }
    end

    -- State 4 means the cloud has already supplied the material.  Only return
    -- it after Black Step has reached Mastery 300 (guarded above).
    if boltPending then
        xyraxLightningDebug(scientistRoot
            and "Lightning Bolt held; returning to Mad Scientist (" .. tostring(state.ScientistSource) .. ")"
            or "Lightning Bolt held; travelling to Mad Scientist template")
        return {
            Kind = "DeliverBolt",
            Target = scientist,
            Root = scientistRoot,
            Destination = scientistRoot and scientistRoot.CFrame or state.ScientistDock,
        }
    end

    local cloud = xyraxFindChargedCloud()
    if cloud then
        local root = xyraxLightningPart(cloud)
        if root then
            if XyraxAutomation.LightningBolt.CloudHitCount == 0 then
                xyraxLightningDebug(string.format(
                    "Dark charged cloud found (brightness %.3f); collecting Lightning Bolt",
                    XyraxAutomation.LightningBolt.TargetBrightness or 0
                ))
            end
            XyraxAutomation.LightningBolt.Target = cloud
            return {Kind = "Collect", Target = cloud, Root = root}
        end
    end
    -- State 1 is the confirmed accepted quest.  A missing spawn never owns
    -- movement, so normal Farm Level keeps progressing until it appears.
    xyraxLightningDebug("Mad Scientist quest active; waiting for charged cloud; Farm Level continues")
    return nil
end

-- Only one fighting style is held at a time, so a missing Tool never means
-- the style was not bought.  The teacher dialogue answers this directly:
-- CommF_(Remote, true) == 1 is "It seems you already know this style"
-- (DialoguesList BuyBlackLeg / BuyElectro).  A learned style is never lost,
-- so a true result is cached permanently and only a false one is re-polled.
XyraxAutomation.SuperhumanOwned = XyraxAutomation.SuperhumanOwned or {}
XyraxAutomation.SuperhumanOwnedCheckAt = {}

-- Once a stage's Tool reports Level >= 300, remember that permanently.  The
-- Tool disappears the moment the next style is bought (only one style is
-- held at a time), so re-reading Level after that point would see nothing
-- and must never be mistaken for mastery resetting to 0.
XyraxAutomation.SuperhumanMasteryDone = XyraxAutomation.SuperhumanMasteryDone or {}

function XyraxAutomation.SuperhumanOwns(stage)
    if XyraxAutomation.SuperhumanOwned[stage.Key] then
        return true
    end
    if xyraxFindSuperhumanTool(stage) then
        XyraxAutomation.SuperhumanOwned[stage.Key] = true
        return true
    end
    local now = os.clock()
    if now < (XyraxAutomation.SuperhumanOwnedCheckAt[stage.Key] or 0) then
        return false
    end
    XyraxAutomation.SuperhumanOwnedCheckAt[stage.Key] = now + 30
    local ok, result = pcall(function()
        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
        local commF = remotes and remotes:FindFirstChild("CommF_")
        if not commF then
            return nil
        end
        if stage.Key == "DragonBreath" then
            -- Sabi's precheck shape: ("BlackbeardReward","DragonClaw","1")
            -- returns falsy (never talked to Sabi before), 1 (already
            -- know it), or anything else (need to trade Fragments).
            return commF:InvokeServer("BlackbeardReward", "DragonClaw", "1")
        end
        return commF:InvokeServer(stage.Remote, true)
    end)
    if ok and result == 1 then
        XyraxAutomation.SuperhumanOwned[stage.Key] = true
        return true
    end
    return false
end

-- Sabi/Martial Arts Master have no confirmed live Workspace position in
-- the dump (same situation Trevor/Mysterious Scientist were in earlier),
-- but their template Model does exist under ReplicatedStorage.NPCs constantly
-- (same place Mad Scientist's fallback NPC coordinate above was itself
-- read from) - check there too when Workspace doesn't have it yet.
-- Confirmed live crash: a blind ReplicatedStorage:FindFirstChild(name, true)
-- can match the WRONG instance - e.g. "Sabi" also exists as a ModuleScript
-- at ReplicatedStorage.DialoguesList.NPCs.Sabi (dialogue data, no
-- PrimaryPart), separate from the real Model at ReplicatedStorage.NPCs.Sabi.
-- Scoping the fallback search to the ReplicatedStorage.NPCs folder (the same
-- folder every other confirmed NPC template in this file lives in) avoids
-- ever matching that dialogue script.
function XyraxAutomation.FindSuperhumanTeacher(name)
    if not name then
        return nil
    end
    local npcs = game:GetService("ReplicatedStorage"):FindFirstChild("NPCs")
    return workspace:FindFirstChild(name, true) or (npcs and npcs:FindFirstChild(name, true))
end

function XyraxAutomation.SuperhumanStageAffordable(stage)
    if stage.CostCurrency == "Fragments" then
        return xyraxGetFragments() >= stage.Cost
    end
    return xyraxGetBeli() >= stage.Cost
end

-- Same print-on-change convention as XyraxAutomation.SetProgressionBossSea2Status
-- / SetRaceV3Status.  xyraxGetSuperhumanPhaseOneAction() below already sets
-- XyraxAutomation.SuperhumanStatus at every yield/nil point (deferred-until-Sea2,
-- waiting for Lightning Bolt, need resources, re-equip retry, waiting for
-- mastery) but nothing ever printed those - the worker further below only
-- prints its own travel/purchase status, which never runs while this
-- function is yielding (action == nil).  Routing the decision function's own
-- assignments through this makes every yield reason visible without changing
-- any of the decision logic itself.
XyraxAutomation.LastSuperhumanDecisionStatus = nil
function XyraxAutomation.SetSuperhumanStatus(status)
    XyraxAutomation.SuperhumanStatus = status
    if status ~= XyraxAutomation.LastSuperhumanDecisionStatus then
        XyraxAutomation.LastSuperhumanDecisionStatus = status
        print("[BfRef Superhuman] " .. tostring(status))
    end
end

local function xyraxGetSuperhumanPhaseOneAction()
    -- Dark Step is learned first.  Electric is taught by Mad Scientist in
    -- Lower Skylands after Missing Lightning Bolt is delivered; later styles
    -- remain Sea 2 progression.
    if not (XyraxAutomation.Desired.SuperhumanPhase1 and (World1 or World2)) then
        XyraxAutomation.SuperhumanAction = nil
        XyraxAutomation.PreferredMeleeAliases = nil
        return nil
    end

    local beli = xyraxGetBeli()

    -- Walk the stages in order.  Mastery (ItemReplicationService KEYS.MASTERY,
    -- read remotely - confirmed live via standalone test, no equip/travel
    -- needed) is checked FIRST for every stage, before ownership or the
    -- currently-equipped Tool are even looked at: a stage already at 300 is
    -- marked done and skipped in this same pass with zero movement, exactly
    -- like the other already-mastered stages.  Only once a stage is found
    -- that still needs mastery does the old ownership/Buy/Equip logic run -
    -- and even then, if that style is already the one currently held,
    -- nothing travels anywhere; Farm Level just keeps grinding it.
    for _, stage in ipairs(xyraxSuperhumanStages) do
        if not XyraxAutomation.SuperhumanMasteryDone[stage.Key] then
            local replicatedMastery = xyraxGetReplicatedMastery(stage)
            if replicatedMastery and replicatedMastery >= 300 then
                XyraxAutomation.SuperhumanMasteryDone[stage.Key] = true
                print("[BfRef Superhuman] " .. stage.Label .. " mastery confirmed remotely ("
                    .. replicatedMastery .. "/300); checking next stage in the same pass")
            else
                local tool = xyraxFindSuperhumanTool(stage)
                if tool then
                    -- Already holding this exact style - never Tween/Equip
                    -- just to check mastery again.  Fall back to Tool.Level
                    -- only if the remote read came back nil (service failed
                    -- to load, or genuinely no entry yet).
                    local masteryValue = replicatedMastery
                    if masteryValue == nil then
                        local levelValue = tool:FindFirstChild("Level")
                        masteryValue = levelValue and levelValue.Value or 0
                    end
                    if masteryValue >= 300 then
                        XyraxAutomation.SuperhumanMasteryDone[stage.Key] = true
                        print("[BfRef Superhuman] " .. stage.Label .. " mastery confirmed via held Tool ("
                            .. masteryValue .. "/300); checking next stage in the same pass")
                    else
                        -- Mastery farming belongs to the normal Farm Level
                        -- system.  Auto Superhuman only observes it and never
                        -- takes a movement slot until this stage is confirmed
                        -- complete.
                        XyraxAutomation.PreferredMeleeAliases = stage.Aliases
                        XyraxAutomation.SuperhumanAction = nil
                        XyraxAutomation.SetSuperhumanStatus("Waiting for " .. stage.Label .. " mastery (" .. masteryValue .. "/300)")
                        return nil
                    end
                else
                    -- Not currently held: this is the only branch that may
                    -- need to travel - either to buy it for the first time,
                    -- or to re-equip an already-owned style so Farm Level has
                    -- something to grind.
                    if not XyraxAutomation.SuperhumanOwns(stage) then
                        if World1 and stage.Key ~= "DarkStep" and stage.Key ~= "Electric" then
                            XyraxAutomation.SuperhumanAction = nil
                            XyraxAutomation.PreferredMeleeAliases = nil
                            XyraxAutomation.SetSuperhumanStatus(stage.Label .. " purchase deferred until Sea 2")
                            return nil
                        end
                        if stage.Key == "Electric" and not xyraxLightningBoltDelivered() then
                            XyraxAutomation.SuperhumanAction = nil
                            XyraxAutomation.PreferredMeleeAliases = nil
                            XyraxAutomation.SetSuperhumanStatus("Waiting for Missing Lightning Bolt to be delivered")
                            return nil
                        end
                        if XyraxAutomation.SuperhumanStageAffordable(stage) and os.clock() >= (xyraxSuperhumanBuyRetryAt[stage.Key] or 0) then
                            local action = {
                                Kind = "Buy",
                                Stage = stage,
                                ToolName = nil,
                            }
                            XyraxAutomation.SuperhumanAction = action
                            XyraxAutomation.SetSuperhumanStatus("Buy " .. stage.Label)
                            return action
                        end
                        XyraxAutomation.SuperhumanAction = nil
                        XyraxAutomation.PreferredMeleeAliases = nil
                        XyraxAutomation.SetSuperhumanStatus("Need " .. stage.Label .. " resources")
                        return nil
                    end

                    XyraxAutomation.PreferredMeleeAliases = stage.Aliases
                    if os.clock() < (xyraxSuperhumanBuyRetryAt[stage.Key] or 0) then
                        XyraxAutomation.SuperhumanAction = nil
                        XyraxAutomation.SetSuperhumanStatus("Re-equip of " .. stage.Label .. " failed; retrying shortly")
                        return nil
                    end
                    local action = {Kind = "Equip", Stage = stage}
                    XyraxAutomation.SuperhumanAction = action
                    XyraxAutomation.SetSuperhumanStatus("Re-equipping " .. stage.Label .. " to obtain the Tool")
                    return action
                end
            end
        end
    end

    -- All four styles owned and mastered at 300: last step is Martial
    -- Arts Master's own capstone style, $3,000,000, no mastery needed.
    -- Confirmed live (dump: DialoguesList.MartialArtsMaster):
    -- CommF_("BuySuperhuman", true) precheck (3 = prerequisites not met
    -- yet), CommF_("BuySuperhuman") with no args to actually buy.  Same
    -- no-confirmed-position situation as Sabi above.
    if XyraxAutomation.SuperhumanBought then
        XyraxAutomation.SuperhumanAction = nil
        XyraxAutomation.PreferredMeleeAliases = nil
        XyraxAutomation.SetSuperhumanStatus("Phase 1 complete")
        return nil
    end
    if beli >= 3000000 and os.clock() >= (xyraxSuperhumanBuyRetryAt.Superhuman or 0) then
        local action = {Kind = "BuySuperhuman"}
        XyraxAutomation.SuperhumanAction = action
        XyraxAutomation.SetSuperhumanStatus("Buy Superhuman")
        return action
    end
    XyraxAutomation.SuperhumanAction = nil
    XyraxAutomation.PreferredMeleeAliases = nil
    XyraxAutomation.SetSuperhumanStatus("Need $3,000,000 for Superhuman")
    return nil
end

-- Death Step (Phoeyu, the Reformed) is gated behind Superhuman itself:
-- Superhuman must be bought and its own Tool mastery >= 300, then Dark Step
-- mastery (re-checked by re-equipping it - only one style is held at a time,
-- so Superhuman replaced Dark Step's Tool the moment it was bought, exactly
-- the situation XyraxAutomation.SuperhumanOwns already documents) must be
-- >= 400, then the Library must already be open (owned by the Auto Sea2 Key
-- job above - this never travels there itself), then $2,500,000 + 5,000
-- Fragments (confirmed live price, DialoguesList.lua "Phoeyu, the Reformed":
-- CommF_("BuyDeathStep", true) precheck, CommF_("BuyDeathStep") to buy).
-- Re-equipping Dark Step is delegated to the existing Superhuman Equip
-- action/worker via the "Auto Superhuman: Equip ..." job name, so no new
-- re-equip code is written here.
local xyraxDeathStepBuyRetryAt = 0
XyraxAutomation.DeathStepSuperhumanMasteryDone = XyraxAutomation.DeathStepSuperhumanMasteryDone or false
XyraxAutomation.DeathStepDarkStepMasteryDone = XyraxAutomation.DeathStepDarkStepMasteryDone or false
XyraxAutomation.LastDeathStepStatus = nil
function XyraxAutomation.SetDeathStepStatus(status)
    XyraxAutomation.DeathStepStatus = status
    if status ~= XyraxAutomation.LastDeathStepStatus then
        XyraxAutomation.LastDeathStepStatus = status
        print("[DeathStep] " .. tostring(status))
    end
end

function XyraxAutomation.GetDeathStepJob()
    if not (XyraxAutomation.Desired.DeathStep and World2) then
        return nil
    end
    if XyraxAutomation.DeathStepOwned or xyraxOwnsTool("death step") then
        XyraxAutomation.DeathStepOwned = true
        XyraxAutomation.SetDeathStepStatus("Complete")
        return nil
    end
    if not XyraxAutomation.SuperhumanBought then
        XyraxAutomation.DeathStepStatus = "Waiting for Superhuman purchase"
        return nil
    end

    -- Superhuman mastery >=300, remote-first (ItemReplicationService
    -- KEYS.MASTERY, ItemId 1162 - confirmed live, RawSource.lua:
    -- Type="Moveset", StorageKey="Superhuman") via xyraxGetReplicatedMastery,
    -- the exact same helper every xyraxSuperhumanStages entry already uses -
    -- this never needs Superhuman actually equipped to know its mastery.
    -- Tool.Level is only a fallback for when the replicated read itself
    -- comes back nil (service not loaded yet / no entry) - never used to
    -- override a real remote value, and nil is never treated as "0/none".
    if not XyraxAutomation.DeathStepSuperhumanMasteryDone then
        local superhumanStub = {ItemId = 1162, Aliases = {"Superhuman"}}
        local superhumanMastery = xyraxGetReplicatedMastery(superhumanStub)
        if superhumanMastery == nil then
            local superhumanTool = xyraxFindSuperhumanTool(superhumanStub)
            local superhumanMasteryValue = superhumanTool and superhumanTool:FindFirstChild("Level")
            superhumanMastery = superhumanMasteryValue and superhumanMasteryValue.Value or 0
        end
        if superhumanMastery < 300 then
            XyraxAutomation.DeathStepStatus = "Waiting for Superhuman mastery (" .. superhumanMastery .. "/300)"
            return nil
        end
        XyraxAutomation.DeathStepSuperhumanMasteryDone = true
        print("[DeathStep] Superhuman mastery: " .. superhumanMastery)
    end

    -- Dark Step / Black Leg mastery >=400, remote-first the exact same way
    -- (ItemId 1456, xyraxSuperhumanStages[1]).  An account with Dragon
    -- Breath (or any other style) currently equipped has no Dark Step Tool
    -- instance to read Tool.Level from at all - the replicated read is what
    -- lets this branch know mastery is already >=400 WITHOUT ever
    -- Equipping/Tweening to Dark Step's teacher just to check.  Cached
    -- permanently once confirmed, so this whole block is skipped forever
    -- afterwards - Dark Step is never re-equipped just to re-verify.
    local darkStep = xyraxSuperhumanStages[1]
    if not XyraxAutomation.DeathStepDarkStepMasteryDone then
        local darkStepMastery = xyraxGetReplicatedMastery(darkStep)
        if darkStepMastery == nil then
            -- Remote unavailable - fall back to the original Tool-based
            -- check exactly as before.  A missing Tool here is genuinely
            -- unresolvable (no remote data AND nothing held to read
            -- Tool.Level from), so it still falls through to the original
            -- "not held -> Equip" behaviour rather than being misread as
            -- "mastery 0"/"no Dark Step".
            local darkStepTool = xyraxFindSuperhumanTool(darkStep)
            if not darkStepTool then
                if os.clock() < (xyraxSuperhumanBuyRetryAt[darkStep.Key] or 0) then
                    XyraxAutomation.SetDeathStepStatus("Re-equip of Dark Step failed; retrying shortly")
                    return nil
                end
                XyraxAutomation.SuperhumanAction = {Kind = "Equip", Stage = darkStep}
                XyraxAutomation.SetDeathStepStatus("Equipping Dark Step for mastery")
                return "Auto Superhuman: Equip " .. darkStep.Label
            end
            local darkStepMasteryValue = darkStepTool:FindFirstChild("Level")
            darkStepMastery = darkStepMasteryValue and darkStepMasteryValue.Value or 0
        end

        if darkStepMastery >= 400 then
            XyraxAutomation.DeathStepDarkStepMasteryDone = true
            XyraxAutomation.PreferredMeleeAliases = nil
            print("[DeathStep] Dark Step mastery complete")
        else
            -- Confirmed <400 (whether from remote or the Tool fallback
            -- above): either grind it if already equipped, or retrieve it
            -- first so Farm Level has something to grind.
            local darkStepTool = xyraxFindSuperhumanTool(darkStep)
            if darkStepTool then
                XyraxAutomation.PreferredMeleeAliases = darkStep.Aliases
                XyraxAutomation.SetDeathStepStatus("Dark Step mastery: " .. darkStepMastery .. "/400")
                return nil
            end
            if os.clock() < (xyraxSuperhumanBuyRetryAt[darkStep.Key] or 0) then
                XyraxAutomation.SetDeathStepStatus("Re-equip of Dark Step failed; retrying shortly")
                return nil
            end
            XyraxAutomation.SuperhumanAction = {Kind = "Equip", Stage = darkStep}
            XyraxAutomation.SetDeathStepStatus("Equipping Dark Step for mastery")
            return "Auto Superhuman: Equip " .. darkStep.Label
        end
    end

    local iceCastle = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("IceCastle")
    local hall = iceCastle and iceCastle:FindFirstChild("Hall")
    local libraryDoor = hall and hall:FindFirstChild("LibraryDoor")
    if libraryDoor and libraryDoor:FindFirstChild("Keyhole") then
        XyraxAutomation.DeathStepStatus = "Waiting for the Library to be opened (Auto Sea2 Key)"
        return nil
    end

    if xyraxGetBeli() < 2500000 or xyraxGetFragments() < 5000 then
        XyraxAutomation.SetDeathStepStatus("Waiting resources")
        return nil
    end
    if os.clock() < xyraxDeathStepBuyRetryAt then
        return nil
    end

    XyraxAutomation.DeathStepStatus = "Buy Death Step"
    return "Auto Death Step"
end

-- Third Sea (Kaitun).  Confirmed live from the current dump, not guessed:
--   - DialoguesList.lua "King Red Head" (u823.RedHead): CommF_("ZQuestProgress",
--     "Check") == 0 -> offers to start (accepted via CommF_("ZQuestProgress",
--     "Begin")); == 1 -> already done (client UI in LocalScript_17.lua treats
--     exactly Check==1 as the Sea3 button's "Active" state); any other value
--     -> "Come back when you've reached Level 1,500 and defeated Don Swan!" -
--     i.e. Don Swan is verified server-side by this same check, so this never
--     duplicates Race V3's own Don Swan hunt, it just yields to let that job
--     (already in this scheduler) keep working on it.
--   - Killing rip_indra (Workspace._WorldOrigin.EnemySpawns has "rip_indra
--     [Lv. 1500] [Boss]"; ReplicatedStorage.NPCs.rip_indra and
--     ReplicatedStorage.rip_indra also exist) triggers DialoguesList.lua
--     "Mental Message" (u823.KilledIndraBoss): "Talk to <Mr. Captain> at
--     <Green Zone>."
--   - DialoguesList.lua "Mr. Captain" (u823.TravelZou): CommF_("ZQuestProgress",
--     "Zou") == 0 -> offers travel, accepted via CommF_("TravelZou") - the
--     exact same remote the hub's own existing "Teleport To Third Sea" button
--     already fires unconditionally, confirming no precheck is required before
--     firing it.
--   - Sharkman Karate ownership: DialoguesList.lua "Sharkman Teacher" uses the
--     identical BuySharkmanKarate(true)/BuySharkmanKarate() precheck/buy shape
--     as every XyraxAutomation.SuperhumanOwns() style (1 == already know).
--   - Both King Red Head and Mr. Captain are ReplicatedStorage.NPCs entries,
--     so XyraxAutomation.FindSuperhumanTeacher(name) (Workspace live copy,
--     falling back to the ReplicatedStorage template) locates them with no
--     new lookup helper and no hardcoded CFrame.
XyraxAutomation.SharkmanKarateOwned = XyraxAutomation.SharkmanKarateOwned or false
XyraxAutomation.SharkmanKarateOwnedCheckAt = XyraxAutomation.SharkmanKarateOwnedCheckAt or 0
function XyraxAutomation.OwnsSharkmanKarate()
    if XyraxAutomation.SharkmanKarateOwned then
        return true
    end
    if xyraxOwnsTool("sharkman karate") then
        XyraxAutomation.SharkmanKarateOwned = true
        return true
    end
    local now = os.clock()
    if now < XyraxAutomation.SharkmanKarateOwnedCheckAt then
        return false
    end
    XyraxAutomation.SharkmanKarateOwnedCheckAt = now + 30
    local ok, result = pcall(function()
        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
        local commF = remotes and remotes:FindFirstChild("CommF_")
        return commF and commF:InvokeServer("BuySharkmanKarate", true)
    end)
    if ok and result == 1 then
        XyraxAutomation.SharkmanKarateOwned = true
        return true
    end
    return false
end

-- Sharkman Karate (Sharkman Teacher, Sea 2).  Flow, confirmed live:
--   1. Water Kung Fu (Fishman Karate) Mastery >= 400 - read the exact same
--      remote-free way every Superhuman stage is read
--      (xyraxGetReplicatedMastery, ItemReplicationService KEYS.MASTERY,
--      ItemId 1134 - xyraxSuperhumanStages' own "WaterKungFu" entry).  Never
--      trust "no Tool currently equipped" as "no mastery": Dragon Breath (or
--      any other style) may be the one equipped while Water Kung Fu's
--      mastery/ownership is still fully intact in Backpack - xyraxFindSuperhumanTool
--      already scans Character AND Backpack, not "currently equipped" only.
--   2. Water Key from Tide Keeper (Sea 2, ForgottenQuest "Tide Keeper" stage,
--      LevelReq 1475) - not guaranteed per kill, so Tide Keeper is hunted
--      (via the Sea2 Progression Boss table/worker, NeedsWaterKey() special
--      case in GetSea2ProgressionBoss above) until the drop actually lands
--      in Character/Backpack.
--   3. The held Water Key is turned in at Sharkman Teacher immediately
--      (GetWaterKeyTurnInJob below) - a one-time, permanent server-side
--      unlock.  Confirmed live precheck text before turning it in:
--      CommF_:InvokeServer("BuySharkmanKarate", true) == "I lost my house
--      keys, could you help me find them? Thanks."  After rejoin, this
--      state is always RE-DERIVED from that same server precheck
--      (CheckWaterKeyUnlocked) - a local flag alone is never trusted, only
--      used as a short-lived cache between re-checks.
--   4. Once unlocked + mastery >=400 + $2,500,000 + 5,000 Fragments:
--      CommF_:InvokeServer("BuySharkmanKarate") (DialoguesList.lua
--      "Sharkman Teacher": 1=learned, 0=insufficient funds, 2=already
--      known, 3=not strong enough yet).
XyraxAutomation.WaterKeyUnlocked = XyraxAutomation.WaterKeyUnlocked or false
XyraxAutomation.WaterKeyUnlockedCheckAt = 0
XyraxAutomation.LastSharkmanPrecheckText = nil
XyraxAutomation.SharkmanTideKeeperHuntLogged = XyraxAutomation.SharkmanTideKeeperHuntLogged or false
XyraxAutomation.SharkmanCompleteLogged = XyraxAutomation.SharkmanCompleteLogged or false

local XYRAX_SHARKMAN_NEED_KEY_TEXT = "I lost my house keys, could you help me find them? Thanks."

-- Re-derives from the server precheck at least every 30s (same cadence as
-- OwnsSharkmanKarate above), and immediately when `force` is passed (e.g.
-- right after a turn-in attempt).  The cached flag is only a short-lived
-- fast path between checks, per "never rely on a local flag alone".
function XyraxAutomation.CheckWaterKeyUnlocked(force)
    if XyraxAutomation.OwnsSharkmanKarate() then
        XyraxAutomation.WaterKeyUnlocked = true
        return true
    end
    local now = os.clock()
    if not force and now < XyraxAutomation.WaterKeyUnlockedCheckAt then
        return XyraxAutomation.WaterKeyUnlocked
    end
    XyraxAutomation.WaterKeyUnlockedCheckAt = now + 30
    local ok, result = pcall(function()
        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
        local commF = remotes and remotes:FindFirstChild("CommF_")
        return commF and commF:InvokeServer("BuySharkmanKarate", true)
    end)
    if not ok then
        return XyraxAutomation.WaterKeyUnlocked
    end
    XyraxAutomation.LastSharkmanPrecheckText = (typeof(result) == "string") and result or nil
    local wasUnlocked = XyraxAutomation.WaterKeyUnlocked
    if typeof(result) == "string" and result == XYRAX_SHARKMAN_NEED_KEY_TEXT then
        XyraxAutomation.WaterKeyUnlocked = false
    else
        -- Any other response (a different string, such as the "prepared
        -- enough" / price-prompt text, or a numeric result code) means the
        -- server no longer considers the key outstanding.
        XyraxAutomation.WaterKeyUnlocked = true
    end
    if XyraxAutomation.WaterKeyUnlocked and not wasUnlocked then
        print("[Sharkman] Water Key unlocked")
    end
    return XyraxAutomation.WaterKeyUnlocked
end

function XyraxAutomation.NeedsWaterKey()
    if XyraxAutomation.OwnsSharkmanKarate() then
        return false
    end
    if xyraxOwnsTool("water key") then
        -- Already holding one - GetWaterKeyTurnInJob owns it from here, not
        -- another Tide Keeper hunt.
        return false
    end
    return not XyraxAutomation.CheckWaterKeyUnlocked()
end

-- Tide Keeper's own table entry.  MinLevel/MaxLevel = math.huge so the
-- normal level-band loop in GetSea2ProgressionBoss can never pick it up -
-- it is only ever returned through the NeedsWaterKey() special case, so it
-- stops being farmed the instant Sharkman Karate stops needing it (it never
-- becomes a general-purpose leveling target).
table.insert(XyraxAutomation.Sea2ProgressionBosses, {
    Label = "Tide Keeper", MinLevel = math.huge, MaxLevel = math.huge,
    EnemyNames = {"Tide Keeper"}, QuestTargets = {"Tide Keeper"},
    QuestName = "ForgottenQuest", QuestLevel = 3,
})

-- Water Key turn-in.  No separate "hand over the key" remote is confirmed
-- to exist - Sharkman Teacher's dialogue tree only ever calls
-- BuySharkmanKarate.  Travelling to the NPC and firing the same precheck
-- the "Talk" dialogue option itself uses is the only confirmed interaction
-- point, so that is what this job performs; CheckWaterKeyUnlocked(true)
-- right after confirms whether the server actually consumed it.
function XyraxAutomation.GetWaterKeyTurnInJob()
    if not (XyraxAutomation.Desired.SharkmanKarate and World2) then
        return nil
    end
    if not xyraxOwnsTool("water key") then
        return nil
    end
    if XyraxAutomation.OwnsSharkmanKarate() then
        return nil
    end
    return "Auto Water Key Turn-In"
end

-- Sharkman Karate purchase decision.  Mirrors XyraxAutomation.GetDeathStepJob's
-- shape closely: mastery gate first (cached once >=400, never re-checked
-- again), then resources, then a retry-cooldown-guarded Buy.  Re-equipping
-- Water Kung Fu to read its mastery reuses the exact same "Equip" action
-- Kind the Superhuman worker already executes - no new worker branch is
-- needed for that half.
local xyraxSharkmanKarateBuyRetryAt = 0
XyraxAutomation.SharkmanMasteryDone = XyraxAutomation.SharkmanMasteryDone or false
XyraxAutomation.SharkmanDeathStepMasteryDone = XyraxAutomation.SharkmanDeathStepMasteryDone or false
XyraxAutomation.SharkmanFarmingDeathStepLogged = XyraxAutomation.SharkmanFarmingDeathStepLogged or false
XyraxAutomation.LastSharkmanStatus = nil
function XyraxAutomation.SetSharkmanStatus(status)
    XyraxAutomation.SharkmanStatus = status
    if status ~= XyraxAutomation.LastSharkmanStatus then
        XyraxAutomation.LastSharkmanStatus = status
        print("[Sharkman] " .. tostring(status))
    end
end

local function xyraxFindWaterKungFuStage()
    for _, stage in ipairs(xyraxSuperhumanStages) do
        if stage.Key == "WaterKungFu" then
            return stage
        end
    end
    return nil
end

function XyraxAutomation.GetSharkmanKarateJob()
    if not (XyraxAutomation.Desired.SharkmanKarate and World2) then
        return nil
    end
    if XyraxAutomation.OwnsSharkmanKarate() then
        if not XyraxAutomation.SharkmanCompleteLogged then
            XyraxAutomation.SharkmanCompleteLogged = true
            print("[Sharkman] Complete")
        end
        return nil
    end

    -- Death Step must be owned, and Death Step's OWN mastery must be >=300,
    -- before Sharkman progression starts - the same "each fighting style
    -- mastery gates the next" chain Superhuman -> Death Step already uses,
    -- extended one link further.  Death Step's Moveset ItemId is 1184
    -- (confirmed live: RawSource.lua:4777 Type="Moveset",
    -- StorageKey="Death Step"; GeneratedSource.lua:1188 ["Death Step"]=1184)
    -- - NOT the same item as Dark Step/Black Leg's own 1456 mastery gate
    -- that unlocks Death Step itself (RawSource.lua:5869).  Remote-first via
    -- xyraxGetReplicatedMastery, exactly like Superhuman/Dark Step in
    -- GetDeathStepJob above - works even while Dragon Breath/Water Kung Fu/
    -- any other style is the one currently equipped.
    if not (XyraxAutomation.DeathStepOwned or xyraxOwnsTool("death step")) then
        XyraxAutomation.SetSharkmanStatus("Waiting for Death Step")
        return nil
    end
    if not XyraxAutomation.SharkmanDeathStepMasteryDone then
        local deathStepStub = {ItemId = 1184, Aliases = {"Death Step"}}
        local deathStepMastery = xyraxGetReplicatedMastery(deathStepStub)
        if deathStepMastery == nil then
            local deathStepTool = xyraxFindSuperhumanTool(deathStepStub)
            if not deathStepTool then
                -- Genuinely unresolvable (no remote data AND nothing held
                -- to read Tool.Level from) - unknown, not "zero".  Wait
                -- rather than guessing; the next pass re-checks the remote.
                XyraxAutomation.SetSharkmanStatus("Waiting for Death Step mastery data")
                return nil
            end
            local levelValue = deathStepTool:FindFirstChild("Level")
            deathStepMastery = levelValue and levelValue.Value or 0
        end

        if deathStepMastery >= 300 then
            XyraxAutomation.SharkmanDeathStepMasteryDone = true
            XyraxAutomation.SharkmanFarmingDeathStepLogged = false
            XyraxAutomation.PreferredMeleeAliases = nil
            print("[Sharkman] Death Step mastery complete")
        else
            local deathStepTool = xyraxFindSuperhumanTool(deathStepStub)
            if deathStepTool then
                -- Already holding Death Step - never Tween/Equip just to
                -- check mastery again, just let Farm Level keep grinding it.
                XyraxAutomation.PreferredMeleeAliases = deathStepStub.Aliases
                if not XyraxAutomation.SharkmanFarmingDeathStepLogged then
                    XyraxAutomation.SharkmanFarmingDeathStepLogged = true
                    print("[Sharkman] Farming Death Step mastery")
                end
                XyraxAutomation.SetSharkmanStatus("Death Step mastery: " .. deathStepMastery .. "/300")
                return nil
            end
            -- Not currently held (some other style equipped instead) -
            -- retrieve it so Farm Level can grind it.  Death Step is not
            -- one of xyraxSuperhumanStages (it is Superhuman's own
            -- follow-up reward, bought via Phoeyu, not a Superhuman
            -- prerequisite stage), so a one-off Stage table is built here
            -- with just the fields the shared "Equip" worker branch needs
            -- (Remote/Teacher/Aliases) - same re-equip mechanics as every
            -- other fighting style: firing BuyDeathStep on an already-owned
            -- style charges nothing and simply re-equips it (confirmed live,
            -- see the Auto Death Step executor's own purchaseResult==2
            -- handling), mastery preserved exactly as left.
            XyraxAutomation.SharkmanAction = {
                Kind = "Equip",
                Stage = {
                    Key = "DeathStep",
                    Label = "Death Step",
                    Aliases = {"Death Step"},
                    Remote = "BuyDeathStep",
                    Teacher = "Phoeyu, the Reformed",
                },
            }
            XyraxAutomation.SetSharkmanStatus("Retrieving Death Step to build mastery")
            return "Auto Sharkman Karate"
        end
    end

    -- Water Kung Fu Mastery >= 400.  Cached permanently once confirmed - the
    -- whole block below is skipped forever after that, so Water Kung Fu is
    -- never Tweened/Equipped again just to re-check it.
    if not XyraxAutomation.SharkmanMasteryDone then
        local waterKungFuStage = xyraxFindWaterKungFuStage()
        if not waterKungFuStage then
            return nil
        end

        local replicatedMastery = xyraxGetReplicatedMastery(waterKungFuStage)
        if replicatedMastery and replicatedMastery >= 400 then
            XyraxAutomation.SharkmanMasteryDone = true
            XyraxAutomation.PreferredMeleeAliases = nil
            print("[Sharkman] Mastery: " .. replicatedMastery)
        else
            local tool = xyraxFindSuperhumanTool(waterKungFuStage)
            if tool then
                -- Already holding Water Kung Fu - never Tween/Equip just to
                -- check mastery again.  Fall back to Tool.Level only if the
                -- replicated read came back nil (service not loaded yet, or
                -- genuinely no entry).  A confirmed non-nil value under 400
                -- is trusted as-is, never assumed "no mastery" just because
                -- it is a low number.
                local masteryValue = replicatedMastery
                if masteryValue == nil then
                    local levelValue = tool:FindFirstChild("Level")
                    masteryValue = levelValue and levelValue.Value or 0
                end
                if masteryValue >= 400 then
                    XyraxAutomation.SharkmanMasteryDone = true
                    XyraxAutomation.PreferredMeleeAliases = nil
                    print("[Sharkman] Mastery: " .. masteryValue)
                else
                    XyraxAutomation.PreferredMeleeAliases = waterKungFuStage.Aliases
                    XyraxAutomation.SetSharkmanStatus("Waiting for Water Kung Fu mastery (" .. masteryValue .. "/400)")
                    return nil
                end
            else
                -- Not currently held (some other style, e.g. Dragon Breath,
                -- may be equipped instead) - retrieve/equip it so Farm Level
                -- can grind it, the same "Equip" action shape every
                -- Superhuman stage already uses.  Never conclude "no
                -- mastery" purely from an unreadable/nil replicated value
                -- here - equipping is what gets a definitive read, it is
                -- not itself a purchase.
                XyraxAutomation.SharkmanAction = {Kind = "Equip", Stage = waterKungFuStage}
                XyraxAutomation.SetSharkmanStatus("Retrieving Water Kung Fu to build mastery")
                return "Auto Sharkman Karate"
            end
        end
    end

    -- Water Key gate - never spend a movement slot on resources/purchase
    -- while the server still considers the key outstanding.  Tide Keeper
    -- hunting itself is owned entirely by the higher-priority Sea2
    -- Progression Boss job (NeedsWaterKey() special case) and Water Key
    -- Turn-In job above this one in xyraxPickJob - this gate only ever
    -- observes CheckWaterKeyUnlocked(), it never travels or fights.
    if not XyraxAutomation.CheckWaterKeyUnlocked() then
        XyraxAutomation.SetSharkmanStatus("State: NeedWaterKey")
        return nil
    end

    if xyraxGetBeli() < 2500000 or xyraxGetFragments() < 5000 then
        XyraxAutomation.SetSharkmanStatus(string.format(
            "Waiting resources: Beli=%d Fragments=%d", xyraxGetBeli(), xyraxGetFragments()))
        return nil
    end
    if os.clock() < xyraxSharkmanKarateBuyRetryAt then
        return nil
    end

    XyraxAutomation.SharkmanAction = {Kind = "Buy"}
    XyraxAutomation.SetSharkmanStatus("Purchasing")
    return "Auto Sharkman Karate"
end

XyraxAutomation.ThirdSeaStateAt = 0
XyraxAutomation.ThirdSeaState = nil
function XyraxAutomation.GetThirdSeaState(force)
    local now = os.clock()
    if not force and now - XyraxAutomation.ThirdSeaStateAt < 3 then
        return XyraxAutomation.ThirdSeaState
    end
    XyraxAutomation.ThirdSeaStateAt = now
    local ok, result = pcall(function()
        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
        local commF = remotes and remotes:FindFirstChild("CommF_")
        return commF and commF:InvokeServer("ZQuestProgress", "Check")
    end)
    XyraxAutomation.ThirdSeaState = ok and result or nil
    return XyraxAutomation.ThirdSeaState
end

XyraxAutomation.LastThirdSeaStatus = nil
function XyraxAutomation.SetThirdSeaStatus(status)
    XyraxAutomation.ThirdSeaStatus = status
    if status ~= XyraxAutomation.LastThirdSeaStatus then
        XyraxAutomation.LastThirdSeaStatus = status
        print("[BfRef ThirdSea] " .. tostring(status))
    end
end

function XyraxAutomation.GetThirdSeaJob()
    if not (XyraxAutomation.Desired.ThirdSea and World2) then
        return nil
    end

    local player = game:GetService("Players").LocalPlayer
    local levelValue = player:FindFirstChild("Data") and player.Data:FindFirstChild("Level")
    local level = levelValue and levelValue.Value or 0
    if level < 1500 then
        XyraxAutomation.SetThirdSeaStatus("Waiting for Level 1500")
        return nil
    end
    if not XyraxAutomation.SuperhumanBought then
        XyraxAutomation.SetThirdSeaStatus("Waiting for Superhuman")
        return nil
    end
    if not (XyraxAutomation.DeathStepOwned or xyraxOwnsTool("death step")) then
        XyraxAutomation.SetThirdSeaStatus("Waiting for Death Step")
        return nil
    end
    if not XyraxAutomation.OwnsSharkmanKarate() then
        XyraxAutomation.SetThirdSeaStatus("Waiting for Sharkman Karate")
        return nil
    end

    local state = XyraxAutomation.GetThirdSeaState()
    if state == 1 then
        XyraxAutomation.ThirdSeaAction = {Kind = "TravelZou"}
        XyraxAutomation.SetThirdSeaStatus("rip_indra defeated; travelling to Mr. Captain")
        return "Auto Third Sea"
    end
    if state == 0 then
        local enemy = xyraxFindEnemyByNames({"rip_indra"})
        XyraxAutomation.ThirdSeaAction = {Kind = "KillRipIndra"}
        XyraxAutomation.SetThirdSeaStatus(enemy and "Fighting rip_indra"
            or "Travelling to King Red Head to start the rip_indra encounter")
        return "Auto Third Sea"
    end
    -- Neither 0 nor 1: Level 1500 is already confirmed above, so per King Red
    -- Head's own dialogue this means Don Swan is not defeated yet.  Race V3
    -- (its own slot elsewhere in this same scheduler) owns that hunt - never
    -- duplicate it here, just yield.
    XyraxAutomation.ThirdSeaAction = nil
    XyraxAutomation.SetThirdSeaStatus("Waiting for Don Swan (owned by Auto Race V3)")
    return nil
end

-- Race V2 is deliberately a state machine owned by the movement scheduler.
-- It uses the server's Bartilo flags and Alchemist result codes as truth, so
-- a streamed-out map object, absent boss, or missing flower never becomes a
-- reason to leave the player standing still.
XyraxAutomation.RaceV2 = XyraxAutomation.RaceV2 or {
    BartiloVisits = {},
    PlateIndex = 1,
}
XyraxAutomation.RaceV2.Config = {
    Bartilo = CFrame.new(-456.28952, 73.0200958, 299.895966),
    Jeremy = CFrame.new(2099.88159, 448.931, 648.997375),
    Alchemist = CFrame.new(-2779.835, 72.966, -3574.020),
    Plates = {
        CFrame.new(-1850.49329, 13.1789551, 1750.89685),
        CFrame.new(-1858.87305, 19.3777466, 1712.01807),
        CFrame.new(-1803.94324, 16.5789185, 1750.89685),
        CFrame.new(-1858.55835, 16.8604317, 1724.79541),
        CFrame.new(-1869.54224, 15.987854, 1681.00659),
        CFrame.new(-1800.0979, 16.4978027, 1684.52368),
        CFrame.new(-1819.26343, 14.795166, 1717.90625),
        CFrame.new(-1813.51843, 14.8604736, 1724.79541),
    },
    -- The map calls the visible Blue object Flower1 and the visible Red
    -- object Flower2.  Confirmed live: picking up map object "Flower2"
    -- (Red) hands over an inventory Tool literally named "Flower 2" - no
    -- swap between map name and item name, matching the wiki's Flower 1 =
    -- Blue / Flower 2 = Red / Flower 3 = Yellow.  The previous "ids are
    -- swapped" mapping here was wrong and made RaceV2Flowers() never see a
    -- flower it had already collected, so it kept re-collecting Red forever.
    Flowers = {
        Red = {MapName = "Flower2", ToolNames = {"Flower 2", "Red Flower"}},
        Blue = {MapName = "Flower1", ToolNames = {"Flower 1", "Blue Flower"}},
        Yellow = {ToolNames = {"Flower 3", "Yellow Flower"}},
    },
}

XyraxAutomation.RaceV2Report = function(stage, detail)
    local message = tostring(stage) .. " | " .. tostring(detail or "")
    local runtime = XyraxAutomation.RaceV2
    XyraxAutomation.RaceV2Status = message
    if runtime.LastDebug ~= message then
        runtime.LastDebug = message
        print("[BfRef RaceV2] " .. message)
    end
end

XyraxAutomation.RaceV2Yield = function(reason, seconds)
    local runtime = XyraxAutomation.RaceV2
    runtime.Action = nil
    runtime.YieldUntil = math.max(runtime.YieldUntil or 0, os.clock() + (seconds or 8))
    XyraxAutomation.RaceV2Report("Yield", reason .. "; continuing other jobs")
end

-- Unlike RaceV2Yield, this keeps "Auto Race V2" as the active job instead of
-- releasing it back to Farm Level.  BartiloQuest is accepted through the
-- same StartQuest/AbandonQuest slot Farm Level's own quest uses: if Farm
-- Level takes over while the tracked "Defeat 50 Swan Pirates" card is on
-- screen, it sees a quest that does not match its current target and fires
-- AbandonQuest, wiping the Bartilo progress.  Waiting here in place - no
-- movement, no remotes - is what avoids that collision.
XyraxAutomation.RaceV2SetWaiting = function(reason, seconds)
    local runtime = XyraxAutomation.RaceV2
    local action = {Kind = "Wait", Detail = reason}
    runtime.Action = action
    -- Deliberately NOT runtime.YieldUntil: that field is the one field
    -- RaceV2GetAction() checks first, before anything else runs, to decide
    -- whether to hand the job to Farm Level/fruit at all.  Writing it here
    -- would silently re-arm that same hand-off on every following tick for
    -- the next `seconds`, undoing the whole point of "waiting in place".
    XyraxAutomation.RaceV2Report("Waiting", reason)
    return action
end

XyraxAutomation.RaceV2GetCommF = function()
    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
    return remotes and remotes:FindFirstChild("CommF_")
end

XyraxAutomation.RaceV2GetBartiloProgress = function()
    local runtime = XyraxAutomation.RaceV2
    if runtime.BartiloProgressAt and os.clock() - runtime.BartiloProgressAt < 1 then
        return runtime.BartiloProgress
    end
    runtime.BartiloProgressAt = os.clock()
    local commF = XyraxAutomation.RaceV2GetCommF()
    local ok, progress = pcall(function()
        return commF and commF:InvokeServer("BartiloQuestProgress")
    end)
    runtime.BartiloProgress = ok and type(progress) == "table" and progress or nil
    return runtime.BartiloProgress
end

XyraxAutomation.RaceV2GetAlchemistState = function(force)
    local runtime = XyraxAutomation.RaceV2
    if not force and runtime.AlchemistAt and os.clock() - runtime.AlchemistAt < 1 then
        return runtime.AlchemistState
    end
    runtime.AlchemistAt = os.clock()
    local commF = XyraxAutomation.RaceV2GetCommF()
    local ok, state = pcall(function()
        return commF and commF:InvokeServer("Alchemist", "1")
    end)
    runtime.AlchemistState = ok and state or nil
    return runtime.AlchemistState
end

XyraxAutomation.RaceV2HasItem = function(itemNames)
    local player = game:GetService("Players").LocalPlayer
    for _, container in ipairs({player.Character, player:FindFirstChild("Backpack")}) do
        if container then
            for _, item in ipairs(container:GetChildren()) do
                if item:IsA("Tool") then
                    local originalName = item:GetAttribute("OriginalName")
                    for _, acceptedName in ipairs(itemNames) do
                        if item.Name == acceptedName or originalName == acceptedName then
                            return true
                        end
                    end
                end
            end
        end
    end
    return false
end

XyraxAutomation.RaceV2Flowers = function()
    local result = {}
    for color, spec in pairs(XyraxAutomation.RaceV2.Config.Flowers) do
        result[color] = XyraxAutomation.RaceV2HasItem(spec.ToolNames)
    end
    return result
end

XyraxAutomation.RaceV2FindMapFlower = function(color)
    local runtime = XyraxAutomation.RaceV2
    local spec = XyraxAutomation.RaceV2.Config.Flowers[color]
    if not spec or not spec.MapName then
        return nil
    end

    -- Flowers are normally direct Workspace children.  Map descendants are
    -- a slower fallback for servers that stream them below Map instead.
    if not runtime.FlowerCacheAt or os.clock() - runtime.FlowerCacheAt >= 2 then
        runtime.FlowerCacheAt = os.clock()
        runtime.FlowerCache = {}
        for _, object in ipairs(workspace:GetChildren()) do
            if object.Name == "Flower1" or object.Name == "Flower2" then
                runtime.FlowerCache[object.Name] = object:IsA("BasePart") and object
                    or object:FindFirstChildWhichIsA("BasePart", true)
            end
        end
        local map = workspace:FindFirstChild("Map")
        if map and (not runtime.FlowerCache.Flower1 or not runtime.FlowerCache.Flower2) then
            for _, object in ipairs(map:GetDescendants()) do
                if (object.Name == "Flower1" or object.Name == "Flower2") and object:IsA("BasePart") then
                    runtime.FlowerCache[object.Name] = object
                end
            end
        end
    end
    return runtime.FlowerCache and runtime.FlowerCache[spec.MapName] or nil
end

XyraxAutomation.RaceV2IsDay = function()
    local clockTime = game:GetService("Lighting").ClockTime
    return clockTime >= 6 and clockTime < 18
end

-- Returns (enemy, source).  source == "Workspace" is live and fightable;
-- source == "ReplicatedStorage" is the same streaming-hint pattern the Sea 1
-- weapon bosses use (xyraxFindEnemyByNames/xyraxFindDistantEnemyByNames) - a
-- full model with Humanoid/HumanoidRootPart that has not streamed into
-- Workspace yet.  Never attack or edit that copy; it is only a coordinate to
-- travel toward so the server streams the real one in.
XyraxAutomation.RaceV2FindTarget = function(name)
    local enemies = workspace:FindFirstChild("Enemies")
    if enemies then
        for _, enemy in ipairs(enemies:GetChildren()) do
            local baseName = enemy.Name:match("^(.-)%s*%[") or enemy.Name
            local humanoid = enemy:FindFirstChild("Humanoid")
            local root = enemy:FindFirstChild("HumanoidRootPart")
            if baseName == name and humanoid and root and humanoid.Health > 0
                and not XyraxAutomation.IsDamageIgnored(enemy) then
                return enemy, "Workspace"
            end
        end
    end
    return xyraxFindDistantEnemyByNames({name})
end

-- Neither Workspace nor ReplicatedStorage has anything for a regular mob
-- (unlike a boss) until a player actually stands in its spawn zone - there
-- is no template to travel toward yet, only the empty map.  The game itself
-- marks these zones with a Part under _WorldOrigin.EnemySpawns named after
-- the mob (confirmed in the map dump: "Swan Pirate [Lv. 775]").  Use that as
-- a last-resort destination so the character walks into the zone instead of
-- waiting forever at Bartilo.
XyraxAutomation.RaceV2FindSpawnPoint = function(name)
    local worldOrigin = workspace:FindFirstChild("_WorldOrigin")
    local spawns = worldOrigin and worldOrigin:FindFirstChild("EnemySpawns")
    if not spawns then
        return nil
    end
    for _, marker in ipairs(spawns:GetChildren()) do
        local baseName = marker.Name:match("^(.-)%s*%[") or marker.Name
        if baseName == name and marker:IsA("BasePart") then
            return marker
        end
    end
    return nil
end

XyraxAutomation.RaceV2NpcDestination = function(name, fallback)
    local npcs = workspace:FindFirstChild("NPCs")
    local npc = (npcs and npcs:FindFirstChild(name)) or workspace:FindFirstChild(name)
    local root = npc and (npc.PrimaryPart or npc:FindFirstChild("HumanoidRootPart") or npc:FindFirstChild("Head"))
    return root and root:IsA("BasePart") and root.CFrame or fallback
end

XyraxAutomation.RaceV2Move = function(destination, key, range)
    local player = game:GetService("Players").LocalPlayer
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not (root and destination) then
        return false
    end
    if (root.Position - destination.Position).Magnitude <= (range or 8) then
        return true
    end
    local runtime = XyraxAutomation.RaceV2
    local tween = _G.TweenCache
    local tweenPlaying = tween and tween.PlaybackState == Enum.PlaybackState.Playing
    if runtime.MoveKey ~= key or not tweenPlaying or os.clock() - (runtime.MoveAt or 0) >= 0.8 then
        runtime.MoveKey = key
        runtime.MoveAt = os.clock()
        topos(destination)
    end
    return false
end

-- The modern tracked-quest card is a React component (GuideModule.
-- ReactComponents.TrackedQuestFrame): React mounts it as a plain "Frame"
-- under whatever key its parent chose, so there is no Instance actually
-- named "TrackedQuestFrame" to FindFirstChild in the live PlayerGui tree -
-- that lookup always missed and made this check worthless.  Scan every
-- descendant instead of guessing a container name.
function XyraxAutomation.RaceV2QuestWindowShows(text)
    local player = game:GetService("Players").LocalPlayer
    local gui = player:FindFirstChild("PlayerGui")
    if not gui then
        return false
    end
    for _, descendant in ipairs(gui:GetDescendants()) do
        if (descendant:IsA("TextLabel") or descendant:IsA("TextButton"))
            and string.find(descendant.Text, text, 1, true) then
            return true
        end
    end
    return false
end

XyraxAutomation.RaceV2HasBartiloQuest = function()
    return XyraxAutomation.RaceV2QuestWindowShows("Swan Pirate")
end

XyraxAutomation.RaceV2SetAction = function(kind, detail)
    local runtime = XyraxAutomation.RaceV2
    runtime.Action = {Kind = kind, Detail = detail}
    XyraxAutomation.RaceV2Action = runtime.Action
    XyraxAutomation.RaceV2Report(kind, detail)
    return runtime.Action
end

XyraxAutomation.RaceV2GetAction = function()
    local runtime = XyraxAutomation.RaceV2
    runtime.Action = nil
    XyraxAutomation.RaceV2Action = nil

    if not (World2 and XyraxAutomation.Desired.RaceV2) then
        return nil
    end
    local player = game:GetService("Players").LocalPlayer
    local data = player:FindFirstChild("Data")
    local levelValue = data and data:FindFirstChild("Level")
    local level = levelValue and levelValue.Value or 0
    if level < 850 then
        XyraxAutomation.RaceV2Report("Waiting", "Lv." .. tostring(level) .. "/850; Farm Level continues")
        return nil
    end
    local raceValue = data and data:FindFirstChild("Race")
    local race = raceValue and tostring(raceValue.Value) or "Unknown"
    if race == "Draco" then
        XyraxAutomation.Desired.RaceV2 = false
        XyraxAutomation.RaceV2Report("Done", "Draco is excluded from Alchemist V2")
        return nil
    end
    if os.clock() < (runtime.YieldUntil or 0) then
        return nil
    end

    local alchemistState = XyraxAutomation.RaceV2GetAlchemistState()
    if alchemistState == -2 then
        XyraxAutomation.Desired.RaceV2 = false
        XyraxAutomation.RaceV2Report("Done", race .. " V2 confirmed")
        return nil
    end
    if alchemistState == 5 then
        XyraxAutomation.Desired.RaceV2 = false
        XyraxAutomation.RaceV2Report("Done", "Alchemist reports Draco / unsupported race")
        return nil
    end

    local progress = XyraxAutomation.RaceV2GetBartiloProgress()
    if not progress then
        XyraxAutomation.RaceV2Yield("Bartilo state unavailable", 5)
        return nil
    end
    if not progress.KilledBandits then
        if not runtime.BartiloVisits.Start then
            return XyraxAutomation.RaceV2SetAction("BartiloStart", "travelling to Café")
        end
        if runtime.BartiloWindowLogged ~= true then
            -- Informational only: BartiloQuestProgress() is the actual
            -- source of truth for KilledBandits, so this never blocks
            -- farming - re-firing StartQuest on every miss would abandon
            -- and restart the quest, wiping real kill progress for nothing.
            -- A manual accept shows this card instantly with no natural
            -- delay to a human clicking through dialogue; checking once,
            -- ~1s after firing StartQuest, was catching the React card
            -- before it had actually rendered.  Keep rechecking briefly
            -- instead of trusting a single early read.
            if XyraxAutomation.RaceV2HasBartiloQuest() then
                runtime.BartiloWindowLogged = true
                print("[BfRef RaceV2] Swan Pirates quest card visible on screen: true")
            elseif runtime.BartiloWindowCheckUntil == nil then
                runtime.BartiloWindowCheckUntil = os.clock() + 5
            elseif os.clock() >= runtime.BartiloWindowCheckUntil then
                runtime.BartiloWindowLogged = true
                print("[BfRef RaceV2] Swan Pirates quest card still not visible after 5s")
            end
        end
        local swanEnemy, swanSource = XyraxAutomation.RaceV2FindTarget("Swan Pirate")
        if swanSource == "Workspace" then
            return XyraxAutomation.RaceV2SetAction("SwanPirates", "farming 50 Swan Pirates")
        end
        if swanSource == "ReplicatedStorage" then
            return XyraxAutomation.RaceV2SetAction("SwanPiratesTravel", "travelling to streamed Swan Pirate")
        end
        if XyraxAutomation.RaceV2FindSpawnPoint("Swan Pirate") then
            return XyraxAutomation.RaceV2SetAction("SwanPiratesZone", "walking into the Swan Pirate spawn zone")
        end
        -- The quest is already accepted and its card is on screen: hold the
        -- job here instead of yielding to Farm Level (see RaceV2SetWaiting).
        return XyraxAutomation.RaceV2SetWaiting("Swan Pirates not spawned yet", 5)
    end
    runtime.BartiloWindowLogged = nil
    runtime.BartiloWindowCheckUntil = nil
    runtime.BartiloVisits.Start = true

    if not progress.KilledSpring then
        if not runtime.BartiloVisits.Jeremy then
            return XyraxAutomation.RaceV2SetAction("BartiloJeremy", "returning after Swan Pirates")
        end
        if not XyraxAutomation.DamageBossBlocked("RaceV2:Jeremy") then
            local jeremyEnemy, jeremySource = XyraxAutomation.RaceV2FindTarget("Jeremy")
            if jeremySource == "Workspace" then
                return XyraxAutomation.RaceV2SetAction("Jeremy", "fighting Jeremy")
            end
            if jeremySource == "ReplicatedStorage" then
                return XyraxAutomation.RaceV2SetAction("JeremyTravel", "travelling to streamed Jeremy")
            end
        end
        -- Unlike Swan Pirates, this stage has no StartQuest/quest-card on
        -- screen for Farm Level to collide with (Bartilo's second dialogue
        -- is plain text, no Accept button - KilledSpring is a flag poll
        -- only).  Safe to release the job so Farm Level keeps earning while
        -- Jeremy is not around.
        XyraxAutomation.RaceV2Yield("Jeremy not spawned", 12)
        return nil
    end
    runtime.BartiloVisits.Jeremy = true

    if not progress.DidPlates then
        if not runtime.BartiloVisits.Plates then
            return XyraxAutomation.RaceV2SetAction("BartiloPlates", "returning after Jeremy")
        end
        local map = workspace:FindFirstChild("Map")
        local dressrosa = map and map:FindFirstChild("Dressrosa")
        local plates = dressrosa and dressrosa:FindFirstChild("BartiloPlates")
        if not plates then
            local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
            if root and (root.Position - XyraxAutomation.RaceV2.Config.Plates[1].Position).Magnitude > 20 then
                return XyraxAutomation.RaceV2SetAction("PlatesStream", "travelling to Colosseum to stream plates")
            end
            -- No quest card for this stage either (DidPlates is a flag
            -- poll, not a StartQuest); safe to release to Farm Level.
            XyraxAutomation.RaceV2Yield("Colosseum plates not streamed", 12)
            return nil
        end
        return XyraxAutomation.RaceV2SetAction("Plates", "solving Plate1 → Plate8")
    end
    runtime.BartiloVisits.Plates = true

    if alchemistState == 0 then
        return XyraxAutomation.RaceV2SetAction("AlchemistStart", "travelling to Green Zone")
    end
    if alchemistState == 1 then
        local flowers = XyraxAutomation.RaceV2Flowers()
        if not flowers.Red then
            -- Confirmed live: Red only actually grants the item during the
            -- day.  Its map Part can still exist at night as an inactive
            -- decoration, so checking for the Part alone (without the time
            -- gate) walks up to a flower the server will never let it pick,
            -- and it retries forever without ever collecting anything.
            if XyraxAutomation.RaceV2IsDay() then
                local red = XyraxAutomation.RaceV2FindMapFlower("Red")
                if red then
                    return XyraxAutomation.RaceV2SetAction("FlowerRed", "Red Flower found")
                end
                XyraxAutomation.RaceV2Yield("Red Flower not spawned", 10)
                return nil
            end
            XyraxAutomation.RaceV2Yield("waiting for daytime Red Flower", 10)
            return nil
        end
        if not flowers.Blue then
            -- Same reasoning as Red, mirrored: Blue only grants at night.
            if not XyraxAutomation.RaceV2IsDay() then
                local blue = XyraxAutomation.RaceV2FindMapFlower("Blue")
                if blue then
                    return XyraxAutomation.RaceV2SetAction("FlowerBlue", "Blue Flower found")
                end
                XyraxAutomation.RaceV2Yield("Blue Flower not spawned", 10)
                return nil
            end
            XyraxAutomation.RaceV2Yield("waiting for nighttime Blue Flower", 10)
            return nil
        end
        if not flowers.Yellow then
            XyraxAutomation.RaceV2Yield("Yellow Flower missing; Farm Level can drop it", 15)
            return nil
        end
        return XyraxAutomation.RaceV2SetAction("AlchemistRefresh", "all flowers collected; verifying")
    end
    if alchemistState == 2 then
        if xyraxGetBeli() >= 500000 then
            return XyraxAutomation.RaceV2SetAction("AlchemistPay", "all flowers ready; paying $500,000")
        end
        XyraxAutomation.RaceV2Yield("need $500,000 for Alchemist", 20)
        return nil
    end
    if alchemistState == -1 then
        XyraxAutomation.RaceV2Yield("need $500,000 for Alchemist", 20)
        return nil
    end
    XyraxAutomation.RaceV2Yield("Alchemist still locked; checking Bartilo again", 8)
    return nil
end

XyraxAutomation.RaceV2RunAction = function()
    if XyraxAutomation.ActiveJob ~= "Auto Race V2" or not _G.XyraxRaceV2 then
        return
    end
    local runtime = XyraxAutomation.RaceV2
    local action = runtime.Action
    if not action then
        return
    end
    local config = runtime.Config
    local commF = XyraxAutomation.RaceV2GetCommF()
    local player = game:GetService("Players").LocalPlayer
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not (commF and root) then
        XyraxAutomation.RaceV2Report("Waiting", "character / CommF unavailable")
        return
    end

    if action.Kind == "BartiloStart" or action.Kind == "BartiloJeremy" or action.Kind == "BartiloPlates" then
        if not XyraxAutomation.RaceV2Move(XyraxAutomation.RaceV2NpcDestination("Bartilo", config.Bartilo), "racev2-" .. action.Kind, 9) then
            return
        end
        if os.clock() < (runtime.NpcActionAt or 0) then
            return
        end
        runtime.NpcActionAt = os.clock() + 1
        local acceptFailed = false
        pcall(function()
            commF:InvokeServer("BartiloQuestProgress", "Bartilo")
            if action.Kind == "BartiloStart" and not XyraxAutomation.RaceV2HasBartiloQuest() then
                commF:InvokeServer("AbandonQuest")
                -- 0 = accepted, 2 = already completed (both fine to move on
                -- from); 1 = error, anything else = required level.  Never
                -- silently assume acceptance: BartiloQuest killing 50 Swan
                -- Pirates with no quest actually registered never advances
                -- KilledBandits, so this would farm Swan Pirates forever.
                local startResult = commF:InvokeServer("StartQuest", "BartiloQuest", 1)
                print("[BfRef RaceV2] StartQuest BartiloQuest result=" .. tostring(startResult))
                if startResult ~= 0 and startResult ~= 2 then
                    acceptFailed = true
                end
            end
        end)
        if action.Kind == "BartiloStart" then
            if not acceptFailed then
                runtime.BartiloVisits.Start = true
            end
        elseif action.Kind == "BartiloJeremy" then
            runtime.BartiloVisits.Jeremy = true
        else
            runtime.BartiloVisits.Plates = true
        end
        runtime.BartiloProgressAt = 0
        runtime.YieldUntil = os.clock() + 0.8
        XyraxAutomation.RaceV2Report("Bartilo", action.Kind .. (acceptFailed and " accept failed; retrying" or " confirmed"))
        return
    end

    if action.Kind == "SwanPiratesTravel" or action.Kind == "JeremyTravel" then
        local targetName = action.Kind == "JeremyTravel" and "Jeremy" or "Swan Pirate"
        local enemy, source = XyraxAutomation.RaceV2FindTarget(targetName)
        if source ~= "ReplicatedStorage" then
            -- Already streamed in (or despawned); next picker tick picks
            -- the correct next step on its own.
            return
        end
        local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
        if enemyRoot and enemyRoot:IsA("BasePart") then
            XyraxAutomation.RaceV2Move(enemyRoot.CFrame * CFrame.new(0, 30, 0), "racev2-travel-" .. targetName, 12)
        end
        return
    end

    if action.Kind == "SwanPiratesZone" then
        local marker = XyraxAutomation.RaceV2FindSpawnPoint("Swan Pirate")
        if marker then
            XyraxAutomation.RaceV2Move(marker.CFrame, "racev2-swan-zone", 15)
        end
        return
    end

    if action.Kind == "SwanPirates" or action.Kind == "Jeremy" then
        local targetName = action.Kind == "Jeremy" and "Jeremy" or "Swan Pirate"
        local enemy = XyraxAutomation.RaceV2FindTarget(targetName)
        local humanoid = enemy and enemy:FindFirstChild("Humanoid")
        local enemyRoot = enemy and enemy:FindFirstChild("HumanoidRootPart")
        if not (enemy and humanoid and enemyRoot and humanoid.Health > 0) then
            return
        end
        local context = "RaceV2 " .. targetName
        local damageState = XyraxAutomation.WatchDamage(enemy, context, action.Kind == "Jeremy" and 8 or 6, action.Kind == "Jeremy" and 1 or 0)
        if damageState == "retry" then
            XyraxAutomation.ResetDamageCombat()
        elseif damageState == "abandon" then
            if action.Kind == "Jeremy" then
                XyraxAutomation.BlockDamageBoss("RaceV2:Jeremy", context, 30)
            else
                XyraxAutomation.IgnoreDamageTarget(enemy, context, 20)
            end
            if action.Kind == "SwanPirates" then
                -- The Swan Pirates quest card is still on screen mid-fight;
                -- hold the job so Farm Level cannot see it and abandon it.
                XyraxAutomation.RaceV2SetWaiting(targetName .. " rejected damage")
            else
                -- Jeremy has no quest card to protect; let Farm Level earn
                -- while this target's block/ignore cooldown runs out.
                XyraxAutomation.RaceV2Yield(targetName .. " rejected damage", 8)
            end
            return
        end
        AutoHaki()
        EquipWeapon(_G.SelectWeapon)
        enemyRoot.CanCollide = false
        humanoid.WalkSpeed = 0
        enemyRoot.Size = Vector3.new(80, 80, 80)
        StartBring = XyraxAutomation.Desired.BringMob == true
        if not XyraxAutomation.RaceV2Move(enemyRoot.CFrame * CFrame.new(0, 30, 0), "racev2-fight-" .. targetName, 12) then
            return
        end
        XyraxAutomation.TryDarkStepV(context, enemy)
        pcall(sethiddenproperty, player, "SimulationRadius", math.huge)
        game:GetService("VirtualUser"):CaptureController()
        game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
        return
    end

    if action.Kind == "PlatesStream" then
        if XyraxAutomation.RaceV2Move(config.Plates[1], "racev2-plates-stream", 12) then
            -- No quest card here either; let Farm Level earn while the
            -- plates model streams in.
            XyraxAutomation.RaceV2Yield("Colosseum reached; waiting for plates to stream", 6)
        end
        return
    end

    if action.Kind == "Plates" then
        local plates = workspace:FindFirstChild("Map")
        plates = plates and plates:FindFirstChild("Dressrosa")
        plates = plates and plates:FindFirstChild("BartiloPlates")
        local index = runtime.PlateIndex or 1
        local plate = plates and plates:FindFirstChild("Plate" .. tostring(index))
        if not plate or not plate:IsA("BasePart") then
            runtime.PlateIndex = 1
            -- No quest card for this stage; let Farm Level earn instead of
            -- standing at a plate that de-streamed.
            XyraxAutomation.RaceV2Yield("Plate" .. tostring(index) .. " unavailable", 8)
            return
        end
        if not XyraxAutomation.RaceV2Move(plate.CFrame * CFrame.new(0, 2, 0), "racev2-plate-" .. tostring(index), 5) then
            return
        end
        if os.clock() < (runtime.PlateTouchAt or 0) then
            return
        end
        runtime.PlateTouchAt = os.clock() + 0.45
        root.CFrame = plate.CFrame * CFrame.new(0, 2, 0)
        if index < 8 then
            runtime.PlateIndex = index + 1
            XyraxAutomation.RaceV2Report("Plates", "touched Plate" .. tostring(index))
            return
        end
        local ok, completed = pcall(function()
            return commF:InvokeServer("BartiloQuestProgress", "DidPlates")
        end)
        runtime.PlateIndex = 1
        runtime.BartiloProgressAt = 0
        if ok and completed == true then
            runtime.YieldUntil = os.clock() + 1
            XyraxAutomation.RaceV2Report("Plates", "complete; Gladiators released")
        else
            -- No quest card for this stage; let Farm Level earn while the
            -- server confirms the last plate touch.
            XyraxAutomation.RaceV2Yield("plate confirmation pending; retrying safely", 4)
        end
        return
    end

    if action.Kind == "FlowerRed" or action.Kind == "FlowerBlue" then
        local color = action.Kind == "FlowerRed" and "Red" or "Blue"
        local flower = XyraxAutomation.RaceV2FindMapFlower(color)
        if not flower then
            XyraxAutomation.RaceV2Yield(color .. " Flower despawned", 8)
            return
        end
        if XyraxAutomation.RaceV2Move(flower.CFrame * CFrame.new(0, 2, 0), "racev2-flower-" .. color, 7) then
            root.CFrame = flower.CFrame * CFrame.new(0, 2, 0)
            runtime.FlowerCacheAt = 0
            runtime.YieldUntil = os.clock() + 1
            XyraxAutomation.RaceV2Report("Flowers", "collecting " .. color .. " Flower")
        end
        return
    end

    if action.Kind == "AlchemistStart" or action.Kind == "AlchemistPay" or action.Kind == "AlchemistRefresh" then
        if not XyraxAutomation.RaceV2Move(XyraxAutomation.RaceV2NpcDestination("Alchemist", config.Alchemist), "racev2-alchemist", 9) then
            return
        end
        if os.clock() < (runtime.NpcActionAt or 0) then
            return
        end
        runtime.NpcActionAt = os.clock() + 1
        local command = action.Kind == "AlchemistStart" and "2" or action.Kind == "AlchemistPay" and "3" or "1"
        local ok, result = pcall(function()
            return commF:InvokeServer("Alchemist", command)
        end)
        runtime.AlchemistAt = 0
        runtime.YieldUntil = os.clock() + 1
        XyraxAutomation.RaceV2Report("Alchemist", action.Kind .. " result=" .. tostring(ok and result or "failed"))
    end
end

if not XyraxAutomation.RaceV2WorkerStarted then
    XyraxAutomation.RaceV2WorkerStarted = true
    task.spawn(function()
        while XyraxAutomation.RaceV2WorkerStarted do
            task.wait(0.12)
            local ok, err = pcall(XyraxAutomation.RaceV2RunAction)
            if not ok then
                XyraxAutomation.RaceV2Yield("worker error", 5)
                XyraxAutomation.RaceV2Report("Error", tostring(err))
            end
        end
    end)
end

local function xyraxPickJob()
    -- Resolve completed weapon jobs before any priority decision.  This is
    -- what prevents an owned Saber (or any other completed weapon) from
    -- interrupting Auto Trident with a stale enabled flag.
    XyraxAutomation.DisableCompletedWeaponJobs()
    local desired = XyraxAutomation.Desired
    local player = game:GetService("Players").LocalPlayer
    local levelValue = player:FindFirstChild("Data") and player.Data:FindFirstChild("Level")
    local level = levelValue and levelValue.Value or 0

    -- Auto Raid sits above everything else, per explicit instruction -
    -- it still only claims the job while GetAutoRaidAction() finds
    -- something real to do (Fragment cap, a Chip/fruit/money to act on),
    -- so it never starves every other job when there's nothing to do.
    if desired.AutoRaid and XyraxAutomation.GetAutoRaidAction() then
        return "Auto Raid"
    end

    -- Missing Lightning Bolt is completed before the Sea 2 route.  Let that
    -- quest own movement first so a held bolt is returned, not skipped.
    local lightningAction = xyraxGetLightningBoltAction()
    if lightningAction then
        return "Auto Lightning Bolt"
    end

    -- Reaching Sea 2 is independent of Electric/Electro.  A Lightning Bolt
    -- may be retained for the later Electric purchase, but it must never
    -- prevent the Lv.700 Dressrosa route from starting.
    if desired.SecondSea and World1 and level >= 700 then
        return "Auto Second Sea"
    end
    -- Awakened Ice Admiral (and the rest of the Sea 2 Progression Boss
    -- table) must be able to interrupt an ongoing Superhuman mastery trip,
    -- not just Farm Level - moved above the Superhuman check for that
    -- reason.  It only claims the job while a live boss is actually found
    -- (Workspace OR ReplicatedStorage, via xyraxFindEnemyByNames); with no
    -- boss it falls straight through to Superhuman/Farm Level below rather
    -- than holding the slot.
    if desired.ProgressionBossSea2 and World2 then
        local progressionBossSea2 = XyraxAutomation.GetSea2ProgressionBoss()
        if progressionBossSea2 then
            XyraxAutomation.ProgressionBossSea2 = progressionBossSea2
            return "Auto Sea2 Progression Boss: " .. progressionBossSea2.Label
        end
        XyraxAutomation.ProgressionBossSea2 = nil
    end
    -- A held Water Key must be turned in immediately - it is a one-shot
    -- unlock the account should never sit on, so this sits above Sea2 Key
    -- (same "interrupt Superhuman" yield behaviour: no key held means no
    -- job claimed here, and this never fires unless Sharkman Karate is
    -- actually still outstanding).
    local waterKeyTurnInJob = XyraxAutomation.GetWaterKeyTurnInJob()
    if waterKeyTurnInJob then
        return waterKeyTurnInJob
    end
    -- Library Key / Hidden Key found mid-Farm (or right after Awakened Ice
    -- Admiral dies) must also be able to interrupt Superhuman, for the same
    -- reason as the boss above.  Same yield behaviour: no pending key means
    -- no job claimed here.
    local sea2KeyJob = XyraxAutomation.GetSea2KeyJob()
    if sea2KeyJob then
        return sea2KeyJob
    end
    -- Superhuman sits above Race V2 now: a Dark Step / Electric / Water
    -- Kung Fu purchase or mastery re-equip is a short, self-contained trip
    -- that should never be starved by an ongoing Colosseum quest chain.
    local superhumanAction = xyraxGetSuperhumanPhaseOneAction()
    if superhumanAction then
        return "Auto Superhuman: " .. superhumanAction.Kind .. " " .. superhumanAction.Stage.Label
    end
    -- Death Step only ever returns a job once Superhuman is bought and
    -- mastered (>=300) and Dark Step is re-mastered to >=400; it never waits
    -- at the Library door itself (Auto Sea2 Key above owns that) and never
    -- blocks waiting for money/Fragments, so it is safe to check right here.
    local deathStepJob = XyraxAutomation.GetDeathStepJob()
    if deathStepJob then
        return deathStepJob
    end
    -- Sharkman Karate sits right after Death Step, before Third Sea - Third
    -- Sea's own gate already requires XyraxAutomation.OwnsSharkmanKarate(),
    -- so once this job finishes buying it, Third Sea unblocks on its own
    -- with no change needed there.  Never blocks waiting for the Water Key/
    -- mastery/resources - it yields (nil) at every one of those gates so
    -- Third Sea/Race V2/V3/Farm Level still get the scheduler meanwhile.
    local sharkmanKarateJob = XyraxAutomation.GetSharkmanKarateJob()
    if sharkmanKarateJob then
        return sharkmanKarateJob
    end
    -- Auto Third Sea sits right after every Fighting Style requirement
    -- (Superhuman, Death Step, Sharkman Karate) and before Farm Level/Race,
    -- per its own gate.  It yields (nil) the instant Don Swan isn't
    -- confirmed yet, so Race V3 below still gets the scheduler to work on
    -- that - never held here waiting.
    local thirdSeaJob = XyraxAutomation.GetThirdSeaJob()
    if thirdSeaJob then
        return thirdSeaJob
    end
    -- Sea 2 Race V2 is intentionally above fruit movement.  It only returns
    -- an action while a real next step exists; spawn/time/money waits return
    -- nil so fruit, bosses, and Farm Level still get the scheduler.
    if XyraxAutomation.RaceV2GetAction() then
        return "Auto Race V2"
    end
    -- Race V3 sits right after V2 - same "one-time big progression unlock"
    -- class, requires V2 already done anyway, and returns nil the moment
    -- there is nothing to travel to (waiting for money/prerequisites/a
    -- manual-only race quest), so fruit/bosses/Farm Level still get it.
    if desired.RaceV3 and XyraxAutomation.GetRaceV3Action() then
        return "Auto Race V3"
    end
    if desired.TweenFruit and xyraxFindWorldFruit() then
        return "Auto Tween Fruit"
    end
    if desired.StoreFruit and xyraxFindStorableFruit() then
        return "Auto Store Fruit"
    end
    if World1 and desired.Saber and level >= 200 and not xyraxOwnsTool("saber") and xyraxCanProgressSaber() then
        return "Auto Saber"
    end
    -- Pole and Trident are held until Lv.300.  They are optional weapon
    -- hunts, so Farm Level remains uninterrupted until the account is ready
    -- to fight their higher-level bosses.  Saw/Warden keep their Lv.100 rule.
    if World1 and level >= 300 and desired.Pole and not xyraxOwnsSea1Weapon("Pole") and xyraxFindSea1WeaponBoss("Pole") then
        return "Auto Pole"
    end
    if World1 and level >= 100 and desired.Saw and not xyraxOwnsSea1Weapon("Saw") and xyraxFindSea1WeaponBoss("Saw") then
        return "Auto Saw"
    end
    if desired.ProgressionBoss and World1 then
        local progressionBoss = xyraxGetSea1ProgressionBoss()
        if progressionBoss then
            XyraxAutomation.ProgressionBoss = progressionBoss
            return "Auto Progression Boss: " .. progressionBoss.Label
        end
        XyraxAutomation.ProgressionBoss = nil
    end
    if desired.MidnightBlade and XyraxAutomation.GetMidnightBladeAction() then
        return "Auto Midnight Blade"
    end
    if World1 and level >= 100 and desired.Warden and not xyraxOwnsSea1Weapon("Warden") and xyraxFindSea1WeaponBoss("Warden") then
        return "Auto Warden"
    end
    if World1 and level >= 300 and desired.Trident and not xyraxOwnsSea1Weapon("Trident") and xyraxFindSea1WeaponBoss("Trident") then
        return "Auto Trident"
    end
    -- Held off in Sea 2 for now: only Auto Race V2 sits above Farm Level
    -- there until a Sea 2 Progression Boss route exists like Sea 1's.
    if World1 and desired.FarmBoss and _G.SelectBoss
        and not (World1 and desired.ProgressionBoss)
        and not XyraxAutomation.DamageBossBlocked("Manual:" .. tostring(_G.SelectBoss))
        and xyraxFindLiveEnemy(_G.SelectBoss) then
        return "Auto Farm Boss"
    end
    if desired.FarmLevel then
        return "Farm Level"
    end
    return "Idle"
end

local function xyraxIsSuperhumanJob(job)
    return type(job) == "string" and string.sub(job, 1, #"Auto Superhuman") == "Auto Superhuman"
end

function xyraxIsLightningBoltJob(job)
    return job == "Auto Lightning Bolt"
end

local function xyraxIsProgressionBossJob(job)
    return type(job) == "string" and string.sub(job, 1, #"Auto Progression Boss") == "Auto Progression Boss"
end

-- Named "Auto Sea2 Progression Boss" (Sea2 first) so this prefix never
-- collides with xyraxIsProgressionBossJob above.
function XyraxAutomation.IsProgressionBossSea2Job(job)
    return type(job) == "string" and string.sub(job, 1, #"Auto Sea2 Progression Boss") == "Auto Sea2 Progression Boss"
end

-- Underwater City is shared by several independent jobs.  Treat it as a
-- route/state owned by the scheduler instead of letting each job teleport on
-- its own: this keeps a Fishman Farm Level job inside after Fishman Lord dies,
-- but sends the player through the real exit before a later outside job moves.
XyraxAutomation.RequiresUnderwater = function(job)
    if not World1 then
        return false
    end
    if job == "Auto Trident" then
        return true
    end
    if job == "Auto Superhuman: Buy Water Kung Fu" then
        return true
    end
    if job == "Auto Farm Boss" then
        local selectedBoss = tostring(_G.SelectBoss or SelectBoss or "")
        return selectedBoss == "Fishman Lord"
    end
    if job ~= "Farm Level" then
        return false
    end

    -- Normal level progression uses Fishman Warrior at 375-399 and Fishman
    -- Commando at 400-449.  Mon/NameMon also cover a manually selected
    -- Fishman target without relying only on the level range.
    local player = game:GetService("Players").LocalPlayer
    local data = player:FindFirstChild("Data")
    local levelValue = data and data:FindFirstChild("Level")
    local level = levelValue and levelValue.Value or 0
    local farmMonster = tostring(Mon or NameMon or _G.SelectMonster or SelectMonster or "")
    return (level >= 375 and level <= 449)
        or farmMonster == "Fishman Warrior"
        or farmMonster == "Fishman Commando"
end

XyraxAutomation.IsInUnderwater = function()
    if not World1 then
        return false
    end
    local player = game:GetService("Players").LocalPlayer
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not root then
        return false
    end
    -- Coordinate ownership is reliable while the Fishmen map section is
    -- being streamed in or out.
    return root.Position.X > 50000
end

XyraxAutomation.UseUnderwaterRoute = function(entering)
    local player = game:GetService("Players").LocalPlayer
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not root then
        XyraxAutomation.UnderwaterState = "Waiting for character"
        return false
    end

    local map = workspace:FindFirstChild("Map")
    -- Sea 1's real entry is the Whirlpool touch part, not the destination
    -- point.  AnimateEntrance connects Map.TeleportSpawn.Entrance.Touched,
    -- then its own handler invokes requestEntrance with EntrancePoint.Position.
    -- Walk to that touch part first so the normal client interaction owns the
    -- transition and never receives a long-range entrance request.
    if entering then
        local teleportSpawn = map and map:FindFirstChild("TeleportSpawn")
        local entrance = teleportSpawn and teleportSpawn:FindFirstChild("Entrance")
        local entrancePoint = teleportSpawn and teleportSpawn:FindFirstChild("EntrancePoint")
        if not (entrance and entrance:IsA("BasePart") and entrancePoint and entrancePoint:IsA("BasePart")) then
            XyraxAutomation.UnderwaterState = "Waiting for Underwater Whirlpool"
            return false
        end

        -- This is the same proximity test used by AnimateEntrance before it
        -- calls doWhirlpoolTeleport(Entrance, TeleportSpawn.EntrancePoint).
        local interactionRange = root.Size.Y * 2 + entrance.Size.X / 2
        if (root.Position - entrance.Position).Magnitude > interactionRange then
            XyraxAutomation.UnderwaterState = "Entering Underwater: travelling to Whirlpool"
            topos(CFrame.new(entrance.Position))
            task.wait(0.1)
            return false
        end

        XyraxAutomation.UnderwaterState = "Entering Underwater: using Whirlpool"
        local character = player.Character
        -- AnimateEntrance accepts a normal character limb (not HumanoidRootPart)
        -- in its Touched listener.  Use the same interaction when available.
        local touchPart = character and (character:FindFirstChild("Head")
            or character:FindFirstChild("UpperTorso")
            or character:FindFirstChild("LowerTorso"))
        if type(firetouchinterest) == "function" and touchPart and touchPart:IsA("BasePart") then
            local ok, err = pcall(function()
                firetouchinterest(touchPart, entrance, 0)
                task.wait(0.1)
                firetouchinterest(touchPart, entrance, 1)
            end)
            if not ok then
                warn("[Underwater] Whirlpool interaction failed: " .. tostring(err))
            end
        else
            -- Fallback is the exact request made by AnimateEntrance, but it is
            -- reached only after the character is inside the touch range above.
            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
            local commF = remotes and remotes:FindFirstChild("CommF_")
            if not commF then
                XyraxAutomation.UnderwaterState = "Waiting for CommF"
                return false
            end
            local ok, result = pcall(function()
                return commF:InvokeServer("requestEntrance", entrancePoint.Position)
            end)
            if not ok then
                warn("[Underwater] requestEntrance failed: " .. tostring(result))
                XyraxAutomation.UnderwaterState = "Underwater entrance remote failed"
                return false
            end
        end

        -- Do not let Farm Level resume on the request alone.  Wait for the
        -- destination's verified coordinate ownership before releasing it.
        local confirmUntil = os.clock() + 5
        repeat
            task.wait(0.1)
            if XyraxAutomation.IsInUnderwater() then
                XyraxAutomation.UnderwaterState = "Settling Underwater entry"
                task.wait(1.5)
                XyraxAutomation.UnderwaterRouteGraceUntil = os.clock() + 2
                XyraxAutomation.UnderwaterState = "Inside Underwater"
                return true
            end
        until os.clock() >= confirmUntil

        XyraxAutomation.UnderwaterState = "Underwater entrance not confirmed"
        return false
    end

    -- The reverse flow is also a Whirlpool touch: AnimateEntrance connects
    -- TeleportSpawn.Exit.Touched and routes it to TeleportSpawn.ExitPoint.
    -- Do not request that destination until the character has reached Exit.
    local teleportSpawn = map and map:FindFirstChild("TeleportSpawn")
    local exit = teleportSpawn and teleportSpawn:FindFirstChild("Exit")
    local exitPoint = teleportSpawn and teleportSpawn:FindFirstChild("ExitPoint")
    if not (exit and exit:IsA("BasePart") and exitPoint and exitPoint:IsA("BasePart")) then
        XyraxAutomation.UnderwaterState = "Waiting for Underwater Exit"
        return false
    end

    local interactionRange = root.Size.Y * 2 + exit.Size.X / 2
    if (root.Position - exit.Position).Magnitude > interactionRange then
        XyraxAutomation.UnderwaterState = "Leaving Underwater: travelling to Exit"
        topos(CFrame.new(exit.Position))
        task.wait(0.1)
        return false
    end

    XyraxAutomation.UnderwaterState = "Leaving Underwater: using Exit"
    local character = player.Character
    local touchPart = character and (character:FindFirstChild("Head")
        or character:FindFirstChild("UpperTorso")
        or character:FindFirstChild("LowerTorso"))
    if type(firetouchinterest) == "function" and touchPart and touchPart:IsA("BasePart") then
        local ok, err = pcall(function()
            firetouchinterest(touchPart, exit, 0)
            task.wait(0.1)
            firetouchinterest(touchPart, exit, 1)
        end)
        if not ok then
            warn("[Underwater] Exit interaction failed: " .. tostring(err))
        end
    else
        -- Same server request made by AnimateEntrance's Exit handler, reached
        -- only after the character is within that handler's touch distance.
        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
        local commF = remotes and remotes:FindFirstChild("CommF_")
        if not commF then
            XyraxAutomation.UnderwaterState = "Waiting for CommF"
            return false
        end
        local ok, result = pcall(function()
            return commF:InvokeServer("requestEntrance", exitPoint.Position)
        end)
        if not ok then
            warn("[Underwater] exit requestEntrance failed: " .. tostring(result))
            XyraxAutomation.UnderwaterState = "Underwater exit remote failed"
            return false
        end
    end

    -- Keep the next job disabled until the exit is physically confirmed, just
    -- as Cursed Ship's route waits for its transition before releasing work.
    local confirmUntil = os.clock() + 5
    repeat
        task.wait(0.1)
        if not XyraxAutomation.IsInUnderwater() then
            XyraxAutomation.UnderwaterState = "Settling Underwater exit"
            task.wait(1.5)
            XyraxAutomation.UnderwaterRouteGraceUntil = os.clock() + 2
            XyraxAutomation.UnderwaterState = "Outside Underwater"
            return true
        end
    until os.clock() >= confirmUntil

    XyraxAutomation.UnderwaterState = "Underwater exit not confirmed"
    return false
end

-- Cursed Ship (Sea2, Farm Level's own Lv.1250-1349 route: Ship Deckhand/
-- Engineer/Steward/Officer).  Entering already happens inline in CheckQuest
-- (BfRef.lua:795-855) via the same OutShip/InShip + requestEntrance pair used
-- here.  This only covers leaving: the same class of "raw tween out of a
-- gated zone leaves the character stuck/slow" problem the Underwater route
-- above solves, confirmed for this ship by the wrong-zone bugs already
-- documented near xyraxFarmMove (BfRef.lua:6779-6805).
XyraxAutomation.CursedShipInShip = Vector3.new(922, 125, 32851)
XyraxAutomation.CursedShipOutShip = Vector3.new(-6506, 83, -127)

XyraxAutomation.RequiresCursedShip = function(job)
    if not World2 then
        return false
    end
    -- El Admin (Midnight Blade's Ectoplasm trader) sits inside the ship too -
    -- confirmed via the manual Teleport NPC list's own El Admin CFrame
    -- (BfRef.lua:20685, ~490 studs from CursedShipInShip).  Ectoplasm itself
    -- is only ever generated by mobs killed AT the ship (see
    -- GetMidnightBladeAction's own comment above), so this job is only ever
    -- selected while the character is already there - forcing an exit first
    -- would just strand it outside with nothing to walk to.
    if job == "Auto Midnight Blade" then
        return true
    end
    if job ~= "Farm Level" then
        return false
    end
    local farmMonster = tostring(Mon or NameMon or _G.SelectMonster or SelectMonster or "")
    return farmMonster == "Ship Deckhand" or farmMonster == "Ship Engineer"
        or farmMonster == "Ship Steward" or farmMonster == "Ship Officer"
end

XyraxAutomation.IsInCursedShip = function()
    if not World2 then
        return false
    end
    local player = game:GetService("Players").LocalPlayer
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not root then
        return false
    end
    return (root.Position - XyraxAutomation.CursedShipInShip).Magnitude <= 2000
end

-- Mirrors the entering half in CheckQuest (BfRef.lua:795-855): walk to the
-- gate first, then request the crossing - rather than an instant CFrame
-- snap.  Safe to use topos() here (unlike a raw check earlier in the
-- scheduler tick): xyraxDisableMovementJobs()/xyraxCancelActiveTween() have
-- already run by the time this is called, so Farm Level's own worker (gated
-- on _G.AutoFarm) is no longer fighting for the same tween proxy.
XyraxAutomation.LeaveCursedShip = function()
    local player = game:GetService("Players").LocalPlayer
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not root then
        return
    end
    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
    local commF = remotes and remotes:FindFirstChild("CommF_")
    if not commF then
        return
    end

    XyraxAutomation.CursedShipStatus = "Leaving Cursed Ship: walking to the door"
    print("[BfRef CursedShip] " .. XyraxAutomation.CursedShipStatus)
    local gate = XyraxAutomation.CursedShipInShip
    local attempts = 0
    while root.Parent and (root.Position - gate).Magnitude > 10 and attempts < 100 do
        topos(CFrame.new(gate))
        task.wait(0.1)
        attempts = attempts + 1
        root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        if not root then
            return
        end
    end
    task.wait(0.5)

    XyraxAutomation.CursedShipStatus = "Leaving Cursed Ship (ghost door)"
    print("[BfRef CursedShip] " .. XyraxAutomation.CursedShipStatus)
    local destination = XyraxAutomation.CursedShipOutShip
    task.spawn(function()
        local ok, err = pcall(function()
            commF:InvokeServer("requestEntrance", destination)
        end)
        if not ok then
            warn("[BfRef CursedShip] exit requestEntrance failed: " .. tostring(err))
        end
    end)
    root.CFrame = CFrame.new(destination)
    task.wait()
    if root.Parent then
        root.CFrame = CFrame.new(destination + Vector3.new(0, 0.1, 0))
    end
    task.wait(1.5)
    XyraxAutomation.CursedShipStatus = "Left Cursed Ship"
end

local function xyraxDisableMovementJobs()
    _G.AutoRaid = false
    _G.AutoFarm = false
    _G.AutoBoss = false
    _G.AutoProgressionBoss = false
    _G.AutoProgressionBossSea2 = false
    _G.AutoMidnightBlade = false
    _G.AutoRaceV3 = false
    AutoSaber = false
    _G.Autopole = false
    _G.Autosaw = false
    _G.ChiefWarden = false
    _G.Trident = false
    _G.XyraxSea1WeaponBoss = nil
    _G.AutoSecondSea = false
    _G.XyraxRaceV2 = false
    _G.AutoBartilo = false -- prevents the old independent Bartilo loop racing this state machine
    _G.TweenFruit = false
    _G.AutoStoreFruit = false
    _G.AutoLightningBolt = false
    _G.XyraxSaberLockedTool = nil
    StartBring = false
end

local function xyraxEnableMovementJob(job)
    if job == "Auto Raid" then
        _G.AutoRaid = true
    elseif job == "Auto Second Sea" then
        _G.AutoSecondSea = true
    elseif job == "Auto Race V2" then
        _G.XyraxRaceV2 = true
    elseif job == "Auto Tween Fruit" then
        _G.TweenFruit = true
    elseif job == "Auto Store Fruit" then
        _G.AutoStoreFruit = true
    elseif job == "Auto Lightning Bolt" then
        _G.AutoLightningBolt = true
    elseif job == "Auto Saber" then
        AutoSaber = true
    elseif job == "Auto Pole" then
        _G.XyraxSea1WeaponBoss = "Pole"
    elseif job == "Auto Saw" then
        _G.XyraxSea1WeaponBoss = "Saw"
    elseif job == "Auto Warden" then
        _G.XyraxSea1WeaponBoss = "Warden"
    elseif job == "Auto Trident" then
        _G.XyraxSea1WeaponBoss = "Trident"
    elseif XyraxAutomation.IsProgressionBossSea2Job(job) then
        _G.AutoProgressionBossSea2 = true
    elseif job == "Auto Midnight Blade" then
        _G.AutoMidnightBlade = true
    elseif job == "Auto Race V3" then
        _G.AutoRaceV3 = true
    elseif xyraxIsProgressionBossJob(job) then
        _G.AutoProgressionBoss = true
    elseif job == "Auto Farm Boss" then
        _G.AutoBoss = true
    elseif job == "Farm Level" then
        _G.AutoFarm = true
    end
end

-- One scheduler-owned worker handles Pole / Saw / Warden / Trident.  The
-- legacy workers further down are deliberately left inactive by the scheduler
-- so no old exact-name or ReplicatedStorage fallback can start a second tween.
local function xyraxTravelToDistantBoss(root, key)
    if not root then
        return
    end
    local destination = root.CFrame * CFrame.new(0, 30, 0)
    local playerRoot = game:GetService("Players").LocalPlayer.Character
        and game:GetService("Players").LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    if not playerRoot or (playerRoot.Position - destination.Position).Magnitude <= 12 then
        return
    end

    local move = XyraxAutomation.DistantBossMove or {}
    local tween = _G.TweenCache
    local tweenPlaying = tween and tween.PlaybackState == Enum.PlaybackState.Playing
    local now = os.clock()
    if move.Key ~= key or not tweenPlaying or now - (move.At or 0) >= 0.8 then
        XyraxAutomation.DistantBossMove = {Key = key, At = now}
        TP1(destination)
    end
end

task.spawn(function()
    while task.wait(0.08) do
        local key = _G.XyraxSea1WeaponBoss
        local spec = key and xyraxSea1WeaponBosses[key]
        if spec then
            pcall(function()
                local enemy, source = xyraxFindSea1WeaponBoss(key)
                local humanoid = enemy and enemy:FindFirstChild("Humanoid")
                local root = enemy and enemy:FindFirstChild("HumanoidRootPart")
                if not (enemy and humanoid and root and humanoid.Health > 0) then
                    return
                end

                -- A distant model is a travel hint only.  Do not modify or
                -- attack it until Streaming moves the same boss into
                -- Workspace.Enemies and the next pass confirms it live.
                if source == "ReplicatedStorage" then
                    XyraxAutomation.DistantBossStatus = "Travelling to " .. enemy.Name
                    xyraxTravelToDistantBoss(root, key)
                    return
                end

                XyraxAutomation.DistantBossStatus = "Farming " .. enemy.Name
                AutoHaki()
                EquipWeapon(_G.SelectWeapon)
                local damageState = XyraxAutomation.WatchDamage(enemy, spec.Job, 8, 1)
                if damageState == "retry" then
                    XyraxAutomation.ResetDamageCombat()
                elseif damageState == "abandon" then
                    XyraxAutomation.BlockDamageBoss("Weapon:" .. tostring(key), spec.Job .. ": " .. enemy.Name, XyraxAutomation.DamageBossBlockSeconds)
                    XyraxAutomation.ResetDamageCombat()
                    return
                end
                root.CanCollide = false
                humanoid.WalkSpeed = 0
                root.Size = Vector3.new(80, 80, 80)
                StartBring = true
                topos(root.CFrame * CFrame.new(0, 30, 0))
                XyraxAutomation.TryDarkStepV(spec.Job, enemy)
                sethiddenproperty(game:GetService("Players").LocalPlayer, "SimulationRadius", math.huge)
                if spec.FastAttack then
                    AttackNoCD()
                else
                    game:GetService("VirtualUser"):CaptureController()
                    game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
                end
            end)
        end
    end
end)

local function xyraxCancelActiveTween()
    local tween = _G.TweenCache
    if tween then
        pcall(function()
            tween:Cancel()
        end)
    end
end

task.spawn(function()
    local activeJob = nil
    while task.wait(0.35) do
        local nextJob = xyraxPickJob()
        local nextJobNeedsUnderwater = XyraxAutomation.RequiresUnderwater(nextJob)
        local isInUnderwater = XyraxAutomation.IsInUnderwater()
        local now = os.clock()

        -- Farm Level (Fishman) and Auto Trident share this same route.  A
        -- transient higher-priority scan must not eject the player and then
        -- force another entrance a fraction of a second later.  Hold the
        -- current underwater job for the short entrance transition, then
        -- require a non-underwater job to remain selected for two seconds.
        if isInUnderwater and not nextJobNeedsUnderwater and activeJob
            and XyraxAutomation.RequiresUnderwater(activeJob) then
            local graceUntil = XyraxAutomation.UnderwaterRouteGraceUntil or 0
            local exit = XyraxAutomation.UnderwaterExitCandidate
            if now < graceUntil then
                nextJob = activeJob
                nextJobNeedsUnderwater = true
            elseif not exit or exit.Job ~= nextJob then
                XyraxAutomation.UnderwaterExitCandidate = {Job = nextJob, At = now}
                nextJob = activeJob
                nextJobNeedsUnderwater = true
            elseif now - exit.At < 2 then
                nextJob = activeJob
                nextJobNeedsUnderwater = true
            else
                XyraxAutomation.UnderwaterExitCandidate = nil
            end
        else
            XyraxAutomation.UnderwaterExitCandidate = nil
        end

        -- A manual exit/entry while the same job is active is also repaired
        -- here.  Only this scheduler is allowed to make the route change.
        if nextJob ~= activeJob or nextJobNeedsUnderwater ~= isInUnderwater then
            -- TEMP DEBUG (TransitionDebug): snapshot state right at the
            -- moment the scheduler decides to switch jobs, specifically for
            -- the Farm Level -> Auto Superhuman case (the reported freeze).
            -- Compare these timestamps against the xyraxFarmMove->TP1 /
            -- xyraxSuperhumanMove->TP1 lines to see whether Farm still fires
            -- TP1 after this point.  Remove once diagnosed.
            if activeJob == "Farm Level" and type(nextJob) == "string"
                and string.sub(nextJob, 1, #"Auto Superhuman") == "Auto Superhuman" then
                local player = game:GetService("Players").LocalPlayer
                local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                local tween = _G.TweenCache
                print(string.format(
                    "[BfRef TransitionDebug] SWITCH %s -> %s | t=%.2f AutoFarm=%s StartBring=%s TweenPlaying=%s RootAnchored=%s RootPos=%s",
                    tostring(activeJob), tostring(nextJob), os.clock(),
                    tostring(_G.AutoFarm), tostring(StartBring),
                    tostring(tween and tween.PlaybackState == Enum.PlaybackState.Playing),
                    tostring(root and root.Anchored),
                    tostring(root and root.Position)))
            end
            xyraxDisableMovementJobs()
            xyraxCancelActiveTween()

            -- Cursed Ship (Sea2, Lv.1250-1349 Farm Level route) needs its own
            -- exit ("ghost door") fired before ANY other job's movement takes
            -- over - confirmed live: Auto Raid (and the same applies to Tween
            -- Fruit/Store Fruit/any other job) just tweened straight off the
            -- ship through open water once it claimed the scheduler, which
            -- can kill the character.  Must run here, AFTER
            -- xyraxDisableMovementJobs()/xyraxCancelActiveTween() above - the
            -- exact same "stale Farm tween reclaims movement" race the
            -- Underwater route below already avoids by running in this same
            -- position.  Gated purely on physical position, not on what the
            -- previous job was, since the character can end up on the ship
            -- for reasons other than Farm Level (manual teleport, etc.).
            if not XyraxAutomation.RequiresCursedShip(nextJob) and XyraxAutomation.IsInCursedShip() then
                XyraxAutomation.LeaveCursedShip()
            end

            local routeReady = true
            if nextJobNeedsUnderwater and not isInUnderwater then
                routeReady = XyraxAutomation.UseUnderwaterRoute(true)
            elseif not nextJobNeedsUnderwater and isInUnderwater then
                routeReady = XyraxAutomation.UseUnderwaterRoute(false)
            end
            if routeReady then
                task.wait(0.12)
                xyraxEnableMovementJob(nextJob)
                activeJob = nextJob
                XyraxAutomation.ActiveJob = nextJob
                XyraxEnvironment.XyraxSchedulerStatus = nextJob
            else
                XyraxAutomation.ActiveJob = XyraxAutomation.UnderwaterState
                XyraxEnvironment.XyraxSchedulerStatus = XyraxAutomation.UnderwaterState
                -- Leave activeJob unchanged so the next scheduler pass retries
                -- the route before any movement job can start.
            end
        end
    end
end)

-- Auto Progression Boss owns movement only while the appropriate Sea 1 boss
-- is alive.  It never waits at a spawn point: a despawn returns control to
-- Farm Level on the scheduler's next pass.
local xyraxProgressionBossMoveAt = 0
local xyraxProgressionBossMoveKey = nil
local xyraxProgressionQuestActionAt = 0
local xyraxProgressionEntranceAt = 0
local function xyraxProgressionBossMove(destination, key)
    local player = game:GetService("Players").LocalPlayer
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not (root and destination) then
        return false
    end
    if (root.Position - destination.Position).Magnitude <= 6 then
        return true
    end
    local tweenPlaying = _G.TweenCache and _G.TweenCache.PlaybackState == Enum.PlaybackState.Playing
    if xyraxProgressionBossMoveKey ~= key or not tweenPlaying or os.clock() - xyraxProgressionBossMoveAt >= 0.8 then
        xyraxProgressionBossMoveKey = key
        xyraxProgressionBossMoveAt = os.clock()
        TP1(destination)
    end
    return false
end

local function xyraxProgressionQuestAction(...)
    if os.clock() - xyraxProgressionQuestActionAt < 1 then
        return false
    end
    xyraxProgressionQuestActionAt = os.clock()
    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
    local commF = remotes and remotes:FindFirstChild("CommF_")
    if not commF then
        return false
    end
    local args = {...}
    return pcall(function()
        return commF:InvokeServer(unpack(args))
    end)
end

local function xyraxGuiContainsAny(gui, names)
    if not gui then
        return false
    end
    for _, item in ipairs(gui:GetDescendants()) do
        if item:IsA("TextLabel") or item:IsA("TextButton") then
            for _, name in ipairs(names) do
                if string.find(item.Text or "", name, 1, true) then
                    return true
                end
            end
        end
    end
    return false
end

local function xyraxProgressionQuestState(boss)
    local playerGui = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
    local main = playerGui and playerGui:FindFirstChild("Main")
    local legacyQuest = main and main:FindFirstChild("Quest")
    if legacyQuest and legacyQuest.Visible then
        return true, xyraxGuiContainsAny(legacyQuest, boss.QuestTargets)
    end

    -- Update-30 can keep the visible quest in TrackedQuestFrame rather than
    -- Main.Quest.  The old test returned true only when it already matched
    -- the requested boss, leaving a Shanda quest looking like "no quest" and
    -- making StartQuest for Sky Warlord fail silently at the NPC.
    if type(getGuideQuestData) == "function" then
        local guideQuestData = getGuideQuestData()
        if type(guideQuestData) == "table" then
            local task = guideQuestData.Task
            if type(task) == "table" then
                local hasTask = false
                local matches = false
                for _ in pairs(task) do
                    hasTask = true
                    break
                end
                for _, targetName in ipairs(boss.QuestTargets) do
                    if task[targetName] ~= nil then
                        matches = true
                        break
                    end
                end
                -- Shanda and Sky Warlord share SkyExp1Quest.  When the
                -- authoritative task list is present it, not the shared
                -- InternalQuestName, decides whether this is the right quest.
                if hasTask then
                    return true, matches
                end
            end
            return true, guideQuestData.InternalQuestName == boss.QuestName
        end
    end

    local tracked = playerGui and playerGui:FindFirstChild("TrackedQuestFrame")
    if tracked and tracked.Parent ~= nil then
        return true, xyraxGuiContainsAny(tracked, boss.QuestTargets)
    end
    return false, false
end

local xyraxLastProgressionBossStatus = nil
local function xyraxSetProgressionBossStatus(status)
    XyraxAutomation.ProgressionBossStatus = status
    if status ~= xyraxLastProgressionBossStatus then
        xyraxLastProgressionBossStatus = status
        print("[BfRef Progression Boss] " .. status)
    end
end

local function xyraxProgressionQuestGiverCFrame(boss)
    -- The normal farm already uses this current Guide-data lookup.  Retain a
    -- verified map fallback so temporarily unloaded NPCs cannot halt a boss
    -- quest.
    if type(findQuestGiver) == "function" then
        local ok, giver = pcall(findQuestGiver, boss.QuestName)
        if ok and giver and giver.CFrame then
            return giver.CFrame
        end
    end
    return boss.QuestCFrame
end

task.spawn(function()
    while task.wait(0.15) do
        if _G.AutoProgressionBoss then
            pcall(function()
                local boss, enemy, enemySource = xyraxGetSea1ProgressionBoss()
                if not boss then
                    return
                end

                local questVisible, questMatches = xyraxProgressionQuestState(boss)
                if questVisible and not questMatches then
                    xyraxSetProgressionBossStatus("Abandoning unrelated quest")
                    xyraxProgressionQuestAction("AbandonQuest")
                    return
                end

                if not questMatches then
                    local player = game:GetService("Players").LocalPlayer
                    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                    local questCFrame = xyraxProgressionQuestGiverCFrame(boss)
                    if not (root and questCFrame) then
                        return
                    end
                    if boss.Entrance and (root.Position - questCFrame.Position).Magnitude > 10000
                        and os.clock() - xyraxProgressionEntranceAt >= 2 then
                        xyraxProgressionEntranceAt = os.clock()
                        pcall(function()
                            game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("requestEntrance", boss.Entrance)
                        end)
                    end
                    xyraxSetProgressionBossStatus("Getting " .. boss.Label .. " quest")
                    if xyraxProgressionBossMove(questCFrame, "progression-quest:" .. boss.QuestName) then
                        -- Recheck immediately before spending a quest action:
                        -- if another player killed the boss en route, leave
                        -- the normal Farm Level quest untouched.
                        if xyraxFindLiveEnemyByNames(boss.EnemyNames) then
                            xyraxProgressionQuestAction("StartQuest", boss.QuestName, boss.QuestLevel)
                        end
                    end
                    return
                end

                -- A complete runtime model in ReplicatedStorage is a travel
                -- hint only.  Keep the Sky Warlord route alive until that map
                -- streams in, but never attack a replicated/template model.
                if enemySource == "ReplicatedStorage" and enemy then
                    local distantRoot = enemy:FindFirstChild("HumanoidRootPart")
                    if distantRoot and distantRoot:IsA("BasePart") then
                        xyraxSetProgressionBossStatus("Approaching " .. boss.Label .. " (streamed)")
                        xyraxProgressionBossMove(
                            distantRoot.CFrame * CFrame.new(0, 30, 0),
                            "progression-distant-boss:" .. boss.Label
                        )
                    end
                    return
                end

                if enemySource == "StreamHold" then
                    xyraxSetProgressionBossStatus("Waiting for " .. boss.Label .. " map stream")
                    return
                end

                enemy = xyraxFindLiveEnemyByNames(boss.EnemyNames)
                if not enemy then
                    return
                end
                xyraxSetProgressionBossStatus("Farming " .. boss.Label)
                local humanoid = enemy:FindFirstChild("Humanoid")
                local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                if not (humanoid and enemyRoot and humanoid.Health > 0) then
                    return
                end

                repeat
                    task.wait(0.08)
                    if not _G.AutoProgressionBoss or not enemy.Parent or humanoid.Health <= 0 then
                        break
                    end
                    AutoHaki()
                    EquipWeapon(_G.SelectWeapon)
                    local damageState = XyraxAutomation.WatchDamage(enemy, "Progression Boss: " .. boss.Label, 8, 1)
                    if damageState == "retry" then
                        XyraxAutomation.ResetDamageCombat()
                    elseif damageState == "abandon" then
                        XyraxAutomation.BlockDamageBoss("Progression:" .. boss.Label, "Progression Boss: " .. boss.Label, XyraxAutomation.DamageBossBlockSeconds)
                        XyraxAutomation.ResetDamageCombat()
                        break
                    end
                    enemyRoot.CanCollide = false
                    humanoid.WalkSpeed = 0
                    enemyRoot.Size = Vector3.new(80, 80, 80)
                    if xyraxProgressionBossMove(enemyRoot.CFrame * CFrame.new(0, 30, 0), "progression-boss:" .. boss.Label) then
                        XyraxAutomation.TryDarkStepV("Progression Boss: " .. boss.Label, enemy)
                        game:GetService("VirtualUser"):CaptureController()
                        game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
                    end
                until not _G.AutoProgressionBoss or not enemy.Parent or humanoid.Health <= 0

                if boss.StreamingAware and humanoid.Health <= 0 then
                    XyraxAutomation.ProgressionBossDefeated = {Label = boss.Label, At = os.clock()}
                    XyraxAutomation.ProgressionStreamLock = nil
                    xyraxSetProgressionBossStatus("Defeated " .. boss.Label .. "; returning to Farm Level")
                end
            end)
        end
    end
end)

-- Sea 2 Progression Boss executor.  Same shape as the Sea 1 worker above but
-- without the ReplicatedStorage/StreamHold hint tier (no verified need for
-- it yet on these three targets) - reuses the same generic quest-state,
-- travel, and combat helpers since none of them are Sea 1-specific.
XyraxAutomation.LastProgressionBossSea2Status = nil
function XyraxAutomation.SetProgressionBossSea2Status(status)
    XyraxAutomation.ProgressionBossSea2Status = status
    if status ~= XyraxAutomation.LastProgressionBossSea2Status then
        XyraxAutomation.LastProgressionBossSea2Status = status
        print("[BfRef Progression Boss Sea2] " .. status)
    end
end

task.spawn(function()
    while task.wait(0.15) do
        if _G.AutoProgressionBossSea2 then
            pcall(function()
                local boss, enemy, bossSource = XyraxAutomation.GetSea2ProgressionBoss()
                if not boss then
                    XyraxAutomation.SharkmanTideKeeperHuntLogged = false
                    return
                end
                if boss.Label ~= "Tide Keeper" then
                    XyraxAutomation.SharkmanTideKeeperHuntLogged = false
                end

                -- Confirmed live (Scripts/ReplicatedStorage/Quests.lua):
                -- FrostQuest's 3rd stage (Task "Awakened Ice Admiral") has
                -- LevelReq = 1400 - that requirement gates accepting the
                -- QUEST server-side, not fighting the boss itself.  Below
                -- 1400 the boss is still eligible here purely for its Library
                -- Key / Hidden Key drop (XyraxAutomation.GetSea2ProgressionBoss
                -- already only returns it below 1400 while
                -- IceCastleNeedsKeyOrDrop() is true), so StartQuest would just
                -- be rejected by the server every pass and loop forever on
                -- "Getting Awakened Ice Admiral quest".  Skip the quest
                -- accept/track step entirely in that case and go straight to
                -- combat - no other Sea2 progression boss is affected.
                local belowQuestLevel = false
                if boss.Label == "Awakened Ice Admiral" then
                    local player = game:GetService("Players").LocalPlayer
                    local levelValue = player:FindFirstChild("Data") and player.Data:FindFirstChild("Level")
                    local level = levelValue and levelValue.Value or 0
                    belowQuestLevel = level < 1400
                elseif boss.Label == "Tide Keeper" then
                    -- Same situation as Awakened Ice Admiral above:
                    -- ForgottenQuest's "Tide Keeper" stage has LevelReq =
                    -- 1475 (Quests.lua), but Sharkman Karate needs the Water
                    -- Key drop regardless of level. Skip quest accept below
                    -- that level and fight directly.
                    local player = game:GetService("Players").LocalPlayer
                    local levelValue = player:FindFirstChild("Data") and player.Data:FindFirstChild("Level")
                    local level = levelValue and levelValue.Value or 0
                    belowQuestLevel = level < 1475
                end

                if not belowQuestLevel then
                    local questVisible, questMatches = xyraxProgressionQuestState(boss)
                    if questVisible and not questMatches then
                        XyraxAutomation.SetProgressionBossSea2Status("Abandoning unrelated quest")
                        xyraxProgressionQuestAction("AbandonQuest")
                        return
                    end

                    if not questMatches then
                        local player = game:GetService("Players").LocalPlayer
                        local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                        local questCFrame = xyraxProgressionQuestGiverCFrame(boss)
                        if not (root and questCFrame) then
                            XyraxAutomation.SetProgressionBossSea2Status("Waiting for " .. boss.Label .. " quest giver to stream")
                            return
                        end
                        XyraxAutomation.SetProgressionBossSea2Status("Getting " .. boss.Label .. " quest")
                        if xyraxProgressionBossMove(questCFrame, "progression-sea2-quest:" .. boss.QuestName) then
                            -- Accepting the quest only needs the boss to still
                            -- be available somewhere (Workspace OR
                            -- ReplicatedStorage) - it does not need to be
                            -- live-in-Workspace yet.  The combat phase below
                            -- (the shared liveEnemy check) is what walks a
                            -- ReplicatedStorage-only boss into Workspace, so
                            -- accepting the quest here never depends on that
                            -- having happened first.
                            if xyraxFindEnemyByNames(boss.EnemyNames) then
                                xyraxProgressionQuestAction("StartQuest", boss.QuestName, boss.QuestLevel)
                            else
                                -- Boss was found when GetSea2ProgressionBoss()
                                -- picked it, but is gone from BOTH Workspace
                                -- and ReplicatedStorage by the time the walk to
                                -- the quest giver finished - genuinely
                                -- despawned, not just "not streamed in yet".
                                -- Never stand here waiting for a respawn -
                                -- block re-picking this boss for the same
                                -- cooldown the combat-abandon path below
                                -- already uses, so the next scheduler pass
                                -- finds no boss and falls through to Farm
                                -- Level/whatever else is next in priority.
                                XyraxAutomation.SetProgressionBossSea2Status(
                                    boss.Label .. " no longer available anywhere; yielding to scheduler")
                                XyraxAutomation.BlockDamageBoss("ProgressionSea2:" .. boss.Label,
                                    "Progression Boss Sea2: " .. boss.Label, XyraxAutomation.DamageBossBlockSeconds)
                            end
                        end
                        return
                    end
                end

                local liveEnemy = xyraxFindLiveEnemyByNames(boss.EnemyNames)
                if not liveEnemy then
                    -- GetSea2ProgressionBoss() picked this boss up from
                    -- ReplicatedStorage (a distant, not-yet-streamed-in
                    -- template with a real HumanoidRootPart/CFrame) - confirmed
                    -- live that xyraxFindLiveEnemyByNames (Workspace-only)
                    -- then always misses it, returning empty-handed forever.
                    -- Walk toward the distant template's own CFrame to force
                    -- that area to stream in, the same fallback Farm Level
                    -- already uses for a ReplicatedStorage-only Mon - never
                    -- enter combat on the distant instance itself.  Next pass
                    -- re-checks Workspace fresh.
                    if bossSource == "ReplicatedStorage" and enemy then
                        local distantRoot = enemy:FindFirstChild("HumanoidRootPart")
                        if distantRoot and distantRoot:IsA("BasePart") then
                            XyraxAutomation.SetProgressionBossSea2Status(
                                "Streaming in " .. boss.Label .. " (ReplicatedStorage -> Workspace)")
                            xyraxProgressionBossMove(distantRoot.CFrame * CFrame.new(0, 20, 0),
                                "progression-sea2-stream:" .. boss.Label)
                        end
                    end
                    return
                end
                enemy = liveEnemy
                XyraxAutomation.SetProgressionBossSea2Status("Farming " .. boss.Label)
                if boss.Label == "Tide Keeper" and not XyraxAutomation.SharkmanTideKeeperHuntLogged then
                    XyraxAutomation.SharkmanTideKeeperHuntLogged = true
                    print("[Sharkman] Hunting Tide Keeper")
                end
                local humanoid = enemy:FindFirstChild("Humanoid")
                local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                if not (humanoid and enemyRoot and humanoid.Health > 0) then
                    return
                end

                repeat
                    task.wait(0.08)
                    if not _G.AutoProgressionBossSea2 or not enemy.Parent or humanoid.Health <= 0 then
                        break
                    end
                    AutoHaki()
                    EquipWeapon(_G.SelectWeapon)
                    local damageState = XyraxAutomation.WatchDamage(enemy, "Progression Boss Sea2: " .. boss.Label, 8, 1)
                    if damageState == "retry" then
                        XyraxAutomation.ResetDamageCombat()
                    elseif damageState == "abandon" then
                        XyraxAutomation.BlockDamageBoss("ProgressionSea2:" .. boss.Label, "Progression Boss Sea2: " .. boss.Label, XyraxAutomation.DamageBossBlockSeconds)
                        XyraxAutomation.ResetDamageCombat()
                        break
                    end
                    enemyRoot.CanCollide = false
                    humanoid.WalkSpeed = 0
                    enemyRoot.Size = Vector3.new(80, 80, 80)
                    if xyraxProgressionBossMove(enemyRoot.CFrame * CFrame.new(0, 30, 0), "progression-sea2-boss:" .. boss.Label) then
                        XyraxAutomation.TryDarkStepV("Progression Boss Sea2: " .. boss.Label, enemy)
                        game:GetService("VirtualUser"):CaptureController()
                        game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
                    end
                until not _G.AutoProgressionBossSea2 or not enemy.Parent or humanoid.Health <= 0

                if boss.Label == "Tide Keeper" and humanoid.Health <= 0 then
                    XyraxAutomation.SharkmanTideKeeperHuntLogged = false
                    if xyraxOwnsTool("water key") then
                        print("[Sharkman] Water Key acquired")
                    else
                        print("[Sharkman] Tide Keeper defeated; Water Key not found")
                    end
                end
            end)
        end
    end
end)

