            pcall(function()
                local npcs = workspace:FindFirstChild("NPCs")
                local elAdmin = (npcs and npcs:FindFirstChild("El Admin")) or workspace:FindFirstChild("El Admin", true)
                local npcRoot = elAdmin and (elAdmin.PrimaryPart
                    or elAdmin:FindFirstChild("HumanoidRootPart")
                    or elAdmin:FindFirstChild("Head"))
                if not (npcRoot and npcRoot:IsA("BasePart")) then
