                    -- there.  Reuse the same OutShip -> requestEntrance(InShip)
                    -- entrance CheckQuest already uses for Farm Level
                    -- (BfRef.lua:795-855) instead of waiting forever.  World1's
                    -- own El Admin has no verified static position, so this
                    -- only applies to World2.
                    if World2 then
                        local player = game:GetService("Players").LocalPlayer
                        local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                        if root and not XyraxAutomation.IsInCursedShip() then
                            XyraxAutomation.SetMidnightBladeStatus("Ectoplasm ready; travelling to Cursed Ship")
                            local outShip = XyraxAutomation.CursedShipOutShip
                            if (root.Position - outShip).Magnitude > 10 then
                                topos(CFrame.new(outShip))
                            else
                                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                                local commF = remotes and remotes:FindFirstChild("CommF_")
                                if commF then
                                    commF:InvokeServer("requestEntrance", XyraxAutomation.CursedShipInShip)
                                end
                            end
                            return
                        end
                    end
                    XyraxAutomation.SetMidnightBladeStatus("waiting for El Admin to stream in")
                    return
                end

                local player = game:GetService("Players").LocalPlayer
                local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                if not root then
                    return
                end
                local destination = npcRoot.CFrame
                if (root.Position - destination.Position).Magnitude > 8 then
                    XyraxAutomation.SetMidnightBladeStatus("Ectoplasm ready; travelling to El Admin")
                    local tweenPlaying = _G.TweenCache and _G.TweenCache.PlaybackState == Enum.PlaybackState.Playing
                    if XyraxAutomation.MidnightBladeMoveKey ~= "midnight-blade" or not tweenPlaying
                        or os.clock() - XyraxAutomation.MidnightBladeMoveAt >= 0.8 then
                        XyraxAutomation.MidnightBladeMoveKey = "midnight-blade"
                        XyraxAutomation.MidnightBladeMoveAt = os.clock()
                        TP1(destination)
                    end
                    return
                end

                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                local commF = remotes and remotes:FindFirstChild("CommF_")
                if not commF then
                    return
                end
                local result = commF:InvokeServer("Ectoplasm", "Buy", 3)
                if result == 1 then
                    XyraxAutomation.MidnightBladeOwned = true
                    XyraxAutomation.SetMidnightBladeStatus("purchased Midnight Blade")
                elseif result == 2 then
                    XyraxAutomation.MidnightBladeOwned = true
                    XyraxAutomation.SetMidnightBladeStatus("already own Midnight Blade")
                else
                    XyraxAutomation.SetMidnightBladeStatus("trade rejected (result=" .. tostring(result) .. "); Farm Level resumes")
                end
            end)
        end
    end
end)

