function XyraxAutomation.RaceV3Move(destination, key, range)
    local player = game:GetService("Players").LocalPlayer
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not (root and destination) then
        return false
    end
    if (root.Position - destination.Position).Magnitude <= (range or 8) then
        return true
    end
    local tweenPlaying = _G.TweenCache and _G.TweenCache.PlaybackState == Enum.PlaybackState.Playing
    if XyraxAutomation.RaceV3MoveKey ~= key or not tweenPlaying
        or os.clock() - XyraxAutomation.RaceV3MoveAt >= 0.8 then
        XyraxAutomation.RaceV3MoveKey = key
        XyraxAutomation.RaceV3MoveAt = os.clock()
        topos(destination)
    end
    return false
end

task.spawn(function()
    while task.wait(0.2) do
        if _G.AutoRaceV3 then
            pcall(function()
                local action = XyraxAutomation.GetRaceV3Action()
                -- Auto Store Fruits runs as its own always-on 0.25s loop
                -- that grabs any Tool sitting in Character/Backpack and
                -- stores it, with no idea this job is deliberately holding
                -- one for Trevor.  Flag it reserved for exactly as long as
                -- this is the active action so that loop skips it.
                XyraxAutomation.HeldFruitReserved = action ~= nil and action.Kind == "UnlockDonSwan"
                if not action then
                    return
                end

                if action.Kind == "Accept" or action.Kind == "Pay" then
                    local arowe = XyraxAutomation.FindArowe()
                    local aroweRoot = arowe and (arowe.PrimaryPart
                        or arowe:FindFirstChild("HumanoidRootPart")
                        or arowe:FindFirstChild("Head"))
                    if not (aroweRoot and aroweRoot:IsA("BasePart")) then
                        -- Not streamed in yet.  arowe's secret room is
                        -- reached by walking into the hillside near
                        -- Diamond's spawn - travel there to force that area
                        -- to stream, then re-search on the next pass.
                        local diamondSpawn = XyraxAutomation.RaceV2FindSpawnPoint("Diamond")
                        if diamondSpawn then
                            XyraxAutomation.SetRaceV3Status("arowe not streamed; approaching Diamond's hill")
                            XyraxAutomation.RaceV3Move(diamondSpawn.CFrame, "racev3-diamond-hill", 15)
                        else
                            XyraxAutomation.SetRaceV3Status("waiting for Arowe to stream in")
                        end
                        return
                    end
                    if not XyraxAutomation.RaceV3Move(aroweRoot.CFrame, "racev3-arowe", 9) then
                        XyraxAutomation.SetRaceV3Status("travelling to Arowe")
                        return
                    end
                    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                    local commF = remotes and remotes:FindFirstChild("CommF_")
                    if not commF then
                        return
                    end
                    if action.Kind == "Accept" then
                        local result = commF:InvokeServer("Wenlocktoad", "2")
                        XyraxAutomation.SetRaceV3Status("accepted race quest: " .. tostring(result))
                    else
                        local result = commF:InvokeServer("Wenlocktoad", "3")
                        XyraxAutomation.SetRaceV3Status("paid for Race V3: " .. tostring(result))
                    end
                    XyraxAutomation.GetRaceV3State(true)
                    return
                end

                if action.Kind == "UnlockDonSwan" then
                    local player = game:GetService("Players").LocalPlayer
                    local character = player.Character
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                    local heldTool = character and character:FindFirstChildOfClass("Tool")
                    local heldToolOriginalName = heldTool and heldTool:GetAttribute("OriginalName")
                    local fruitTool = (type(heldToolOriginalName) == "string" and heldToolOriginalName ~= "" and heldTool)
                        or XyraxAutomation.FindBestPhysicalFruitForTrevor()
                    if not fruitTool then
                        -- Nothing loose in the Backpack yet - pull one out
                        -- of the fruit storage box if a qualifying one is
                        -- in there, then look it up by name right away
                        -- (InvokeServer already waits for the server's
                        -- reply, so the Tool should exist by now) instead
                        -- of waiting for a later tick's price-based scan,
                        -- which can never match if LoadFruit's InvokeServer
                        -- hasn't returned or the Tool name differs.
                        local storedKey = XyraxAutomation.FindBestStoredPhysicalFruitForTrevor()
                        if not storedKey then
                            XyraxAutomation.SetRaceV3Status("waiting for a Fruit worth $1M+ to give Trevor")
                            return
                        end
                        XyraxAutomation.UnstoreFruit(storedKey)
                        local backpackAfterUnstore = player:FindFirstChild("Backpack")
                        -- Match by the "OriginalName" attribute, not
                        -- Tool.Name (confirmed different - e.g. "Spider
                        -- Fruit" the display name for key "Spider-Spider").
                        if backpackAfterUnstore then
                            for _, tool in ipairs(backpackAfterUnstore:GetChildren()) do
                                if tool:IsA("Tool") and tool:GetAttribute("OriginalName") == storedKey then
                                    fruitTool = tool
                                    break
                                end
                            end
                        end
                        if not fruitTool then
                            XyraxAutomation.SetRaceV3Status("requested " .. storedKey .. " from storage; waiting for it to arrive")
                            return
                        end
                        XyraxAutomation.SetRaceV3Status("took " .. storedKey .. " out of storage")
                    end
                    if fruitTool.Parent ~= character and humanoid then
                        humanoid:EquipTool(fruitTool)
                        task.wait(0.2)
                    end
                    local trevor = XyraxAutomation.FindTrevor()
                    local trevorRoot = trevor and (trevor.PrimaryPart or trevor:FindFirstChild("HumanoidRootPart"))
                    if not (trevorRoot and trevorRoot:IsA("BasePart")) then
                        if XyraxAutomation.RaceV3Move(XyraxAutomation.TrevorMansionCFrame, "racev3-trevor-mansion", 18) then
                            XyraxAutomation.SetRaceV3Status("at Trevor's Mansion; waiting for Trevor to stream in")
                        else
                            XyraxAutomation.SetRaceV3Status("travelling to Trevor's Mansion to stream Trevor")
                        end
                        return
                    end
                    if not XyraxAutomation.RaceV3Move(trevorRoot.CFrame, "racev3-trevor", 9) then
                        XyraxAutomation.SetRaceV3Status("travelling to Trevor with " .. fruitTool.Name)
                        return
                    end
                    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                    local commF = remotes and remotes:FindFirstChild("CommF_")
                    if not commF then
                        return
                    end
                    -- Client dialogue flow from Trevor.lua: "1" first.  A
                    -- truthy value other than 0/1/2 is the opening dialogue;
                    -- its "Alright" option calls "2", then the client calls
                    -- "1" again before offering the Give ("3") option.
                    local result = commF:InvokeServer("TalkTrevor", "1")
                    if result and result ~= 0 and result ~= 1 and result ~= 2 then
                        commF:InvokeServer("TalkTrevor", "2")
                        result = commF:InvokeServer("TalkTrevor", "1")
                    end
                    if result == 2 then
                        local giveResult = commF:InvokeServer("TalkTrevor", "3")
                        XyraxAutomation.DonSwanUnlocked = true
                        XyraxAutomation.SetRaceV3Status("gave Trevor " .. fruitTool.Name .. "; Don Swan room unlocked (" .. tostring(giveResult) .. ")")
                    elseif result == 0 then
                        -- Trevor already holds a fruit from before this
                        -- session started tracking it - treat as unlocked.
                        XyraxAutomation.DonSwanUnlocked = true
                        XyraxAutomation.SetRaceV3Status("Trevor already has a fruit; treating Don Swan room as unlocked")
                    else
                        XyraxAutomation.SetRaceV3Status("Trevor didn't accept " .. fruitTool.Name .. " (result: " .. tostring(result) .. ")")
                    end
                    return
                end

                if action.Kind == "HuntDonSwan" then
                    local enemy, source = xyraxFindEnemyByNames({"Don Swan"})
                    if not enemy then
                        XyraxAutomation.SetRaceV3Status("waiting for Don Swan to spawn (Colosseum)")
                        return
                    end
                    if source == "ReplicatedStorage" then
                        local distantRoot = enemy:FindFirstChild("HumanoidRootPart")
                        if distantRoot and distantRoot:IsA("BasePart") then
                            XyraxAutomation.SetRaceV3Status("approaching streamed Don Swan")
                            XyraxAutomation.RaceV3Move(distantRoot.CFrame * CFrame.new(0, 30, 0), "racev3-donswan", 12)
                        end
                        return
                    end
                    local humanoid = enemy:FindFirstChild("Humanoid")
                    local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                    if not (humanoid and enemyRoot and humanoid.Health > 0) then
                        return
                    end
                    XyraxAutomation.SetRaceV3Status("fighting Don Swan (prerequisite for Race V3)")
                    local damageState = XyraxAutomation.WatchDamage(enemy, "RaceV3:DonSwan", 8, 1)
                    if damageState == "retry" then
                        XyraxAutomation.ResetDamageCombat()
                    elseif damageState == "abandon" then
                        XyraxAutomation.BlockDamageBoss("RaceV3:DonSwan", "RaceV3:DonSwan", 60)
                        XyraxAutomation.ResetDamageCombat()
                    else
                        AutoHaki()
                        EquipWeapon(_G.SelectWeapon)
                        enemyRoot.CanCollide = false
                        humanoid.WalkSpeed = 0
                        enemyRoot.Size = Vector3.new(80, 80, 80)
                        -- 80-stud Size above means a 40-stud radius; +30
                        -- puts the character (and camera) inside that box,
                        -- where the fixed-screen-point click can miss
                        -- everything.  +50 clears it.
                        if XyraxAutomation.RaceV3Move(enemyRoot.CFrame * CFrame.new(0, 50, 0), "racev3-donswan-fight", 12) then
                            XyraxAutomation.TryDarkStepV("RaceV3:DonSwan", enemy)
                            game:GetService("VirtualUser"):CaptureController()
                            game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
                        end
                    end
                    if humanoid.Health <= 0 then
                        -- Refresh state immediately.  If it is still nil
                        -- right after this confirmed kill, some other
                        -- prerequisite is the real blocker (or the server
                        -- has not credited the kill yet) - back off on a
                        -- cooldown instead of re-killing him nonstop, and
                        -- retry automatically once it expires.  Never a
                        -- permanent flag: this attempt could have been too
                        -- early for the server to register.
                        local freshState = XyraxAutomation.GetRaceV3State(true)
                        if freshState == nil then
                            XyraxAutomation.RaceV3DonSwanCooldownUntil = os.clock() + 60
                            XyraxAutomation.SetRaceV3Status("Don Swan defeated but Race V3 still not ready; retrying in 60s")
                        else
                            XyraxAutomation.SetRaceV3Status("Don Swan defeated; re-checking Race V3 prerequisites")
                        end
                    end
                    return
                end

                if action.Kind == "HuntHuman" then
                    for _, name in ipairs(XyraxAutomation.RaceV3HumanTargets) do
                        local enemy, source = xyraxFindEnemyByNames({name})
                        if enemy and source == "Workspace" then
                            local humanoid = enemy:FindFirstChild("Humanoid")
                            local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                            if humanoid and enemyRoot and humanoid.Health > 0 then
                                XyraxAutomation.SetRaceV3Status("hunting " .. name .. " for Race V3")
                                local damageState = XyraxAutomation.WatchDamage(enemy, "RaceV3:" .. name, 8, 1)
                                if damageState == "retry" then
                                    XyraxAutomation.ResetDamageCombat()
                                elseif damageState == "abandon" then
                                    XyraxAutomation.BlockDamageBoss("RaceV3:" .. name, "RaceV3:" .. name, 60)
                                    XyraxAutomation.ResetDamageCombat()
                                else
                                    AutoHaki()
                                    EquipWeapon(_G.SelectWeapon)
                                    enemyRoot.CanCollide = false
                                    humanoid.WalkSpeed = 0
                                    enemyRoot.Size = Vector3.new(80, 80, 80)
                                    if XyraxAutomation.RaceV3Move(enemyRoot.CFrame * CFrame.new(0, 30, 0), "racev3-hunt-" .. name, 12) then
                                        XyraxAutomation.TryDarkStepV("RaceV3:" .. name, enemy)
                                        game:GetService("VirtualUser"):CaptureController()
                                        game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
                                    end
                                end
                                return
                            end
                        elseif enemy and source == "ReplicatedStorage" then
                            local distantRoot = enemy:FindFirstChild("HumanoidRootPart")
                            if distantRoot and distantRoot:IsA("BasePart") then
                                XyraxAutomation.SetRaceV3Status("approaching streamed " .. name)
                                XyraxAutomation.RaceV3Move(distantRoot.CFrame * CFrame.new(0, 30, 0), "racev3-distant-" .. name, 12)
                                return
                            end
                        end
                    end
                    XyraxAutomation.SetRaceV3Status("waiting for Diamond/Jeremy/Orbitus to spawn")
                    return
                end

                if action.Kind == "HuntSharkBeast" then
                    -- Confirmed live: workspace.SeaBeasts holds every
                    -- naturally-spawned sea creature (SyncLeviathan.lua
                    -- watches this exact folder).  Any live one in it
                    -- satisfies the Shark race quest.
                    local beasts = workspace:FindFirstChild("SeaBeasts")
                    local target = nil
                    if beasts then
                        for _, model in ipairs(beasts:GetChildren()) do
                            local humanoid = model:FindFirstChild("Humanoid")
                            if humanoid and humanoid.Health > 0 then
                                target = model
                                break
                            end
                        end
                    end
                    if not target then
                        XyraxAutomation.SetRaceV3Status("waiting for a Sea Beast to spawn")
                        return
                    end
                    local humanoid = target:FindFirstChild("Humanoid")
                    local enemyRoot = target:FindFirstChild("HumanoidRootPart") or target.PrimaryPart
                    if not (humanoid and enemyRoot) then
                        return
                    end
                    XyraxAutomation.SetRaceV3Status("hunting Sea Beast (" .. target.Name .. ") for Race V3")
                    local damageState = XyraxAutomation.WatchDamage(target, "RaceV3:SeaBeast", 8, 2)
                    if damageState == "retry" or damageState == "abandon" then
                        XyraxAutomation.ResetDamageCombat()
                    else
                        AutoHaki()
                        EquipWeapon(_G.SelectWeapon)
                        enemyRoot.CanCollide = false
                        humanoid.WalkSpeed = 0
                        enemyRoot.Size = Vector3.new(80, 80, 80)
                        if XyraxAutomation.RaceV3Move(enemyRoot.CFrame * CFrame.new(0, 30, 0), "racev3-seabeast", 20) then
                            game:GetService("VirtualUser"):CaptureController()
                            game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
                        end
                    end
                    return
                end

                if action.Kind == "EquipCyborgFruit" then
                    -- No separate "show fruit" remote was found in the
                    -- dump; the dialogue text only asks for a Physical
                    -- Fruit to be shown, so this just holds one and lets
                    -- the normal state poll (every 3s) notice the server
                    -- flip to state 2 once it registers the equipped fruit.
                    local player = game:GetService("Players").LocalPlayer
                    local character = player.Character
                    local heldTool = character and character:FindFirstChildOfClass("Tool")
                    if heldTool and heldTool.ToolTip == "Blox Fruit" then
                        XyraxAutomation.SetRaceV3Status("holding " .. heldTool.Name .. "; waiting for Arowe to register it")
                        return
                    end
                    local backpack = player:FindFirstChild("Backpack")
                    local fruitTool = nil
                    if backpack then
                        for _, tool in ipairs(backpack:GetChildren()) do
                            if tool:IsA("Tool") and tool.ToolTip == "Blox Fruit" then
                                fruitTool = tool
                                break
                            end
                        end
                    end
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                    if fruitTool and humanoid then
                        humanoid:EquipTool(fruitTool)
                        XyraxAutomation.SetRaceV3Status("equipped " .. fruitTool.Name .. " for Cyborg race quest")
                    else
                        XyraxAutomation.SetRaceV3Status("no Physical Fruit tool available to show Arowe")
                    end
                    return
                end

                if action.Kind == "HuntRabbitChests" then
                    local player = game:GetService("Players").LocalPlayer
                    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                    if not root then
                        return
                    end
                    local chest = XyraxAutomation.FindNearestChest(root.Position)
                    if not chest then
                        XyraxAutomation.SetRaceV3Status("waiting for a chest to be found")
                        return
                    end
                    if XyraxAutomation.RaceV3Move(chest.Part.CFrame, "racev3-chest", 6) then
                        -- Standing on the chest is enough - the game's own
                        -- always-running chest listener spawns the touch
                        -- box and registers the pickup on its own.
                        XyraxAutomation.SetRaceV3Status("opening " .. chest.Type)
                        task.wait(1)
                        for i, entry in ipairs(XyraxAutomation.RaceV3ChestCache or {}) do
                            if entry == chest then
                                table.remove(XyraxAutomation.RaceV3ChestCache, i)
                                break
                            end
                        end
                        XyraxAutomation.RaceV3ChestOpensSinceCheck = XyraxAutomation.RaceV3ChestOpensSinceCheck + 1
                        if XyraxAutomation.RaceV3ChestOpensSinceCheck >= 2 then
                            XyraxAutomation.RaceV3ChestOpensSinceCheck = 0
                            -- Force a fresh state read; the picker's next
                            -- pass switches to Pay on its own once this
                            -- comes back as state 2 instead of 1.
                            XyraxAutomation.GetRaceV3State(true)
                        end
                    else
                        XyraxAutomation.SetRaceV3Status("travelling to " .. chest.Type)
                    end
                end
            end)
        end
    end
end)

-- The scheduler is the only owner of movement.  Auto Superhuman reaches this
-- worker only for a verified purchase; mastery checking itself never owns a
-- movement job and leaves Farm/Saber/Boss free to run.
XyraxAutomation.SuperhumanMoveAt = 0
XyraxAutomation.SuperhumanMoveKey = nil
XyraxAutomation.SuperhumanBuyBusy = false
local function xyraxSuperhumanMove(destination, key)
    local player = game:GetService("Players").LocalPlayer
    local character = player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not (root and destination) then
        return false
    end
    if (root.Position - destination.Position).Magnitude <= 10 then
        return true
    end

    local currentTween = _G.TweenCache
    local tweenPlaying = currentTween and currentTween.PlaybackState == Enum.PlaybackState.Playing
    local now = os.clock()
    if key ~= XyraxAutomation.SuperhumanMoveKey or not tweenPlaying or now - XyraxAutomation.SuperhumanMoveAt >= 0.8 then
        XyraxAutomation.SuperhumanMoveKey = key
        XyraxAutomation.SuperhumanMoveAt = now
        TP1(destination)
    end
    return false
end

task.spawn(function()
    while task.wait(0.2) do
        local activeJob = XyraxAutomation.ActiveJob
        local action = XyraxAutomation.SuperhumanAction
        if xyraxIsSuperhumanJob(activeJob) and action then
            if action.Kind == "Buy" and not XyraxAutomation.SuperhumanBuyBusy then
                local stage = action.Stage
                if stage.Key == "Electric" and not xyraxLightningBoltDelivered() then
                    XyraxAutomation.SuperhumanAction = nil
                    XyraxAutomation.SuperhumanStatus = "Waiting for Missing Lightning Bolt delivery before Electric"
                    return
                end
                -- Resolve the live NPC model first.  For Mad Scientist in
                -- Sea 1, the fallback only reaches Lower Skylands dock to
                -- request streaming; it is never considered close enough to
                -- send a purchase remote.
                local teacher = XyraxAutomation.FindSuperhumanTeacher(stage.Teacher)
                local teacherRoot = teacher and (teacher.PrimaryPart
                    or teacher:FindFirstChild("HumanoidRootPart")
                    or teacher:FindFirstChild("Head"))
                local teacherDestination = teacherRoot and teacherRoot:IsA("BasePart")
                    and teacherRoot.CFrame
                    or (World2 and stage.NPC2)
                    or (World1 and stage.NPC or nil)
                if World2 and not teacher then
                    XyraxAutomation.SuperhumanStatus = "Travelling to " .. stage.Teacher .. " (Sea 2)"
                    if XyraxAutomation.SuperhumanLastDebug ~= XyraxAutomation.SuperhumanStatus then
                        XyraxAutomation.SuperhumanLastDebug = XyraxAutomation.SuperhumanStatus
                        print("[BfRef Superhuman] " .. XyraxAutomation.SuperhumanStatus)
                    end
                end
                local readyToBuy = teacherDestination
                    and xyraxSuperhumanMove(teacherDestination, "superhuman:" .. stage.Key)
                if World1 and stage.Key == "Electric" and not teacherRoot then
                    if readyToBuy then
                        XyraxAutomation.SuperhumanAction = nil
                        xyraxSuperhumanBuyRetryAt[stage.Key] = os.clock() + 20
                        XyraxAutomation.SuperhumanStatus = "Mad Scientist not streamed; Farm Level resumes for 20s"
                        print("[BfRef Superhuman] " .. XyraxAutomation.SuperhumanStatus)
                    end
                    return
                end
                if XyraxAutomation.SuperhumanStageAffordable(stage) and readyToBuy then
                    XyraxAutomation.SuperhumanBuyBusy = true
                    XyraxAutomation.SuperhumanStatus = "At " .. stage.Teacher .. "; buying " .. stage.Label
                    print("[BfRef Superhuman] At " .. stage.Teacher .. "; buying " .. stage.Label)
                    local purchaseResult = nil
                    local precheckResult = nil
                    local purchaseOk = pcall(function()
                        -- Check money/Fragments a second time at the NPC,
                        -- then use the same CommF purchase call as the
                        -- manual dialogue.
                        if XyraxAutomation.SuperhumanStageAffordable(stage) then
                            local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                            local commF = remotes and remotes:FindFirstChild("CommF_")
                            if commF then
                                -- The dialogue performs this non-mutating
                                -- check before showing its Learn/Pay button.
                                -- Keep it after the tween so Sea 2 never uses
                                -- a remote while still travelling.
                                if stage.Key == "DragonBreath" then
                                    -- Sabi: "1" checks/offers, "2" is the
                                    -- Learn/Trade button - both dialogue
                                    -- branches (already-know vs. not-yet)
                                    -- end up firing the same "2" call.
                                    precheckResult = commF:InvokeServer("BlackbeardReward", "DragonClaw", "1")
                                    purchaseResult = commF:InvokeServer("BlackbeardReward", "DragonClaw", "2")
                                else
                                    precheckResult = commF:InvokeServer(stage.Remote, true)
                                    purchaseResult = commF:InvokeServer(stage.Remote)
                                end
                            end
                        end
                        task.wait(1.5)
                    end)
                    print("[BfRef Superhuman] " .. stage.Label .. " precheck=" .. tostring(purchaseOk and precheckResult or "error") .. "; purchase=" .. tostring(purchaseOk and purchaseResult or "error"))
                    if purchaseOk and stage.Key == "Electric" and purchaseResult == 0 then
                        XyraxAutomation.SuperhumanStatus = "Electric needs Lightning Bolt at Mad Scientist"
                        print("[BfRef Superhuman] Electric is not ready: bring Lightning Bolt, then retry")
                    end
                    -- Success is the server's own result code, not a Tool in
                    -- the Backpack: only one fighting style is held at a
                    -- time, so the new style replaces the previous one.
                    if purchaseOk and purchaseResult == 1 then
                        XyraxAutomation.SuperhumanOwned[stage.Key] = true
                    end
                    if not purchaseOk or purchaseResult ~= 1 then
                        -- An insufficient-funds/server response must never
                        -- pin the character at the NPC.  Release the job long
                        -- enough for Farm Level to earn resources, then retry.
                        local retryDelay = 15
                        if purchaseOk and stage.Key == "Electric" and purchaseResult == 0 then
                            -- The current dialogue requires a Lightning Bolt;
                            -- do not spam BuyElectro while that prerequisite is
                            -- still missing.
                            retryDelay = 60
                        end
                        xyraxSuperhumanBuyRetryAt[stage.Key] = os.clock() + retryDelay
                    end
                    XyraxAutomation.SuperhumanBuyBusy = false
                end
            elseif action.Kind == "Equip" and not XyraxAutomation.SuperhumanBuyBusy then
                local stage = action.Stage
                local teacher = XyraxAutomation.FindSuperhumanTeacher(stage.Teacher)
                local teacherRoot = teacher and (teacher.PrimaryPart
                    or teacher:FindFirstChild("HumanoidRootPart")
                    or teacher:FindFirstChild("Head"))
                local teacherDestination = teacherRoot and teacherRoot:IsA("BasePart")
                    and teacherRoot.CFrame
                    or (World2 and stage.NPC2)
                    or (World1 and stage.NPC or nil)
                local readyToEquip = teacherDestination
                    and xyraxSuperhumanMove(teacherDestination, "superhuman-equip:" .. stage.Key)
                if readyToEquip then
                    XyraxAutomation.SuperhumanBuyBusy = true
                    XyraxAutomation.SuperhumanStatus = "At " .. stage.Teacher .. "; re-equipping " .. stage.Label
                    print("[BfRef Superhuman] At " .. stage.Teacher .. "; re-equipping " .. stage.Label .. " to verify mastery")
                    local result = nil
                    local ok = pcall(function()
                        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                        local commF = remotes and remotes:FindFirstChild("CommF_")
                        if commF then
                            -- Verified live: firing the same purchase remote on
                            -- an already-owned style charges nothing and simply
                            -- re-equips it, mastery preserved exactly as left.
                            -- Dragon Breath is the one stage whose remote takes
                            -- extra args (Sabi.lua: "BlackbeardReward",
                            -- "DragonClaw", "2" - the same call the dialogue's
                            -- Learn AND Trade buttons both use) - stage.Remote
                            -- alone ("BlackbeardReward" with no args) is not a
                            -- valid re-equip call for it and silently does
                            -- nothing, same special-case the Buy action above
                            -- already carries for this stage.
                            if stage.Key == "DragonBreath" then
                                result = commF:InvokeServer("BlackbeardReward", "DragonClaw", "2")
                            else
                                result = commF:InvokeServer(stage.Remote)
                            end
                        end
                        task.wait(1)
                    end)
                    print("[BfRef Superhuman] " .. stage.Label .. " re-equip result=" .. tostring(ok and result or "error"))
                    if not ok or not xyraxFindSuperhumanTool(stage) then
                        -- Never pin the character here forever; Farm Level
                        -- gets the movement slot back and this same Equip
                        -- action is retried after a short cooldown.
                        xyraxSuperhumanBuyRetryAt[stage.Key] = os.clock() + 15
                    end
                    XyraxAutomation.SuperhumanAction = nil
                    XyraxAutomation.SuperhumanBuyBusy = false
                end
            elseif action.Kind == "BuySuperhuman" and not XyraxAutomation.SuperhumanBuyBusy then
                -- Same no-confirmed-position situation as Sabi: rely on
                -- Martial Arts Master streaming in on its own.
                local teacher = XyraxAutomation.FindSuperhumanTeacher("Martial Arts Master")
                local teacherRoot = teacher and (teacher.PrimaryPart
                    or teacher:FindFirstChild("HumanoidRootPart")
                    or teacher:FindFirstChild("Head"))
                local teacherDestination = teacherRoot and teacherRoot:IsA("BasePart") and teacherRoot.CFrame or nil
                if not teacherDestination then
                    XyraxAutomation.SuperhumanStatus = "Waiting for Martial Arts Master to stream in"
                else
                    local readyToBuy = xyraxSuperhumanMove(teacherDestination, "superhuman:buy-superhuman")
                    if xyraxGetBeli() >= 3000000 and readyToBuy then
                        XyraxAutomation.SuperhumanBuyBusy = true
                        XyraxAutomation.SuperhumanStatus = "At Martial Arts Master; buying Superhuman"
                        print("[BfRef Superhuman] At Martial Arts Master; buying Superhuman")
                        local purchaseResult = nil
                        local precheckResult = nil
                        local purchaseOk = pcall(function()
                            if xyraxGetBeli() >= 3000000 then
                                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                                local commF = remotes and remotes:FindFirstChild("CommF_")
                                if commF then
                                    -- Confirmed live (dump): "true" precheck
                                    -- returns 3 when prerequisite styles
                                    -- aren't all mastered yet; no-args buys.
                                    precheckResult = commF:InvokeServer("BuySuperhuman", true)
                                    purchaseResult = commF:InvokeServer("BuySuperhuman")
                                end
                            end
                            task.wait(1.5)
                        end)
                        print("[BfRef Superhuman] Superhuman precheck=" .. tostring(purchaseOk and precheckResult or "error")
                            .. "; purchase=" .. tostring(purchaseOk and purchaseResult or "error"))
                        if purchaseOk and purchaseResult == 1 then
                            XyraxAutomation.SuperhumanBought = true
                        end
                        if not purchaseOk or purchaseResult ~= 1 then
                            xyraxSuperhumanBuyRetryAt.Superhuman = os.clock() + 15
                        end
                        XyraxAutomation.SuperhumanBuyBusy = false
                    end
                end
            end
        end
    end
end)

-- Auto Death Step executor.  Re-equipping Dark Step to read its mastery is
-- delegated to the Superhuman Equip worker above (job name "Auto Superhuman:
-- Equip Dark Step"); this worker only ever runs the final "Buy" step, once
-- XyraxAutomation.GetDeathStepJob has already confirmed Superhuman mastery
-- 300+, Dark Step mastery 400+, the Library open, and $2,500,000/5,000
-- Fragments on hand.  Teacher lookup reuses XyraxAutomation.FindSuperhumanTeacher
-- and travel reuses xyraxSuperhumanMove, same as every Superhuman stage.
task.spawn(function()
    while task.wait(0.2) do
        if XyraxAutomation.ActiveJob == "Auto Death Step" and not XyraxAutomation.DeathStepBuyBusy then
            pcall(function()
                local teacher = XyraxAutomation.FindSuperhumanTeacher("Phoeyu, the Reformed")
                local teacherRoot = teacher and (teacher.PrimaryPart
                    or teacher:FindFirstChild("HumanoidRootPart")
                    or teacher:FindFirstChild("Head"))
                if not (teacherRoot and teacherRoot:IsA("BasePart")) then
                    XyraxAutomation.DeathStepStatus = "Waiting for Phoeyu, the Reformed to stream in"
                    return
                end
                local readyToBuy = xyraxSuperhumanMove(teacherRoot.CFrame, "death-step:buy")
                if not (readyToBuy and xyraxGetBeli() >= 2500000 and xyraxGetFragments() >= 5000) then
                    return
                end
                XyraxAutomation.DeathStepBuyBusy = true
                XyraxAutomation.DeathStepStatus = "At Phoeyu, the Reformed; buying Death Step"
                print("[BfRef Death Step] At Phoeyu, the Reformed; buying Death Step")
                local precheckResult, purchaseResult
                local purchaseOk = pcall(function()
                    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                    local commF = remotes and remotes:FindFirstChild("CommF_")
                    if commF then
                        -- Confirmed live (DialoguesList.lua, "Phoeyu, the
                        -- Reformed"): "true" precheck returns 3 when not
                        -- strong enough yet; no-args actually buys.
                        precheckResult = commF:InvokeServer("BuyDeathStep", true)
                        purchaseResult = commF:InvokeServer("BuyDeathStep")
                    end
                    task.wait(1.5)
                end)
                print("[BfRef Death Step] precheck=" .. tostring(purchaseOk and precheckResult or "error")
                    .. "; purchase=" .. tostring(purchaseOk and purchaseResult or "error"))
                -- 1 = learned, 2 = already known: both mean the account now
                -- has Death Step.  0 = insufficient funds/Fragments, 3 = not
                -- strong enough - both just retry later.
                if purchaseOk and (purchaseResult == 1 or purchaseResult == 2) then
                    XyraxAutomation.DeathStepOwned = true
                    XyraxAutomation.DeathStepStatus = "Death Step complete"
                else
                    xyraxDeathStepBuyRetryAt = os.clock() + 15
                end
                XyraxAutomation.DeathStepBuyBusy = false
            end)
        end
    end
end)

-- Auto Water Key Turn-In executor.  Reuses xyraxProgressionBossMove (same
-- shared mover as the Sea2 Progression Boss / Sea2 Key / Third Sea workers
-- above) and XyraxAutomation.FindSuperhumanTeacher for the NPC lookup, same
-- as every other fighting-style teacher in this file.  No separate "hand
-- over the key" remote is confirmed to exist, so this fires the same
-- precheck the dialogue's own "Talk" option uses once at the NPC, then asks
-- CheckWaterKeyUnlocked(true) to confirm against the server whether that
-- actually consumed it - never assumes success just because the call did
-- not error.
XyraxAutomation.WaterKeyTurnInBusy = false
task.spawn(function()
    while task.wait(0.2) do
        if XyraxAutomation.ActiveJob == "Auto Water Key Turn-In" and not XyraxAutomation.WaterKeyTurnInBusy then
            pcall(function()
                local teacher = XyraxAutomation.FindSuperhumanTeacher("Sharkman Teacher")
                local teacherRoot = teacher and (teacher.PrimaryPart
                    or teacher:FindFirstChild("HumanoidRootPart")
                    or teacher:FindFirstChild("Head"))
                if not (teacherRoot and teacherRoot:IsA("BasePart")) then
                    XyraxAutomation.SetSharkmanStatus("Waiting for Sharkman Teacher to stream in")
                    return
                end
                if not xyraxProgressionBossMove(teacherRoot.CFrame, "sharkman:turn-in-key") then
                    return
                end

                XyraxAutomation.WaterKeyTurnInBusy = true
                XyraxAutomation.SetSharkmanStatus("Turning in Water Key")
                local precheckResult
                local ok = pcall(function()
                    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                    local commF = remotes and remotes:FindFirstChild("CommF_")
                    if commF then
                        precheckResult = commF:InvokeServer("BuySharkmanKarate", true)
                    end
                    task.wait(1)
                end)
                print("[Sharkman] Turn-in precheck=" .. tostring(ok and precheckResult or "error"))
                if not XyraxAutomation.CheckWaterKeyUnlocked(true) then
                    XyraxAutomation.SetSharkmanStatus("Water Key turn-in not yet confirmed by server; retrying")
                end
                XyraxAutomation.WaterKeyTurnInBusy = false
            end)
        end
    end
end)

-- Auto Sharkman Karate executor.  XyraxAutomation.GetSharkmanKarateJob sets
-- XyraxAutomation.SharkmanAction to either {Kind="Equip", Stage=<Water Kung
-- Fu stage>} (re-equip it to build/confirm mastery, exact same shape as the
-- Superhuman worker's own Equip branch) or {Kind="Buy"} (purchase at
-- Sharkman Teacher, $2,500,000 + 5,000 Fragments).  Reuses
-- xyraxProgressionBossMove and XyraxAutomation.FindSuperhumanTeacher, same
-- as every other job in this section.
XyraxAutomation.SharkmanBuyBusy = false
task.spawn(function()
    while task.wait(0.2) do
        if XyraxAutomation.ActiveJob == "Auto Sharkman Karate" and not XyraxAutomation.SharkmanBuyBusy then
            pcall(function()
                local action = XyraxAutomation.SharkmanAction
                if not action then
                    return
                end

                local teacherName = (action.Kind == "Equip") and action.Stage.Teacher or "Sharkman Teacher"
                local teacher = XyraxAutomation.FindSuperhumanTeacher(teacherName)
                local teacherRoot = teacher and (teacher.PrimaryPart
                    or teacher:FindFirstChild("HumanoidRootPart")
                    or teacher:FindFirstChild("Head"))
                local destination = (teacherRoot and teacherRoot:IsA("BasePart")) and teacherRoot.CFrame or nil
                if not destination and action.Kind == "Equip" then
                    destination = (World2 and action.Stage.NPC2) or (World1 and action.Stage.NPC) or nil
                end
                if not destination then
                    XyraxAutomation.SetSharkmanStatus("Waiting for " .. teacherName .. " to stream in")
                    return
                end
                if not xyraxProgressionBossMove(destination, "sharkman:" .. action.Kind) then
                    return
                end

                XyraxAutomation.SharkmanBuyBusy = true

                if action.Kind == "Equip" then
                    XyraxAutomation.SetSharkmanStatus("At " .. teacherName .. "; re-equipping " .. action.Stage.Label .. " to verify mastery")
                    local ok = pcall(function()
                        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                        local commF = remotes and remotes:FindFirstChild("CommF_")
                        if commF then
                            -- Verified live elsewhere in this file (Superhuman
                            -- worker): firing the purchase remote on an
                            -- already-owned style charges nothing and simply
                            -- re-equips it, mastery preserved exactly as left.
                            commF:InvokeServer(action.Stage.Remote)
                        end
                        task.wait(1)
                    end)
                    if not ok or not xyraxFindSuperhumanTool(action.Stage) then
                        xyraxSharkmanKarateBuyRetryAt = os.clock() + 15
                    end
                    XyraxAutomation.SharkmanAction = nil
                    XyraxAutomation.SharkmanBuyBusy = false
                    return
                end

                XyraxAutomation.SetSharkmanStatus("At Sharkman Teacher; purchasing")
                local precheckResult, purchaseResult
                local purchaseOk = pcall(function()
                    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                    local commF = remotes and remotes:FindFirstChild("CommF_")
                    if commF then
                        precheckResult = commF:InvokeServer("BuySharkmanKarate", true)
                        purchaseResult = commF:InvokeServer("BuySharkmanKarate")
                    end
                    task.wait(1.5)
                end)
                print("[Sharkman] precheck=" .. tostring(purchaseOk and precheckResult or "error")
                    .. "; purchase=" .. tostring(purchaseOk and purchaseResult or "error"))
                -- 1 = learned, 2 = already known: both mean the account now
                -- has Sharkman Karate.  0 = insufficient funds/Fragments,
                -- 3 = not strong enough - both just retry later.
                if purchaseOk and (purchaseResult == 1 or purchaseResult == 2) then
                    XyraxAutomation.SharkmanKarateOwned = true
                    if not XyraxAutomation.SharkmanCompleteLogged then
                        XyraxAutomation.SharkmanCompleteLogged = true
                        print("[Sharkman] Complete")
                    end
                else
                    xyraxSharkmanKarateBuyRetryAt = os.clock() + 15
                end
                XyraxAutomation.SharkmanAction = nil
                XyraxAutomation.SharkmanBuyBusy = false
            end)
        end
    end
end)

-- Auto Third Sea (Kaitun) executor.  Reuses xyraxProgressionBossMove (same
-- shared mover as the Sea2 Progression Boss / Sea2 Key jobs above) and the
-- exact same combat helpers (WatchDamage/TryDarkStepV/DamageBossBlocked) as
-- the Sea2 Progression Boss worker.  XyraxAutomation.GetThirdSeaJob decides
-- Kind (KillRipIndra vs TravelZou); this loop only travels and fires the
-- confirmed remotes (ZQuestProgress "Begin"/"Check", TravelZou).
XyraxAutomation.ThirdSeaBeginRetryAt = 0
task.spawn(function()
    while task.wait(0.15) do
        if XyraxAutomation.ActiveJob == "Auto Third Sea" then
            pcall(function()
                local action = XyraxAutomation.ThirdSeaAction
                if not action then
                    return
                end

                if action.Kind == "TravelZou" then
                    local teacher = XyraxAutomation.FindSuperhumanTeacher("Mr. Captain")
                    local teacherRoot = teacher and (teacher.PrimaryPart
                        or teacher:FindFirstChild("HumanoidRootPart")
                        or teacher:FindFirstChild("Head"))
                    if not (teacherRoot and teacherRoot:IsA("BasePart")) then
                        XyraxAutomation.SetThirdSeaStatus("Waiting for Mr. Captain to stream in")
                        return
                    end
                    if xyraxProgressionBossMove(teacherRoot.CFrame, "third-sea:travel-zou") then
                        local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                        local commF = remotes and remotes:FindFirstChild("CommF_")
                        if commF then
                            local result = commF:InvokeServer("TravelZou")
                            print("[BfRef ThirdSea] TravelZou result=" .. tostring(result))
                        end
                    end
                    return
                end

                if action.Kind == "KillRipIndra" then
                    local enemy = xyraxFindEnemyByNames({"rip_indra"})
                    if not enemy then
                        -- Not spawned/streamed yet - go to King Red Head and
                        -- start the encounter.  Confirmed remote/arg from
                        -- DialoguesList.lua "King Red Head": ZQuestProgress
                        -- "Begin" is what the accepted "Of course, admin"
                        -- dialogue option fires.
                        local teacher = XyraxAutomation.FindSuperhumanTeacher("King Red Head")
                        local teacherRoot = teacher and (teacher.PrimaryPart
                            or teacher:FindFirstChild("HumanoidRootPart")
                            or teacher:FindFirstChild("Head"))
                        if not (teacherRoot and teacherRoot:IsA("BasePart")) then
                            XyraxAutomation.SetThirdSeaStatus("Waiting for King Red Head to stream in")
                            return
                        end
                        if xyraxProgressionBossMove(teacherRoot.CFrame, "third-sea:king-red-head") then
                            local now = os.clock()
                            if now >= XyraxAutomation.ThirdSeaBeginRetryAt then
                                XyraxAutomation.ThirdSeaBeginRetryAt = now + 10
                                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                                local commF = remotes and remotes:FindFirstChild("CommF_")
                                if commF then
                                    local result = commF:InvokeServer("ZQuestProgress", "Begin")
                                    print("[BfRef ThirdSea] ZQuestProgress Begin result=" .. tostring(result))
                                end
                            end
                        end
                        return
                    end

                    local humanoid = enemy:FindFirstChild("Humanoid")
                    local enemyRoot = enemy:FindFirstChild("HumanoidRootPart")
                    if not (humanoid and enemyRoot and humanoid.Health > 0) then
                        return
                    end
                    if XyraxAutomation.DamageBossBlocked("ThirdSea:rip_indra") then
                        return
                    end
                    XyraxAutomation.SetThirdSeaStatus("Fighting rip_indra")
                    repeat
                        task.wait(0.08)
                        if XyraxAutomation.ActiveJob ~= "Auto Third Sea" or not enemy.Parent or humanoid.Health <= 0 then
                            break
                        end
                        AutoHaki()
                        EquipWeapon(_G.SelectWeapon)
                        local damageState = XyraxAutomation.WatchDamage(enemy, "Third Sea: rip_indra", 8, 1)
                        if damageState == "retry" then
                            XyraxAutomation.ResetDamageCombat()
                        elseif damageState == "abandon" then
                            XyraxAutomation.BlockDamageBoss("ThirdSea:rip_indra", "Third Sea: rip_indra", XyraxAutomation.DamageBossBlockSeconds)
                            XyraxAutomation.ResetDamageCombat()
                            break
                        end
                        enemyRoot.CanCollide = false
                        humanoid.WalkSpeed = 0
                        if xyraxProgressionBossMove(enemyRoot.CFrame * CFrame.new(0, 30, 0), "third-sea:rip-indra") then
                            XyraxAutomation.TryDarkStepV("Third Sea: rip_indra", enemy)
                            game:GetService("VirtualUser"):CaptureController()
                            game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
                        end
                    until XyraxAutomation.ActiveJob ~= "Auto Third Sea" or not enemy.Parent or humanoid.Health <= 0
                end
            end)
        end
    end
end)

-- Optional Sea 1 prerequisite route. It first starts Missing Lightning Bolt
-- at Mad Scientist, then only owns movement again for a confirmed cloud or
-- for returning a collected Bolt; a missing spawn never pins Farm Level.
task.spawn(function()
    while task.wait(0.12) do
        if xyraxIsLightningBoltJob(XyraxAutomation.ActiveJob) then
            pcall(function()
                local state = XyraxAutomation.LightningBolt
                local action = xyraxGetLightningBoltAction()
                if not action then
                    return
                end

                if action.Kind == "StartQuest" or action.Kind == "DeliverBolt" then
                    if not xyraxSuperhumanMove(action.Destination, "lightning:" .. action.Kind) then
                        return
                    end
                    if action.Kind == "StartQuest" then
                        -- Streaming may hide Workspace.NPCs even after the
                        -- verified Lower Skylands teleport point is loaded.
                        -- The manual dialogue itself uses these state calls,
                        -- so confirm the server quest state instead of
                        -- blocking forever on a client-only NPC model.
                        local questState = xyraxEnsureLightningQuest(true)
                        if questState == 1 then
                            xyraxLightningDebug("Mad Scientist quest confirmed; Farm Level waits for flashing cloud")
                        else
                            state.ScientistRetryAt = os.clock() + 20
                            xyraxLightningDebug("Mad Scientist quest was not accepted; retrying in 20s")
                        end
                        return
                    end

                    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                    local commF = remotes and remotes:FindFirstChild("CommF_")
                    local ok, result = pcall(function()
                        return commF and commF:InvokeServer("DeliverLightningBolt")
                    end)
                    if ok and result == 1 then
                        state.Delivered = true
                        state.HasAt = 0
                        state.QuestAt = 0
                        state.Target = nil
                        xyraxLightningDebug("Lightning Bolt delivered; Electric purchase can continue")
                    else
                        state.ScientistRetryAt = os.clock() + 20
                        xyraxLightningDebug("Lightning Bolt delivery failed; retrying in 20s")
                    end
                    return
                end

                local cloud = action.Target
                local cloudRoot = action.Root
                if not (cloud and cloudRoot and cloudRoot.Parent) then
                    xyraxLightningDebug("Charged cloud not streamed; Farm Level continues")
                    return
                end
                local player = game:GetService("Players").LocalPlayer
                local character = player.Character
                local root = character and character:FindFirstChild("HumanoidRootPart")
                if not root then return end
                local destination = cloudRoot.CFrame * CFrame.new(0, 8, 0)
                local tween = _G.TweenCache
                local playing = tween and tween.PlaybackState == Enum.PlaybackState.Playing
                local now = os.clock()
                if (root.Position - destination.Position).Magnitude > 12 then
                    local state = XyraxAutomation.LightningBolt
                    if state.MoveKey ~= "cloud" or not playing or now - (state.MoveAt or 0) >= 0.8 then
                        state.MoveKey = "cloud"
                        state.MoveAt = now
                        TP1(destination)
                        xyraxLightningDebug("Travelling to charged cloud")
                    end
                    return
                end

                -- This cloud is a map part, not an enemy.  Keep the character
                -- at it and only watch inventory: its hit method is verified
                -- separately from a real player left-click before automation
                -- is ever enabled here.
                local humanoid = cloud:IsA("Model") and cloud:FindFirstChildOfClass("Humanoid")
                if humanoid then
                    cloudRoot.CanCollide = false
                    humanoid.WalkSpeed = 0
                    local fastAttack = (_ENV and _ENV.rz_FastAttack) or _G.rz_FastAttack
                    if fastAttack and type(fastAttack.BladeHits) == "function" then
                        fastAttack:BladeHits()
                    elseif character:FindFirstChildOfClass("Tool") then
                        character:FindFirstChildOfClass("Tool"):Activate()
                    end
                    xyraxLightningDebug("Attacking charged cloud")
                else
                    local state = XyraxAutomation.LightningBolt
                    -- The quest cloud is a map part, so FastAttack and a raw
                    -- RegisterHit payload are both invalid here.  Aim the
                    -- local camera at the cloud and send an ordinary left
                    -- mouse click instead; CombatController then constructs
                    -- its own current RegisterAttack/RegisterHit data.
                    if now >= (state.BoltCheckAt or 0) then
                        state.BoltCheckAt = now + 0.75
                        state.HasAt = 0
                        if xyraxHasLightningBolt() then
                            state.Target = nil
                            state.TargetUntil = 0
                            xyraxLightningDebug("Lightning Bolt detected; holding it until Black Step Mastery 300")
                            return
                        end
                    end

                    local meleeTool = xyraxFindCloudMeleeTool()
                    if not meleeTool then
                        xyraxLightningDebug("Charged cloud ready; waiting for any Melee tool in Character or Backpack")
                        return
                    end
                    if meleeTool.Parent ~= character then
                        local humanoid = character:FindFirstChildOfClass("Humanoid")
                        if humanoid then
                            humanoid:EquipTool(meleeTool)
                            xyraxLightningDebug("Charged cloud ready; equipping " .. meleeTool.Name .. " before M1")
                        else
                            xyraxLightningDebug("Charged cloud ready; could not equip " .. meleeTool.Name)
                        end
                        return
                    end

                    if now < (state.CloudClickAt or 0) then
                        return
                    end
                    state.CloudClickAt = now + 0.60
                    state.CloudHitCount = (state.CloudHitCount or 0) + 1

                    local camera = workspace.CurrentCamera
                    if camera then
                        local cameraPosition = camera.CFrame.Position
                        if (cameraPosition - cloudRoot.Position).Magnitude > 0.1 then
                            camera.CFrame = CFrame.lookAt(cameraPosition, cloudRoot.Position)
                        end
                        local viewport = camera.ViewportSize
                        local x, y = viewport.X * 0.5, viewport.Y * 0.5
                        local input = game:GetService("VirtualInputManager")
                        input:SendMouseButtonEvent(x, y, 0, true, game, 0)
                        task.delay(0.06, function()
                            pcall(function()
                                input:SendMouseButtonEvent(x, y, 0, false, game, 0)
                            end)
                        end)
                    end
                    if now - (state.CloudAttackDebugAt or 0) >= 2 then
                        state.CloudAttackDebugAt = now
                        xyraxLightningDebug("At charged cloud; sending normal left-click x" .. tostring(state.CloudHitCount))
                    end
                end
            end)
        end
    end
end)

