    -- Uses the game's replicated ownership tags.  The old auto-buy loop
    -- invoked every purchase remote every 0.1 seconds even after success;
    -- this worker purchases only a missing ability and verifies its tag.
    Settings:Seperator("Abilities")
    Settings:Toggle("Auto Buy Abilities", true, function(value)
        XyraxAutomation.Desired.AutoBuyAbilities = value
    end)
    Settings:Toggle("Auto Instinct", true, function(value)
        XyraxAutomation.Desired.AutoInstinct = value
    end)

    XyraxAutomation.AbilityPurchases = {
        {Tag = "Geppo", Label = "Air Jump"},
        {Tag = "Buso", Label = "Aura"},
        {Tag = "Soru", Label = "Flash Step"},
    }
    XyraxAutomation.AbilityBuyRetryAt = XyraxAutomation.AbilityBuyRetryAt or {}
    XyraxAutomation.AbilityLastStatus = XyraxAutomation.AbilityLastStatus or nil
    XyraxAutomation.HasAbility = function(tag)
        local character = game:GetService("Players").LocalPlayer.Character
        return character ~= nil and game:GetService("CollectionService"):HasTag(character, tag)
    end
    XyraxAutomation.ReportAbilityStatus = function(status)
        if XyraxAutomation.AbilityLastStatus ~= status then
            XyraxAutomation.AbilityLastStatus = status
            print("[BfRef Abilities] " .. status)
        end
    end

    if XyraxEnvironment.XyraxAbilitiesControl then
        XyraxEnvironment.XyraxAbilitiesControl.Stop = true
    end
    XyraxAutomation.AbilitiesControl = {Stop = false}
    XyraxEnvironment.XyraxAbilitiesControl = XyraxAutomation.AbilitiesControl
    task.spawn(function()
            while not XyraxAutomation.AbilitiesControl.Stop do
                task.wait(2)
                pcall(function()
                    local player = game:GetService("Players").LocalPlayer
                    local character = player.Character
                    local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                    local commF = remotes and remotes:FindFirstChild("CommF_")
                    if not character then
                        XyraxAutomation.ReportAbilityStatus("waiting for character")
                        return
                    end

                    if XyraxAutomation.Desired.AutoBuyAbilities and commF then
                        for _, ability in ipairs(XyraxAutomation.AbilityPurchases) do
                            if not XyraxAutomation.HasAbility(ability.Tag)
                                and os.clock() >= (XyraxAutomation.AbilityBuyRetryAt[ability.Tag] or 0) then
                                local ok, result = pcall(function()
                                    return commF:InvokeServer("BuyHaki", ability.Tag)
                                end)
                                if ok and result == 1 then
                                    XyraxAutomation.ReportAbilityStatus(ability.Label .. " purchased; verifying ownership")
                                    task.wait(1)
                                elseif ok and result == 2 then
                                    -- The server already knows the ability; wait for
                                    -- its ownership tag to replicate before retrying.
                                    XyraxAutomation.ReportAbilityStatus(ability.Label .. " already owned; waiting for tag")
                                    XyraxAutomation.AbilityBuyRetryAt[ability.Tag] = os.clock() + 10
                                else
                                    -- Usually insufficient Beli.  Back off instead
                                    -- of repeatedly spending remote calls while farming.
                                    XyraxAutomation.AbilityBuyRetryAt[ability.Tag] = os.clock() + 30
                                    XyraxAutomation.ReportAbilityStatus(ability.Label .. " not purchased (result=" .. tostring(result) .. "); retrying later")
                                end
                                return
                            end
                        end

                        -- Instinct uses its own Teacher remote and costs
                        -- $750,000, so buy it only after the three basic
                        -- abilities are confirmed and only when Ken is absent.
                        if not XyraxAutomation.HasAbility("Ken")
                            and os.clock() >= (XyraxAutomation.AbilityBuyRetryAt.Ken or 0) then
                            local ok, result = pcall(function()
                                return commF:InvokeServer("KenTalk", "Buy")
                            end)
                            if ok and result == 0 then
                                XyraxAutomation.ReportAbilityStatus("Instinct purchased; verifying ownership")
                                task.wait(1)
                            else
                                XyraxAutomation.AbilityBuyRetryAt.Ken = os.clock() + 30
                                XyraxAutomation.ReportAbilityStatus("Instinct not purchased (result=" .. tostring(result) .. "); retrying later")
                            end
                            return
                        end
                    end

                    if XyraxAutomation.Desired.AutoInstinct then
                        if not XyraxAutomation.HasAbility("Ken") then
                            XyraxAutomation.ReportAbilityStatus("Instinct not owned; Auto Instinct is waiting")
                        elseif character:FindFirstChild("KenDisabled") then
                            XyraxAutomation.ReportAbilityStatus("Instinct temporarily disabled by game")
                        else
                            -- The live Observation client first changes its
                            -- own ObservationManager state on E, then sends
                            -- CommE("Ken", active).  Calling CommE alone does
                            -- not update that client state or its UI.
                            local events = game:GetService("ReplicatedStorage"):FindFirstChild("Events")
                            local activeQuery = events and events:FindFirstChild("IsObservationActive")
                            local stateOk, isActive = pcall(function()
                                return activeQuery and activeQuery:Invoke()
                            end)
                            if not stateOk or isActive == nil then
                                XyraxAutomation.ReportAbilityStatus("Instinct UI not ready; waiting")
                            elseif isActive then
                                XyraxAutomation.ReportAbilityStatus("Instinct already enabled")
                            else
                                local input = game:GetService("VirtualInputManager")
                                input:SendKeyEvent(true, Enum.KeyCode.E, false, game)
                                task.wait(0.05)
                                input:SendKeyEvent(false, Enum.KeyCode.E, false, game)
                                XyraxAutomation.ReportAbilityStatus("Instinct activation requested (E)")
                            end
                        end
                    end
                end)
            end
        end)

