      if World2 then
      Items:Toggle("Auto Legendary Sword", true, function(value)
          XyraxAutomation.Desired.LegendarySword = value
      end)

      -- Sea 2 only.  The dealer is answered by CommF_ from anywhere, so this
      -- is a plain background poll: no tween, no scheduler priority, and it
      -- never takes movement away from Farm Level.
      --   "1" -> sword name on offer, falsy when the dealer is not spawned
      --   "2" -> 1 purchased | 0 not enough money | 2 already owned | else gone
      -- getTradeInventory only lists fruits, so ownership is read from the
      -- Backpack exactly like the Sea 1 weapon jobs do.
      XyraxAutomation.LegendarySwordNames = {"Shizu", "Saishi", "Oroshi"}
      XyraxAutomation.LegendarySwordStatus = "Idle"

      local function xyraxLegendarySwordReport(step)
          if XyraxAutomation.LegendarySwordStatus ~= step then
              XyraxAutomation.LegendarySwordStatus = step
              print("[BfRef LegendarySword] " .. step)
          end
      end

      local function xyraxLegendarySwordMissing()
          local missing = {}
          for _, name in ipairs(XyraxAutomation.LegendarySwordNames) do
              if not xyraxOwnsTool(string.lower(name)) then
                  table.insert(missing, name)
              end
          end
          return missing
      end

      task.spawn(function()
          while task.wait(5) do
              if XyraxAutomation.LegendarySwordComplete then
                  break
              end
              if XyraxAutomation.Desired.LegendarySword then
                  pcall(function()
                      local player = game:GetService("Players").LocalPlayer
                      local missing = xyraxLegendarySwordMissing()
                      if #missing == 0 then
                          XyraxAutomation.LegendarySwordComplete = true
                          xyraxLegendarySwordReport("Complete: Shizu + Saishi + Oroshi owned")
                          return
                      end

                      local beliValue = player:FindFirstChild("Data")
                          and player.Data:FindFirstChild("Beli")
                      local beli = beliValue and beliValue.Value or 0
                      if beli < 2000000 then
                          xyraxLegendarySwordReport("waiting for money (" .. math.floor(beli)
                              .. " / 2000000); missing " .. table.concat(missing, ", "))
                          return
                      end

                      local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                      local commF = remotes and remotes:FindFirstChild("CommF_")
                      if not commF then
                          return
                      end

                      local offered = commF:InvokeServer("LegendarySwordDealer", "1")
                      if type(offered) ~= "string" or offered == "" then
                          xyraxLegendarySwordReport("dealer not available; retrying in 5s")
                          return
                      end
                      if xyraxOwnsTool(string.lower(offered)) then
                          xyraxLegendarySwordReport("dealer selling " .. offered
                              .. " (already owned); waiting for the next rotation")
                          return
                      end

                      xyraxLegendarySwordReport("dealer selling " .. offered .. "; purchasing")
                      local result = commF:InvokeServer("LegendarySwordDealer", "2")
                      if result == 1 then
                          task.wait(1)
                          local after = beliValue and beliValue.Value or beli
                          xyraxLegendarySwordReport("purchased " .. offered .. " (-"
                              .. math.floor(beli - after) .. " Beli); "
                              .. (3 - #xyraxLegendarySwordMissing()) .. "/3 owned")
                      elseif result == 0 then
                          xyraxLegendarySwordReport("purchase rejected: not enough money")
                      elseif result == 2 then
                          xyraxLegendarySwordReport("purchase rejected: " .. offered
                              .. " already owned; waiting for the next rotation")
                      else
                          xyraxLegendarySwordReport("dealer gone before purchase; retrying in 5s")
                      end
                  end)
              end
          end
      end)
      end

      if World1 then
      Items:Toggle("Auto Second Sea", true,function(Second)
      XyraxAutomation.Desired.SecondSea = Second
     end)
     
      -- State-driven Sea 2 quest.  The former loop inferred progress from
      -- Ice.Door alone and jumped straight to TravelDressrosa after combat;
      -- the current client requires a post-boss Detective dialogue first.
      local xyraxSecondSeaDetective = CFrame.new(4851.8720703125, 5.6514348983765, 718.47094726563)
      local xyraxSecondSeaIceDoor = CFrame.new(1347.7124, 37.3751602, -1325.6488)
      local xyraxSecondSeaMiddleTown = CFrame.new(-690.33081054688, 15.09425163269, 1582.2380371094)
      local xyraxSecondSeaMoveTag = nil
      local xyraxSecondSeaMoveAt = 0
      local xyraxSecondSeaLastStep = nil
      local xyraxSecondSeaDetectiveConfirmed = false

      local function xyraxSecondSeaReport(step)
          XyraxAutomation.SecondSeaStatus = step
          if xyraxSecondSeaLastStep ~= step then
              xyraxSecondSeaLastStep = step
              print("[BfRef Second Sea] " .. step)
          end
      end

      local function xyraxSecondSeaMove(destination, tag, range)
          local character = game.Players.LocalPlayer.Character
          local root = character and character:FindFirstChild("HumanoidRootPart")
          if not root then
              return false
          end
          if (root.Position - destination.Position).Magnitude <= (range or 8) then
              return true
          end
          local tweenPlaying = _G.TweenCache and _G.TweenCache.PlaybackState == Enum.PlaybackState.Playing
          if xyraxSecondSeaMoveTag ~= tag or not tweenPlaying or os.clock() - xyraxSecondSeaMoveAt >= 0.8 then
              xyraxSecondSeaMoveTag = tag
              xyraxSecondSeaMoveAt = os.clock()
              topos(destination)
          end
          return false
      end

      local function xyraxSecondSeaFindNpcRoot(name)
          local npcs = workspace:FindFirstChild("NPCs")
          local npc = (npcs and npcs:FindFirstChild(name)) or workspace:FindFirstChild(name)
          return npc and (npc.PrimaryPart or npc:FindFirstChild("HumanoidRootPart"))
      end

      local function xyraxSecondSeaHasTool(name)
          local player = game.Players.LocalPlayer
          local character = player.Character
          local backpack = player:FindFirstChild("Backpack")
          return (character and character:FindFirstChild(name)) or (backpack and backpack:FindFirstChild(name))
      end

      task.spawn(function()
          while task.wait(0.2) do
              if _G.AutoSecondSea and World1 and game.Players.LocalPlayer.Data.Level.Value >= 700 then
                  pcall(function()
                      local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                      local commF = remotes and remotes:FindFirstChild("CommF_")
                      local player = game.Players.LocalPlayer
                      local character = player.Character
                      local root = character and character:FindFirstChild("HumanoidRootPart")
                      if not (commF and character and root) then
                          xyraxSecondSeaReport("waiting for character / CommF")
                          return
                      end

                      local ok, progress = pcall(function()
                          return commF:InvokeServer("DressrosaQuestProgress")
                      end)
                      if not ok or type(progress) ~= "table" then
                          xyraxSecondSeaReport("waiting for Dressrosa quest state")
                          return
                      end

                      -- Step 1: Detective must issue the Key.
                      if not progress.TalkedDetective then
                          xyraxSecondSeaReport("Detective: travelling to Prison")
                          if xyraxSecondSeaMove(xyraxSecondSeaDetective, "second-sea-detective", 12) then
                              xyraxSecondSeaReport("Detective: requesting Key")
                              commF:InvokeServer("DressrosaQuestProgress", "Detective")
                          end
                          return
                      end

                      -- Step 2: own and equip the server-issued Key before
                      -- attempting the Frozen Village door.
                      if not progress.UsedKey then
                          local key = xyraxSecondSeaHasTool("Key")
                          if not key then
                              xyraxSecondSeaReport("Detective: Key missing; returning to retry")
                              xyraxSecondSeaMove(xyraxSecondSeaDetective, "second-sea-detective-key", 12)
                              if (root.Position - xyraxSecondSeaDetective.Position).Magnitude <= 12 then
                                  commF:InvokeServer("DressrosaQuestProgress", "Detective")
                              end
                              return
                          end

                          if key.Parent ~= character and character:FindFirstChild("Humanoid") then
                              character.Humanoid:EquipTool(key)
                          end
                          EquipWeapon("Key")
                          local map = workspace:FindFirstChild("Map")
                          local ice = map and map:FindFirstChild("Ice")
                          local door = ice and ice:FindFirstChild("Door")
                          local doorTarget = door and door.CFrame or xyraxSecondSeaIceDoor
                          xyraxSecondSeaReport(door and "Key: travelling to Ice Admiral door" or "Key: travelling to Frozen Village to stream door")
                          if xyraxSecondSeaMove(doorTarget, "second-sea-ice-door", 7) and door and door:IsA("BasePart") then
                              local heldKey = character:FindFirstChild("Key")
                              local keyHandle = heldKey and heldKey:FindFirstChild("Handle")
                              if type(firetouchinterest) == "function" then
                                  pcall(function()
                                      firetouchinterest(keyHandle or root, door, 0)
                                      task.wait(0.1)
                                      firetouchinterest(keyHandle or root, door, 1)
                                  end)
                              end
                              xyraxSecondSeaReport("Key: opening Ice Admiral door")
                          end
                          return
                      end

                      -- Step 3: after UsedKey is server-confirmed, fight the
                      -- actual live Ice Admiral, never a Replicated template.
                      if not progress.KilledIceBoss then
                          xyraxSecondSeaDetectiveConfirmed = false
                          local enemies = workspace:FindFirstChild("Enemies")
                          local iceAdmiral = enemies and enemies:FindFirstChild("Ice Admiral")
                          if iceAdmiral and iceAdmiral:FindFirstChild("HumanoidRootPart")
                              and iceAdmiral:FindFirstChild("Humanoid") and iceAdmiral.Humanoid.Health > 0 then
                              xyraxSecondSeaReport("Ice Admiral: fighting")
                              AutoHaki()
                              EquipWeapon(_G.SelectWeapon)
                              iceAdmiral.HumanoidRootPart.CanCollide = false
                              iceAdmiral.HumanoidRootPart.Size = Vector3.new(60, 60, 60)
                              -- FastAttack pauses while TweenCache is playing.  Do
                              -- not restart a new tween every 0.2 seconds or the
                              -- character can hold Black Leg without a stable hit.
                              local attackPoint = iceAdmiral.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0)
                              if (root.Position - attackPoint.Position).Magnitude > 8 then
                                  xyraxSecondSeaMove(attackPoint, "second-sea-ice-admiral-fight", 8)
                                  return
                              end
                              local damageState = XyraxAutomation.WatchDamage(iceAdmiral, "Auto Second Sea: Ice Admiral", 8, 1)
                              if damageState == "retry" then
                                  XyraxAutomation.ResetDamageCombat()
                                  xyraxSecondSeaReport("Ice Admiral: no damage; repositioning and retrying")
                                  return
                              elseif damageState == "abandon" then
                                  -- Keep the Sea 2 quest active: a live boss may
                                  -- briefly reject hits while its server state loads.
                                  XyraxAutomation.DamageWatchRecords[iceAdmiral] = nil
                                  xyraxSecondSeaReport("Ice Admiral: no damage yet; continuing attack")
                              end
                              XyraxAutomation.TryDarkStepV("Auto Second Sea: Ice Admiral", iceAdmiral)
                              -- Every other boss worker drives one manual
                              -- BladeHits so the M1 does not depend on the
                              -- background Fast Attack pass alone.  Ice
                              -- Admiral was the only path without it.
                              local fastAttack = (getgenv and getgenv().rz_FastAttack)
                                  or rz_FastAttack or _G.rz_FastAttack
                              if fastAttack and type(fastAttack.BladeHits) == "function" then
                                  pcall(function()
                                      fastAttack:BladeHits()
                                  end)
                              end
                              local heldTool = character:FindFirstChildOfClass("Tool")
                              if heldTool then
                                  pcall(function()
                                      heldTool:Activate()
                                  end)
                              end
                              game:GetService("VirtualUser"):CaptureController()
                              game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 870), workspace.CurrentCamera.CFrame)
                          else
                              xyraxSecondSeaReport("Ice Admiral: travelling to cave / waiting for spawn")
                              xyraxSecondSeaMove(xyraxSecondSeaIceDoor, "second-sea-ice-admiral", 25)
                          end
                          return
                      end

                      -- Step 4: the game dialogue explicitly requires a
                      -- second Detective visit after Ice Admiral is defeated.
                      -- Remember that approval so the following movement to
                      -- Middle Town is not reset back to Prison next tick.
                      if not xyraxSecondSeaDetectiveConfirmed then
                          local detectiveRoot = xyraxSecondSeaFindNpcRoot("Military Detective")
                          local detectiveTarget = detectiveRoot and detectiveRoot.CFrame or xyraxSecondSeaDetective
                          xyraxSecondSeaReport(detectiveRoot and "Detective: returning after Ice Admiral" or "Detective: returning to Prison to stream NPC")
                          if not xyraxSecondSeaMove(detectiveTarget, "second-sea-detective-complete", 12) then
                              return
                          end
                          local detectiveOk, detectiveState = pcall(function()
                              return commF:InvokeServer("DressrosaQuestProgress", "Detective")
                          end)
                          if not detectiveOk or detectiveState ~= 2 then
                              xyraxSecondSeaReport("Detective: confirming Ice Admiral information")
                              return
                          end
                          xyraxSecondSeaDetectiveConfirmed = true
                          return
                      end

                      -- Step 5: only Experienced Captain's approved
                      -- Dressrosa dialogue may trigger TravelDressrosa.
                      local captainRoot = xyraxSecondSeaFindNpcRoot("Experienced Captain")
                      local captainTarget = captainRoot and captainRoot.CFrame or xyraxSecondSeaMiddleTown
                      xyraxSecondSeaReport(captainRoot and "Captain: travelling to Experienced Captain" or "Captain: travelling to Middle Town to stream NPC")
                      if not xyraxSecondSeaMove(captainTarget, "second-sea-experienced-captain", 12) then
                          return
                      end
                      local captainOk, captainState = pcall(function()
                          return commF:InvokeServer("DressrosaQuestProgress", "Dressrosa")
                      end)
                      if captainOk and captainState == 0 then
                          xyraxSecondSeaReport("Captain: travelling to Second Sea")
                          commF:InvokeServer("TravelDressrosa")
                      else
                          xyraxSecondSeaReport("Captain: waiting for travel approval")
                      end
                  end)
              end
          end
      end)
    end

