       Items:Toggle("Auto Get Saber", true,function(Values) 
          XyraxAutomation.Desired.Saber = Values
       end)

       -- Live status for diagnosing the Saber quest.  It is intentionally a
       -- UI label as well as a throttled console log, so the exact blocked
       -- step remains visible even when the executor console is closed.
       XyraxAutomation.SaberDebug = true
       XyraxAutomation.SaberDebugLabel = Items:Label("Saber Debug: waiting for Auto Saber")
       XyraxAutomation.SaberLastStep = nil
       XyraxAutomation.ReportSaberStep = function(step)
           step = tostring(step or "unknown")
           XyraxAutomation.SaberStep = step
           local label = XyraxAutomation.SaberDebugLabel
           if label then
               label:Set("Saber Debug: " .. step)
           end
           if XyraxAutomation.SaberDebug and XyraxAutomation.SaberLastStep ~= step then
               XyraxAutomation.SaberLastStep = step
               print("[BfRef Saber] " .. step)
           end
       end
       Items:Toggle("Saber Debug Log", true, function(value)
           XyraxAutomation.SaberDebug = value
       end)

       -- Temporary diagnostic for the Saber quest state.  It observes only
       -- map/tool state and never invokes a quest Remote, so testing it cannot
       -- advance or alter the puzzle by itself.
       -- Debug was useful while repairing the puzzle, but continuously
       -- scanning the streamed map is unnecessary during normal farming.
       local xyraxLastSaberDebug = nil
       local xyraxLastSaberDebugAt = 0
       local function xyraxSaberDebug()
           if not XyraxAutomation.SaberDebug then
               return
           end

           -- Searching every Workspace descendant is expensive in a live
           -- server.  The old diagnostic did that every frame even though its
           -- output was throttled to three seconds, which was the FPS drop.
           local now = os.clock()
           if now - xyraxLastSaberDebugAt < 3 then
               return
           end

           local player = game:GetService("Players").LocalPlayer
           local character = player.Character
           local root = character and character:FindFirstChild("HumanoidRootPart")
           local map = workspace:FindFirstChild("Map")
           local jungle = map and map:FindFirstChild("Jungle")
           local finalPart = jungle and jungle:FindFirstChild("Final") and jungle.Final:FindFirstChild("Part")
           local questPlates = jungle and jungle:FindFirstChild("QuestPlates")
           local platesDoor = questPlates and questPlates:FindFirstChild("Door")
           local desert = map and map:FindFirstChild("Desert")
           local burnPart = desert and desert:FindFirstChild("Burn") and desert.Burn:FindFirstChild("Part")
           local heldTorch = (character and character:FindFirstChild("Torch")) or player.Backpack:FindFirstChild("Torch")
           local worldTorch = nil
           -- A full Workspace descendant scan is needed only while actually
           -- looking for Torch.  Do not do it during Plates/Boss/Farm states.
           if not heldTorch and (xyraxSaberStage == "Torch" or xyraxSaberAwaitingTorch) then
               for _, candidate in pairs(workspace:GetDescendants()) do
                   if candidate:IsA("Tool") and candidate.Name == "Torch" then
                       worldTorch = candidate
                       break
                   end
               end
           end

           local state
           if finalPart and finalPart.Transparency ~= 0 then
               state = "Saber room open; waiting for Saber Expert"
           elseif platesDoor and platesDoor.Transparency == 0 then
               state = "Jungle plates pending"
           elseif burnPart and burnPart.Transparency == 0 then
               state = heldTorch and "Torch held; moving to Desert" or "Torch missing; waiting at Jungle pickup"
           elseif burnPart and burnPart.Transparency ~= 0 then
               state = "Curtain burned; getting Cup"
           elseif xyraxSaberAwaitingTorch then
               state = heldTorch and "Torch held; waiting for Desert stream" or "Torch missing; waiting at Jungle pickup"
           else
               state = "Saber map state unavailable; waiting for stream"
           end

           local stateKey = state
               .. " | stage=" .. tostring(xyraxSaberStage)
               .. " | final=" .. tostring(finalPart and finalPart.Transparency)
               .. " | door=" .. tostring(platesDoor and platesDoor.Transparency)
               .. " | burn=" .. tostring(burnPart and burnPart.Transparency)
               .. " | torch=" .. (heldTorch and ("held:" .. heldTorch.Parent.Name) or (worldTorch and ("world:" .. worldTorch:GetFullName()) or "missing"))
               .. " | torchPart=" .. tostring(XyraxAutomation.SaberTorchPart or "none")
           local detail = stateKey
               .. " | pos=" .. (root and string.format("%.0f, %.0f, %.0f", root.Position.X, root.Position.Y, root.Position.Z) or "no character")
           xyraxLastSaberDebug = stateKey
           xyraxLastSaberDebugAt = now
           print("[BfRef Saber Debug] " .. detail)
       end

       -- topos creates a new Tween every call.  Saber used to call it every
       -- frame while travelling, leaving dozens of active Tweens behind.  Use
       -- the existing TP1/topos route, but refresh a destination at most once
       -- per 0.8 seconds.
       local xyraxSaberTravelTarget = nil
       local xyraxSaberTravelAt = 0
       local function xyraxSaberTravel(destination, tag)
           local character = game.Players.LocalPlayer.Character
           local root = character and character:FindFirstChild("HumanoidRootPart")
           if not root then
               return false
           end
           if (root.Position - destination.Position).Magnitude <= 5 then
               return true
           end
           local tweenPlaying = _G.TweenCache and _G.TweenCache.PlaybackState == Enum.PlaybackState.Playing
           if xyraxSaberTravelTarget ~= tag or not tweenPlaying or os.clock() - xyraxSaberTravelAt >= 0.8 then
               xyraxSaberTravelTarget = tag
               xyraxSaberTravelAt = os.clock()
               TP1(destination)
           end
           return false
       end

       local xyraxSaberBurnTouchAt = 0
       local xyraxSaberRelicTouchAt = 0
       -- Captured while the player was physically against the brown Saber
       -- curtain.  This is the live approach point, unlike the old CFrame
       -- below the Desert house.
       local xyraxSaberCurtainCFrame = CFrame.new(1122.16443, -0.0255184472, 4388.17529, -0.0131619452, 1.01260778e-09, 0.999913394, 5.29517541e-09, 1, -9.42994571e-10, -0.999913394, 5.28230526e-09, -0.0131619452)
       -- Fallback stream points for the physical Cup quest.  Live instances
       -- are always preferred below; these only bring Ice/NPCs into range
       -- before their streamed objects can be found.
       local xyraxSaberWaterFallback = CFrame.new(1347.7124, 37.3751602, -1325.6488)
       local xyraxSaberSickManFallback = CFrame.new(1389.74451, 88.1519318, -1298.90796)
       local xyraxSaberBurnDebugAt = 0
       local function xyraxDebugSaberBurnParts(burn)
           if not burn or os.clock() - xyraxSaberBurnDebugAt < 3 then
               return
           end
           xyraxSaberBurnDebugAt = os.clock()
           local parts = {}
           for index, item in ipairs(burn:GetChildren()) do
               if item:IsA("BasePart") then
                   local position = item.Position
                   local size = item.Size
                   table.insert(parts, string.format(
                       "%d:%s pos=(%.1f,%.1f,%.1f) size=(%.1f,%.1f,%.1f) trans=%.2f touch=%s",
                       index,
                       item.Name,
                       position.X, position.Y, position.Z,
                       size.X, size.Y, size.Z,
                       item.Transparency,
                       tostring(item:FindFirstChildOfClass("TouchTransmitter") ~= nil)
                   ))
               end
           end
           print("[BfRef Saber Burn Debug] " .. table.concat(parts, " | "))
       end

       local function xyraxSaberBurnDoor(burnPart)
           -- Move to the verified curtain even while Desert.Burn has not
           -- replicated yet; arriving here is what streams the Desert model
           -- in.  Once Burn is present, emit the legacy physical touch too.
           -- The captured CFrame is flush against the curtain.  Move two
           -- studs backward in that captured orientation so the HRP waits in
           -- front of it, close enough to burn but never embedded in it.
           local destination = xyraxSaberCurtainCFrame * CFrame.new(0, 0, 1.8)
           if xyraxSaberTravel(destination, "saber-verified-curtain") then
               -- Do not submit DestroyTorch until the streamed Burn part is
               -- actually available.  A successful travel alone is not a
               -- successful burn.
               if not (burnPart and burnPart:IsA("BasePart") and type(firetouchinterest) == "function") then
                   return false
               end
               local character = game.Players.LocalPlayer.Character
               local root = character and character:FindFirstChild("HumanoidRootPart")
               local heldTorch = character and character:FindFirstChild("Torch")
               local torchHandle = heldTorch and heldTorch:FindFirstChild("Handle")
               if not (root and heldTorch) then
                   return false
               end
               if os.clock() - xyraxSaberBurnTouchAt >= 1 then
                   xyraxSaberBurnTouchAt = os.clock()
                   pcall(function()
                       -- The game checks the held Torch contact, not a bare
                       -- character-root contact with the curtain.
                       firetouchinterest(torchHandle or root, burnPart, 0)
                       task.wait(0.1)
                       firetouchinterest(torchHandle or root, burnPart, 1)
                   end)
               end
               return true
           end
           return false
       end

       local function xyraxSaberPlaceRelic()
           local player = game:GetService("Players").LocalPlayer
           local character = player.Character
           local backpack = player:FindFirstChild("Backpack")
           local relic = (character and character:FindFirstChild("Relic"))
               or (backpack and backpack:FindFirstChild("Relic"))
           local map = workspace:FindFirstChild("Map")
           local jungle = map and map:FindFirstChild("Jungle")
           local final = jungle and jungle:FindFirstChild("Final")
           local slot = final and final:FindFirstChild("Part")
           local root = character and character:FindFirstChild("HumanoidRootPart")
           if not (relic and slot and slot:IsA("BasePart") and root) then
               return false
           end

           EquipWeapon("Relic")
           -- The map dump confirms Final.Part is the locked Final door.  The
           -- server expects the held Relic to contact that door before it
           -- accepts ProQuestProgress("PlaceRelic").
           -- Stand two studs from it and derive rotation from the actual
           -- socket position; this guarantees the character faces the Part
           -- instead of assuming the map's authored orientation is correct.
           local approach = slot.CFrame * CFrame.new(0, 0, 2)
           local destination = CFrame.lookAt(approach.Position, slot.Position)
           if xyraxSaberTravel(destination, "saber-relic-socket") then
               if type(firetouchinterest) == "function" and os.clock() - xyraxSaberRelicTouchAt >= 1 then
                   xyraxSaberRelicTouchAt = os.clock()
                   pcall(function()
                       local heldRelic = character:FindFirstChild("Relic")
                       local relicHandle = heldRelic and heldRelic:FindFirstChild("Handle")
                       firetouchinterest(relicHandle or root, slot, 0)
                       task.wait(0.1)
                       firetouchinterest(relicHandle or root, slot, 1)
                   end)
               end
               return true
           end
           return false
       end

       -- The Torch is a server-spawned Tool, not one of the decorative Torch
       -- models in Map.  Once at the actual basement pickup position, use its
       -- Handle as the final tween/touch target when it becomes visible.
       local xyraxSaberTorchPickup = CFrame.new(-1610.00757, 11.5049858, 164.001587, 0.984807551, -0.167722285, -0.0449818149, 0.17364943, 0.951244235, 0.254912198, 3.42372805e-05, -0.258850515, 0.965917408)
       local xyraxSaberTorchPartScanAt = 0
       local xyraxSaberTorchPart = nil
       local function xyraxFindSaberQuestTorch()
           -- Quest Tools are created directly under Workspace.  Do not search
           -- all descendants here: Map has many decorative Torch models.
           for _, item in ipairs(workspace:GetChildren()) do
               if item:IsA("Tool") and item.Name == "Torch" then
                   return item
               end
           end
           return nil
       end

       local function xyraxFindSaberTorchPart()
           if xyraxSaberTorchPart and xyraxSaberTorchPart.Parent then
               return xyraxSaberTorchPart
           end
           if os.clock() - xyraxSaberTorchPartScanAt < 2 then
               return nil
           end
           xyraxSaberTorchPartScanAt = os.clock()

           local map = workspace:FindFirstChild("Map")
           local jungle = map and map:FindFirstChild("Jungle")
           if not jungle then
               XyraxAutomation.SaberTorchPart = "Jungle unavailable"
               return nil
           end

           local closestPart, closestDistance, closestHasTouch
           for _, item in ipairs(jungle:GetDescendants()) do
               if item:IsA("BasePart") then
                   local parent = item.Parent
                   local isTorchPart = string.lower(item.Name) == "torch"
                       or (parent and string.lower(parent.Name) == "torch")
                   if isTorchPart then
                       local distance = (item.Position - xyraxSaberTorchPickup.Position).Magnitude
                       -- Restrict the search to the secret-room area.  Jungle
                       -- has many ordinary decorative torches elsewhere.
                       if distance <= 120 then
                           local hasTouch = item:FindFirstChildOfClass("TouchTransmitter") ~= nil
                           if not closestPart
                               or (hasTouch and not closestHasTouch)
                               or (hasTouch == closestHasTouch and distance < closestDistance) then
                               closestPart = item
                               closestDistance = distance
                               closestHasTouch = hasTouch
                           end
                       end
                   end
               end
           end

           xyraxSaberTorchPart = closestPart
           XyraxAutomation.SaberTorchPart = closestPart
               and (closestPart:GetFullName() .. string.format(" (%.1f)", closestDistance))
               or "none near secret room"
           return closestPart
       end

       local function xyraxCollectSaberTorch()
           local player = game:GetService("Players").LocalPlayer
           local character = player.Character
           local root = character and character:FindFirstChild("HumanoidRootPart")
           if not root then
               return
           end

           local torch = xyraxFindSaberQuestTorch()
           local handle = torch and torch:FindFirstChild("Handle")
           if handle and handle:IsA("BasePart") then
               if xyraxSaberTravel(handle.CFrame, "saber-live-torch") and type(firetouchinterest) == "function" then
                   pcall(function()
                       firetouchinterest(root, handle, 0)
                       task.wait(0.1)
                       firetouchinterest(root, handle, 1)
                   end)
               end
               return
           end

           -- The quest Torch can replicate as a map Part before it becomes a
           -- Tool.  Aim at that exact live Part rather than the old room-center
           -- coordinate, then emit a touch when close enough.
           local torchPart = xyraxFindSaberTorchPart()
           if torchPart then
               if xyraxSaberTravel(torchPart.CFrame, "saber-torch-part") and type(firetouchinterest) == "function" then
                   pcall(function()
                       firetouchinterest(root, torchPart, 0)
                       task.wait(0.1)
                       firetouchinterest(root, torchPart, 1)
                   end)
               end
               return
           end

           -- This is the Torch's room position.  The previous entry-and-return
           -- route accidentally reused one of the Jungle plate positions,
           -- causing the visible back-and-forth movement.  Remain here while
           -- the server creates the real Torch Tool, then touch that Tool.
           xyraxSaberTravel(xyraxSaberTorchPickup, "saber-torch-pickup")
       end
       
        -- This worker follows the physical Saber quest order.  The previous
        -- version only invoked every ProQuestProgress Remote from the current
        -- Farm Level location.  On a new Lv.200 account those calls are
        -- rejected, while the scheduler has already paused Auto Farm, leaving
        -- the character motionless.
        task.spawn(function()
            local mobLeaderSpawn = CFrame.new(-2852, 8, 5345)

            local function questState()
                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                local commF = remotes and remotes:FindFirstChild("CommF_")
                if not commF then
                    return nil
                end
                local ok, result = pcall(function()
                    return commF:InvokeServer("ProQuestProgress")
                end)
                return ok and type(result) == "table" and result or nil
            end

            local function progressQuest(...)
                local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
                local commF = remotes and remotes:FindFirstChild("CommF_")
                if commF then
                    local args = {...}
                    local ok, result = pcall(function()
                        return commF:InvokeServer("ProQuestProgress", unpack(args))
                    end)
                    return ok, result
                end
                return false, nil
            end

            -- Cup is a three-location physical sequence.  Calling the
            -- Remotes from the Desert curtain skips the game client's own
            -- touch checks and leaves the quest state unchanged.
            local cupPhase = "Water"
            local function runCupStage(character, backpack, root, map)
                xyraxSetSaberStage("Cup")
                local cup = character:FindFirstChild("Cup") or backpack:FindFirstChild("Cup")
                if not cup then
                    local desert = map and map:FindFirstChild("Desert")
                    local cupPart = desert and desert:FindFirstChild("Cup", true)
                    if cupPart and cupPart:IsA("BasePart") then
                        XyraxAutomation.ReportSaberStep("Cup: travelling to Desert cup")
                        if xyraxSaberTravel(cupPart.CFrame, "saber-cup") then
                            if type(firetouchinterest) == "function" then
                                pcall(function()
                                    firetouchinterest(root, cupPart, 0)
                                    task.wait(0.1)
                                    firetouchinterest(root, cupPart, 1)
                                end)
                            end
                            progressQuest("GetCup")
                        end
                    else
                        XyraxAutomation.ReportSaberStep("Cup: waiting for Desert cup to stream")
                        xyraxSaberTravel(xyraxSaberCurtainCFrame * CFrame.new(0, 0, 1.8), "saber-stream-desert-cup")
                    end
                    return
                end

                _G.XyraxSaberLockedTool = "Cup"
                if cup.Parent ~= character and character:FindFirstChild("Humanoid") then
                    character.Humanoid:EquipTool(cup)
                    cup = character:FindFirstChild("Cup") or cup
                end
                EquipWeapon("Cup")
                local heldCup = character:FindFirstChild("Cup")
                if not heldCup then
                    XyraxAutomation.ReportSaberStep("ERROR: Cup found but could not equip")
                    return
                end

                if cupPhase ~= "SickMan" then
                    local ice = map and map:FindFirstChild("Ice")
                    local particleDrop = ice and ice:FindFirstChild("ParticleDrop")
                    local water = particleDrop and particleDrop:FindFirstChild("Water")
                    local waterTarget = water and water.CFrame or xyraxSaberWaterFallback
                    XyraxAutomation.ReportSaberStep(water and "Cup: travelling to Frozen Village water" or "Cup: travelling to Frozen Village to stream water")
                    if xyraxSaberTravel(waterTarget, "saber-cup-water") and water and water:IsA("BasePart") then
                        local cupHandle = heldCup:FindFirstChild("Handle")
                        if type(firetouchinterest) == "function" then
                            pcall(function()
                                firetouchinterest(cupHandle or root, water, 0)
                                task.wait(0.1)
                                firetouchinterest(cupHandle or root, water, 1)
                            end)
                        end
                        progressQuest("FillCup", heldCup)
                        cupPhase = "SickMan"
                    end
                    return
                end

                local npcs = workspace:FindFirstChild("NPCs")
                local sickMan = (npcs and npcs:FindFirstChild("Sick Man")) or workspace:FindFirstChild("Sick Man")
                local sickRoot = sickMan and sickMan:FindFirstChild("HumanoidRootPart")
                local sickTarget = sickRoot and (sickRoot.CFrame * CFrame.new(0, 0, 3)) or xyraxSaberSickManFallback
                XyraxAutomation.ReportSaberStep(sickRoot and "Cup: returning filled cup to Sick Man" or "Cup: travelling to Sick Man to stream NPC")
                if xyraxSaberTravel(sickTarget, "saber-sick-man") then
                    progressQuest("SickMan")
                end
            end

            -- Saber Expert must be fought with an actual fighting-style Tool.
            -- Do not rely on the display name (Combat, Black Step, Dark Step,
            -- Electric, etc.); every valid style advertises ToolTip == Melee.
            local function xyraxEquipSaberMelee(character, backpack)
                _G.XyraxSaberLockedTool = nil
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                if not (character and backpack and humanoid) then
                    return nil
                end

                for _, container in ipairs({character, backpack}) do
                    for _, tool in ipairs(container:GetChildren()) do
                        if tool:IsA("Tool") and tool.ToolTip == "Melee" then
                            if tool.Parent ~= character then
                                humanoid:EquipTool(tool)
                            end
                            return tool.Name
                        end
                    end
                end
                return nil
            end

            while task.wait(0.15) do
                if AutoSaber and game.Players.LocalPlayer.Data.Level.Value >= 200 then
                    local completed, saberError = pcall(function()
                        xyraxSaberDebug()

                        local player = game:GetService("Players").LocalPlayer
                        local character = player.Character
                        local root = character and character:FindFirstChild("HumanoidRootPart")
                        local backpack = player:FindFirstChild("Backpack")
                        local enemies = workspace:FindFirstChild("Enemies")
                        if not (root and backpack and enemies) then
                            XyraxAutomation.ReportSaberStep("waiting for character / Backpack / Enemies")
                            return
                        end
                        local torch = character:FindFirstChild("Torch") or backpack:FindFirstChild("Torch")
                        local state = questState()
                        if state and state.UsedTorch and _G.XyraxSaberLockedTool == "Torch" then
                            -- The curtain accepted Torch; allow normal combat
                            -- equipment again for Cup/Mob Leader.
                            _G.XyraxSaberLockedTool = nil
                        end
                        if state and state.UsedCup and _G.XyraxSaberLockedTool == "Cup" then
                            _G.XyraxSaberLockedTool = nil
                            cupPhase = "Water"
                        end
                        -- UsedRelic is the last quest-item checkpoint.  Clear
                        -- its reservation before inspecting Saber Expert: the
                        -- old flow reached the boss with EquipWeapon still
                        -- forced to Relic, so Black Step/other Melee tools
                        -- were never equipped and HP stayed unchanged.
                        if state and state.UsedRelic and _G.XyraxSaberLockedTool == "Relic" then
                            _G.XyraxSaberLockedTool = nil
                        end

                        local expert, expertSource = xyraxFindEnemyByNames({"Saber Expert"})
                        -- Saber Expert can be replicated before the Final
                        -- door is unlocked.  Do not chase that model until
                        -- the server has accepted the Relic; otherwise the
                        -- worker skips Final.Part forever and attacks a boss
                        -- behind its still-locked room.
                        if expert and expertSource == "ReplicatedStorage" and state and state.UsedRelic
                            and expert:FindFirstChild("HumanoidRootPart") then
                            -- Same behaviour as Pole/Saw: the distant model
                            -- supplies the real boss-room coordinate.  Travel
                            -- there to stream it, but never attack or edit a
                            -- ReplicatedStorage model.
                            xyraxSetSaberStage("Boss")
                            XyraxAutomation.ReportSaberStep("Boss: distant in ReplicatedStorage; travelling to spawn")
                            xyraxSaberTravel(expert.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0), "saber-expert-distant")
                            return
                        end
                        if expert and expertSource == "Workspace" and state and state.UsedRelic
                            and expert:FindFirstChild("HumanoidRootPart") and expert:FindFirstChild("Humanoid") then
                            xyraxSetSaberStage("Boss")
                            local distance = (root.Position - expert.HumanoidRootPart.Position).Magnitude
                            if distance > 40 then
                                XyraxAutomation.ReportSaberStep("Boss: approaching Saber Expert (" .. math.floor(distance) .. " studs)")
                                topos(expert.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
                            else
                                -- Do not recreate a tween while already in
                                -- range.  FastAttack deliberately skips a
                                -- target during movement, so the old loop
                                -- could reach Saber Expert yet never hit it.
                                local activeTween = _G.TweenCache
                                if activeTween and activeTween.PlaybackState == Enum.PlaybackState.Playing then
                                    activeTween:Cancel()
                                end
                                AutoHaki()
                                local meleeName = xyraxEquipSaberMelee(character, backpack)
                                if not meleeName then
                                    XyraxAutomation.ReportSaberStep("Boss: waiting for any Melee tool to equip")
                                    return
                                end
                                XyraxAutomation.TryDarkStepV("Saber Expert", expert)
                                local damageState = XyraxAutomation.WatchDamage(expert, "Saber Expert", 8, 1)
                                if damageState == "retry" then
                                    XyraxAutomation.ResetDamageCombat()
                                elseif damageState == "abandon" then
                                    XyraxAutomation.BlockDamageBoss("Saber Expert", "Saber Expert", XyraxAutomation.DamageBossBlockSeconds)
                                    XyraxAutomation.ResetDamageCombat()
                                    XyraxAutomation.ReportSaberStep("Boss: no damage after retry; yielding to Farm Level for 30 minutes")
                                    return
                                end
                                local fastAttack = (_ENV and _ENV.rz_FastAttack) or _G.rz_FastAttack
                                if fastAttack and type(fastAttack.BladeHits) == "function" then
                                    pcall(function()
                                        fastAttack:BladeHits()
                                    end)
                                end
                                pcall(function()
                                    game:GetService("VirtualUser"):CaptureController()
                                    game:GetService("VirtualUser"):Button1Down(Vector2.new(1280, 672))
                                end)
                                XyraxAutomation.ReportSaberStep("Boss: attacking Saber Expert (HP " .. math.floor(expert.Humanoid.Health) .. ")")
                            end
                            return
                        elseif expert and (not state or not state.UsedRelic) then
                            -- Saber Expert can replicate before Final.Part
                            -- opens.  Relic is still the required next step;
                            -- leave the status line to the active quest step.
                        end

                        local map = workspace:FindFirstChild("Map")
                        local jungle = map and map:FindFirstChild("Jungle")
                        local plates = jungle and jungle:FindFirstChild("QuestPlates")
                        local door = plates and plates:FindFirstChild("Door")

                        -- Travel to Jungle first when its streamed objects are
                        -- unavailable.  This makes a fresh Lv.200 account
                        -- start the puzzle instead of waiting at its farm.
                        if not jungle or not plates or not door then
                            -- Map streaming removes Jungle while travelling
                            -- across First Sea.  Never reset an already
                            -- confirmed Saber stage to Plates during that
                            -- brief gap: doing so overwrites the Mob Leader
                            -- combat tween with a Jungle tween every few
                            -- seconds.
                            -- Once the curtain has burned, Jungle commonly
                            -- streams out while the player remains in Desert.
                            -- Cup is in Desert, so do not let a missing Jungle
                            -- prevent this next physical quest step.
                            if (state and state.UsedTorch and not state.UsedCup)
                                or ((not state) and xyraxSaberStage == "Cup") then
                                runCupStage(character, backpack, root, map)
                            elseif torch then
                                xyraxSetSaberStage("Torch")
                                _G.XyraxSaberLockedTool = "Torch"
                                if torch.Parent ~= character and character:FindFirstChild("Humanoid") then
                                    character.Humanoid:EquipTool(torch)
                                end
                                EquipWeapon("Torch")
                                if not character:FindFirstChild("Torch") then
                                    XyraxAutomation.ReportSaberStep("ERROR: Torch found but could not equip")
                                    return
                                end
                                XyraxAutomation.ReportSaberStep("Torch: equipped; Jungle unloaded, continuing to Desert curtain")
                                xyraxSaberBurnDoor(nil)
                            elseif xyraxSaberStage == "MobLeader" then
                                local streamedState = questState()
                                if streamedState and streamedState.KilledMob then
                                    -- Jungle cannot stream back while we stay
                                    -- at Pirate Village.  Claim the Relic from
                                    -- Rich Son, then actively return to Jungle
                                    -- for the final socket instead of waiting.
                                    progressQuest("RichSon")
                                    local relic = character:FindFirstChild("Relic") or backpack:FindFirstChild("Relic")
                                    if relic then
                                        xyraxSetSaberStage("Relic")
                                        XyraxAutomation.ReportSaberStep("Mob Leader defeated; Relic received, returning to Jungle socket")
                                        xyraxSaberTravel(xyraxSaberTorchPickup, "saber-return-jungle-relic")
                                    else
                                        XyraxAutomation.ReportSaberStep("Mob Leader defeated; requesting Relic from Rich Son")
                                    end
                                else
                                    local mob = enemies:FindFirstChild("Mob Leader")
                                    if mob and mob:FindFirstChild("HumanoidRootPart") and mob:FindFirstChild("Humanoid")
                                        and mob.Humanoid.Health > 0 then
                                        XyraxAutomation.ReportSaberStep("Mob Leader: fighting while Jungle is unloaded")
                                        AutoHaki()
                                        EquipWeapon(_G.SelectWeapon)
                                        topos(mob.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
                                    else
                                        XyraxAutomation.ReportSaberStep("Mob Leader: returning to spawn while Jungle is unloaded")
                                        xyraxSaberTravel(mobLeaderSpawn, "saber-mob-leader")
                                    end
                                end
                            elseif (xyraxSaberStageRank[xyraxSaberStage] or 0) > xyraxSaberStageRank.Plates then
                                XyraxAutomation.ReportSaberStep(tostring(xyraxSaberStage) .. ": Jungle unloaded; preserving current stage")
                            else
                                xyraxSetSaberStage("Plates")
                                XyraxAutomation.ReportSaberStep("Plates: travelling to Jungle so map can stream")
                                xyraxSaberTravel(xyraxSaberTorchPickup, "saber-stream-jungle")
                            end
                            return
                        end

                        -- A transient Remote timeout must not turn Cup into a
                        -- nil-index error or send the player back to plates.
                        if not state then
                            if xyraxSaberStage == "Cup" then
                                runCupStage(character, backpack, root, map)
                            else
                                XyraxAutomation.ReportSaberStep("waiting for Saber quest state")
                            end
                            return
                        end

                        -- The five pressure plates are real touch parts.  Use
                        -- their live instances so a map update cannot leave us
                        -- walking to stale hard-coded positions.
                        if door.Transparency == 0 then
                            xyraxSetSaberStage("Plates")
                            local buttons = {}
                            for _, item in ipairs(plates:GetDescendants()) do
                                if item:IsA("BasePart") and item ~= door
                                    and item:FindFirstChildOfClass("TouchTransmitter") then
                                    table.insert(buttons, item)
                                end
                            end
                            table.sort(buttons, function(a, b)
                                return a:GetFullName() < b:GetFullName()
                            end)
                            if #buttons == 0 then
                                XyraxAutomation.ReportSaberStep("ERROR: found QuestPlates but no touch buttons")
                            else
                                XyraxAutomation.ReportSaberStep("Plates: pressing " .. tostring(#buttons) .. " buttons")
                            end
                            for _, button in ipairs(buttons) do
                                if not AutoSaber or door.Transparency ~= 0 then
                                    break
                                end
                                xyraxPressSaberPlate(button, "saber-plate:" .. button:GetFullName())
                            end
                            return
                        end

                        if not state or not state.UsedTorch then
                            xyraxSetSaberStage("Torch")
                            if torch then
                                -- Keep every legacy EquipWeapon call on the
                                -- Torch until the curtain has acknowledged it.
                                _G.XyraxSaberLockedTool = "Torch"
                                if torch.Parent ~= character and character:FindFirstChild("Humanoid") then
                                    character.Humanoid:EquipTool(torch)
                                    torch = character:FindFirstChild("Torch") or torch
                                end
                                EquipWeapon("Torch")
                                if not character:FindFirstChild("Torch") then
                                    XyraxAutomation.ReportSaberStep("ERROR: Torch found but could not equip")
                                    return
                                end
                                XyraxAutomation.ReportSaberStep("Torch: equipped; travelling to Desert curtain")
                                local desert = map and map:FindFirstChild("Desert")
                                local burn = desert and desert:FindFirstChild("Burn")
                                local burnPart = burn and burn:FindFirstChild("Part")
                                if xyraxSaberBurnDoor(burnPart) then
                                    progressQuest("DestroyTorch")
                                end
                            else
                                XyraxAutomation.ReportSaberStep("Torch: travelling to Jungle pickup")
                                if (root.Position - xyraxSaberTorchPickup.Position).Magnitude <= 12 then
                                    progressQuest("GetTorch")
                                end
                                xyraxCollectSaberTorch()
                            end
                            return
                        end

                        if not state.UsedCup then
                            runCupStage(character, backpack, root, map)
                            return
                        end

                        if not state.KilledMob then
                            xyraxSetSaberStage("MobLeader")
                            progressQuest("RichSon")
                            local mob = enemies:FindFirstChild("Mob Leader")
                            if mob and mob:FindFirstChild("HumanoidRootPart") and mob:FindFirstChild("Humanoid")
                                and mob.Humanoid.Health > 0 then
                                XyraxAutomation.ReportSaberStep("Mob Leader: fighting")
                                AutoHaki()
                                EquipWeapon(_G.SelectWeapon)
                                topos(mob.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
                            else
                                XyraxAutomation.ReportSaberStep("Mob Leader: travelling to spawn")
                                xyraxSaberTravel(mobLeaderSpawn, "saber-mob-leader")
                            end
                            return
                        end

                        if not state.UsedRelic then
                            xyraxSetSaberStage("Relic")
                            _G.XyraxSaberLockedTool = "Relic"
                            XyraxAutomation.ReportSaberStep("Relic: collecting / placing at Jungle socket")
                            progressQuest("RichSon")
                            if xyraxSaberPlaceRelic() then
                                progressQuest("PlaceRelic")
                            end
                            return
                        end
                        _G.XyraxSaberLockedTool = nil
                        XyraxAutomation.ReportSaberStep("Boss room open: waiting for Saber Expert; Farm Level should resume")
                    end)
                    if not completed then
                        XyraxAutomation.ReportSaberStep("ERROR: " .. tostring(saberError))
                    end
                end
            end
        end)
         
     PoleStatus = Items:Label("Check Boss Pole")
      
    task.spawn(function()
     while wait() do
       pcall(function()
      -- UI status must not trigger the expensive distant-boss scan by itself.
      -- The scheduler performs that scan only when Pole can actually run.
      if xyraxFindLiveEnemyByNames({"Lightning God", "Thunder God"}) then
         PoleStatus:Set("Pole Boss Spawning ✅")
          else
         PoleStatus:Set("Not Have Pole Boss ❌")
        end
       end)
      end
    end)
    
      Items:Toggle("Auto Get Sword Pole", true,function(Values)      
          XyraxAutomation.Desired.Pole = Values
       end)
       
       spawn(function()
        while wait() do
            if _G.Autopole then
                pcall(function()
                    if game:GetService("Workspace").Enemies:FindFirstChild("Thunder God") then
                        for i,v in pairs(game:GetService("Workspace").Enemies:GetChildren()) do
                            if v.Name == "Thunder God" then
                                if v:FindFirstChild("Humanoid") and v:FindFirstChild("HumanoidRootPart") and v.Humanoid.Health > 0 then
                                    repeat task.wait()
                                        AutoHaki()
                                        EquipWeapon(_G.SelectWeapon)
                                        v.HumanoidRootPart.CanCollide = false
                                        StartBring = true
                                        v.Humanoid.WalkSpeed = 0
                                        v.HumanoidRootPart.Size = Vector3.new(80,80,80)                             
                                        topos(v.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
                                        sethiddenproperty(game:GetService("Players").LocalPlayer,"SimulationRadius",math.huge)
                                    until not _G.Autopole or not v.Parent or v.Humanoid.Health <= 0
                                end
                            end
                        end
                    else
                        if game:GetService("ReplicatedStorage"):FindFirstChild("Thunder God") then
                            TP1(game:GetService("ReplicatedStorage"):FindFirstChild("Thunder God").HumanoidRootPart.CFrame * CFrame.new(5,10,2))
                        end
                    end
                end)
            end
        end
    end)                            
    
    Items:Toggle("Auto Get Sword Saw", true,function(Values)      
          XyraxAutomation.Desired.Saw = Values
       end)
       
     local SharkPos = CFrame.new(-690.33081054688, 15.09425163269, 1582.2380371094)
       spawn(function()
        while wait() do
            if  _G.Autosaw then
                pcall(function()
                    if game:GetService("Workspace").Enemies:FindFirstChild("The Saw") then
                        for i,v in pairs(game:GetService("Workspace").Enemies:GetChildren()) do
                            if v.Name == "The Saw" then
                                if v:FindFirstChild("Humanoid") and v:FindFirstChild("HumanoidRootPart") and v.Humanoid.Health > 0 then
                                    repeat task.wait(_G.FastAttackDelay)
                                        AutoHaki()
                                        EquipWeapon(_G.SelectWeapon)
                                        v.HumanoidRootPart.CanCollide = false
                                        v.Humanoid.WalkSpeed = 0
                                        v.HumanoidRootPart.Size = Vector3.new(50,50,50)
                                       topos(v.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
