 function IsIslandRaid(cu)
    if game:GetService("Workspace")["_WorldOrigin"].Locations:FindFirstChild("Island " .. cu) then
        min = 4500
        for r, v in pairs(game:GetService("Workspace")["_WorldOrigin"].Locations:GetChildren()) do
            if
                v.Name == "Island " .. cu and
                    (v.Position - game.Players.LocalPlayer.Character.HumanoidRootPart.Position).Magnitude < min
            then
                min = (v.Position - game.Players.LocalPlayer.Character.HumanoidRootPart.Position).Magnitude
            end
        end
        for r, v in pairs(game:GetService("Workspace")["_WorldOrigin"].Locations:GetChildren()) do
            if
                v.Name == "Island " .. cu and
                    (v.Position - game.Players.LocalPlayer.Character.HumanoidRootPart.Position).Magnitude <= min
            then
                return v
            end
        end
    end
end

function getNextIsland()
    TableIslandsRaid = {5, 4, 3, 2, 1}
    for r, v in pairs(TableIslandsRaid) do
        if IsIslandRaid(v) and (IsIslandRaid(v).Position - game.Players.LocalPlayer.Character.HumanoidRootPart.Position).Magnitude <= 4500 then
            return IsIslandRaid(v)
        end
    end
end

-- `source` identifies which caller is running this pass - "AutoRaid" (the
-- scheduler's Auto Raid Farm action) or "Dungeon" (the legacy, pre-scheduler
-- _G.Dungeon toggle further below).  Confirmed live: this function's own
-- enemy scan has no name/raid filter at all (any live Humanoid within 1000
-- studs of Workspace.Enemies qualifies), so once it locks onto something
-- like a stray "Snow Trooper" it used to keep tweening above that enemy's
-- head every 0.1s even after the scheduler had already moved Auto Raid's
-- job on to Superhuman/Farm Level - the old `until` only watched RaidFleeing
-- and the enemy's own HP, never whether the caller that started this pass
-- was still the active job.  xyraxAttackNearbyEnemiesStale() below is the
-- single re-checked guard for that, scoped to the source that started this
-- specific pass so a stale _G.Dungeon can never prop up an Auto Raid pass
-- (or vice versa) - each source's own stop condition is independent.
local function xyraxAttackNearbyEnemiesStale(source)
    if source == "AutoRaid" then
        return not _G.AutoRaid or XyraxAutomation.ActiveJob ~= "Auto Raid"
    end
    if source == "Dungeon" then
        return not _G.Dungeon
    end
    return false
end

function attackNearbyEnemies(source)
    -- The Auto Raid HP watchdog can set this while this function is already
    -- running.  Return immediately so no combat tween can pull the player
    -- back down from the flee position.
    if XyraxAutomation and XyraxAutomation.RaidFleeing then
        return
    end
    if xyraxAttackNearbyEnemiesStale(source) then
        return
    end

    local enemies = {}
    for _, v in pairs(game:GetService("Workspace").Enemies:GetChildren()) do
        if v:FindFirstChild("HumanoidRootPart") and v:FindFirstChild("Humanoid") and v.Humanoid.Health > 0 then
            local distance = (v.HumanoidRootPart.Position - game.Players.LocalPlayer.Character.HumanoidRootPart.Position).Magnitude
            if distance <= 1000 then
                table.insert(enemies, v)
            end
        end
    end

    -- Confirmed live (RaidDebug session): Loop 1 below only walks the
    -- character close and waits for Health<=0 - it never fires a hit
    -- itself.  On Island 4/5 the shared FastAttack aura (still scanning
    -- during "Auto Raid") was finishing every kill inside that wait, so by
    -- the time the old Health=0 pass below got a turn every enemy in
    -- `enemies` already had Health=0 and the assignment never ran.
    -- ShouldScanForFastAttack() now refuses to scan while Auto Raid is on
    -- Island 4/5, so checking the island first and skipping Loop 1 entirely
    -- there is what actually lets Health=0 be the one to do the kill.
    if IsIslandRaid(4) or IsIslandRaid(5) then
        for _, enemy in pairs(enemies) do
            repeat
                if XyraxAutomation and XyraxAutomation.RaidFleeing then
                    return
                end
                if xyraxAttackNearbyEnemiesStale(source) then
                    return
                end
                if enemy:FindFirstChild("Humanoid") and enemy.Humanoid.Health > 0 then
                    EquipWeapon(_G.SelectWeapon)
                    enemy.Humanoid.Health = 0
                    if XyraxAutomation and XyraxAutomation.RaidFleeing then
                        return
                    end
                    if xyraxAttackNearbyEnemiesStale(source) then
                        return
                    end
                    topos(enemy.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
                    wait(0.1)
                end
            until (XyraxAutomation and XyraxAutomation.RaidFleeing)
                or xyraxAttackNearbyEnemiesStale(source)
                or not enemy:FindFirstChild("Humanoid") or enemy.Humanoid.Health <= 0
        end
        return
    end

    -- Island 1-3 (and anywhere else Auto Raid runs attackNearbyEnemies,
    -- e.g. between islands): unchanged from before this fix.  FastAttack
    -- does the actual killing here exactly as it always has.
    for _, enemy in pairs(enemies) do
        repeat
            if XyraxAutomation and XyraxAutomation.RaidFleeing then
                return
            end
            if xyraxAttackNearbyEnemiesStale(source) then
                return
            end
            if enemy:FindFirstChild("Humanoid") and enemy.Humanoid.Health > 0 then
                EquipWeapon(_G.SelectWeapon)
                if XyraxAutomation and XyraxAutomation.RaidFleeing then
                    return
                end
                if xyraxAttackNearbyEnemiesStale(source) then
                    return
                end
                topos(enemy.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
                wait(0.1)
            end
        until (XyraxAutomation and XyraxAutomation.RaidFleeing)
            or xyraxAttackNearbyEnemiesStale(source)
            or not enemy:FindFirstChild("Humanoid") or enemy.Humanoid.Health <= 0
    end
end

