-- GachaNetworkRF is the current shared Gacha endpoint.  Unlike the legacy
-- Cousin remote it works in both Sea 1 and Sea 2 and exposes the server's
-- money/cooldown decision before a purchase is attempted.
XyraxAutomation.RandomFruit = XyraxAutomation.RandomFruit or {NextAt = 0, CloseAt = 0, LastStatus = nil}
XyraxAutomation.SetupRandomFruitUI = function()
    local state = XyraxAutomation.RandomFruit
    if state.GuiConnection then
        pcall(function() state.GuiConnection:Disconnect() end)
    end
    local player = game:GetService("Players").LocalPlayer
    local playerGui = player:FindFirstChild("PlayerGui")
    if not playerGui then return end
    local function hideMainWindow(gui)
        if XyraxAutomation.Desired.RandomFruit
            and gui:IsA("ScreenGui")
            and gui.Name == "ZiolesGacha_Window" then
            gui.Enabled = false
            print("[BfRef RandomFruit] hidden main Gacha UI")
        end
    end
    for _, gui in ipairs(playerGui:GetChildren()) do
        hideMainWindow(gui)
    end
    state.GuiConnection = playerGui.ChildAdded:Connect(hideMainWindow)
end
XyraxAutomation.CloseRandomFruitResult = function()
    -- The "you won X" reveal card (the one with the visible X button) is a
    -- SEPARATE module from the shop window - ReplicatedStorage.Controllers.
    -- UI.Spinner, not GachaWindow.  GachaWindow:IsOpen() was always false
    -- for this popup (it tracks the shop UI's own open state, never set by
    -- a purchase that skips the shop entirely), so the direct-Close path
    -- silently fell through to the slow click-simulation fallback every
    -- time.  Try Spinner first; it is exactly what its own reveal-close
    -- button calls (Spinner.lua: Close() disables Window.Screen).
    local spinnerOk, spinnerResult = pcall(function()
        local Spinner = require(game:GetService("ReplicatedStorage").Controllers.UI.Spinner)
        if Spinner.IsOpen and Spinner:IsOpen() then
            Spinner:Close()
            return true
        end
        return false
    end)
    if spinnerOk and spinnerResult then
        print("[BfRef RandomFruit] closed Spinner reveal (direct Close)")
        return true
    end

    -- Confirmed from the client dump (ReplicatedStorage.Controllers.UI.
    -- GachaWindow): the same "X" button the player would click just calls
    -- this module's own Close(true) method (u0:Close(true) in the Cousin
    -- window body).  require() on the same ModuleScript instance returns
    -- that exact live table, so calling Close(true) directly reproduces the
    -- real close button with no button to find, no coordinates, and no
    -- dependency on the reveal animation having finished rendering one.
    local directOk, directResult = pcall(function()
        local GachaWindow = require(game:GetService("ReplicatedStorage").Controllers.UI.GachaWindow)
        if GachaWindow.IsOpen and GachaWindow:IsOpen() then
            GachaWindow:Close(true)
            return true
        end
        return false
    end)
    if directOk and directResult then
        print("[BfRef RandomFruit] closed Gacha window (direct Close)")
        return true
    end

    -- Fallback only: click-simulation kept in case the module path or
    -- Close() signature ever changes in a future update.
    local player = game:GetService("Players").LocalPlayer
    local playerGui = player:FindFirstChild("PlayerGui")
    if not playerGui then return false end

    local function visible(instance)
        local current = instance
        while current and current ~= playerGui do
            if current:IsA("GuiObject") and not current.Visible then return false end
            if current:IsA("ScreenGui") and not current.Enabled then return false end
            current = current.Parent
        end
        return current == playerGui
    end
    local function gachaButton(button)
        if not (button:IsA("GuiButton") and visible(button)) then return false end
        local current, belongs = button, false
        while current and current ~= playerGui do
            local name = string.lower(current.Name)
            if string.find(name, "gacha", 1, true)
                or string.find(name, "zioles", 1, true)
                or string.find(name, "spinner", 1, true) then
                belongs = true
                break
            end
            current = current.Parent
        end
        if not belongs then return false end
        local name = string.lower(button.Name)
        local icon = button:FindFirstChild("Icon", true)
        return name == "close" or name == "closebutton" or name == "exit" or name == "cancel"
            or (icon and icon:IsA("ImageLabel") and icon.Image == "rbxassetid://127503254560275")
    end

    for _, gui in ipairs(playerGui:GetDescendants()) do
        if gachaButton(gui) then
            pcall(function() gui:Activate() end)
            local point = gui.AbsolutePosition + (gui.AbsoluteSize / 2)
            local input = game:GetService("VirtualInputManager")
            input:SendMouseMoveEvent(point.X, point.Y, game)
            input:SendMouseButtonEvent(point.X, point.Y, 0, true, game, 0)
            task.delay(0.08, function()
                pcall(function()
                    input:SendMouseButtonEvent(point.X, point.Y, 0, false, game, 0)
                end)
            end)
            print("[BfRef RandomFruit] closed Gacha result")
            return true
        end
    end
    return false
end

XyraxAutomation.TryRandomFruit = function(force)
    local state = XyraxAutomation.RandomFruit
    local now = os.clock()
    if not force and now < (state.NextAt or 0) then return end
    state.NextAt = now + 15

    local network = game:GetService("ReplicatedStorage"):FindFirstChild("Modules")
    network = network and network:FindFirstChild("Net")
    local remote = network and network:FindFirstChild("RF/GachaNetworkRF")
    if not remote then
        if state.LastStatus ~= "remote missing" then
            state.LastStatus = "remote missing"
            warn("[BfRef RandomFruit] GachaNetworkRF missing")
        end
        return
    end

    local ok, info = pcall(function()
        return remote:InvokeServer({
            Context = "Check",
            BoxName = "ZiolesGacha",
            SpokeNPC = "Blox Fruit Gacha",
        })
    end)
    local cooldown = ok and info and info.Cooldown and info.Cooldown.RequirementMet
    local money = ok and info and info.Price and info.Price.RequirementMet
    local silverKey = ok and info and info.Keys and info.Keys.Silver and info.Keys.Silver.RequirementMet
    if not (ok and cooldown and (money or silverKey)) then
        if state.LastStatus ~= "cooldown" then
            state.LastStatus = "cooldown"
            print("[BfRef RandomFruit] waiting for cooldown / money")
        end
        return
    end

    local bought, result = pcall(function()
        return remote:InvokeServer({Context = "Purchase", BoxName = "ZiolesGacha"})
    end)
    if bought and result ~= false then
        state.LastStatus = "purchased"
        print("[BfRef RandomFruit] purchased; waiting for the Gacha result to close")
        task.spawn(function()
            -- The reveal animation's length varies (lag, client load), so a
            -- single fixed wait either fires too early - before the close
            -- button exists at all - and then never retries, or wastes time
            -- waiting the full delay on the common case where it finished
            -- fast.  Retry every 2s instead, up to one minute total.
            task.wait(2)
            local deadline = os.clock() + 60
            while os.clock() < deadline do
                if not XyraxAutomation.Desired.RandomFruit then
                    return
                end
                if XyraxAutomation.CloseRandomFruitResult() then
                    -- Auto Store's existing worker runs every 0.25s and uses
                    -- the ItemReplicationService stored-fruit inventory
                    -- check.  It stores this result only when that fruit
                    -- type is not owned.
                    return
                end
                task.wait(2)
            end
            if XyraxAutomation.Desired.RandomFruit then
                print("[BfRef RandomFruit] result close button still not found after 1 minute")
            end
        end)
    else
        state.LastStatus = "purchase failed"
        warn("[BfRef RandomFruit] purchase failed: " .. tostring(result))
    end
end

