    local xyraxStoreAttemptBusy = false
    spawn(function()
        while task.wait(0.25) do
            -- Store is a short equipment action, not a movement action.  It
            -- must still run while Auto Tween Fruit is tracking a world item.
            if XyraxAutomation.Desired.StoreFruit and not xyraxStoreAttemptBusy
                and not XyraxAutomation.HeldFruitReserved and not XyraxAutomation.AutoEatFruitBusy
                and not XyraxAutomation.AutoRaidBusy then
                local fruit, storageKey = xyraxFindStorableFruit()
                if fruit and storageKey then
                    xyraxStoreAttemptBusy = true
                    xyraxStoreDebug("store attempt", storageKey .. " from " .. fruit.Parent.Name)
                    local previousNotAutoEquip = _G.NotAutoEquip
                    _G.NotAutoEquip = true
                    local success, result = pcall(function()
                        local player = game:GetService("Players").LocalPlayer
                        local character = player.Character
                        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                        if not (character and humanoid) then
                            return nil
                        end

                        if fruit.Parent ~= character then
                            humanoid:EquipTool(fruit)
                            task.wait(0.2)
                        end
                        if fruit.Parent ~= character then
                            xyraxStoreDebug("equip did not complete", storageKey)
                            return nil
                        end

                        local originalName = fruit:GetAttribute("OriginalName")
                        if originalName ~= storageKey or not fruit:FindFirstChild("EatRemote", true) then
                            xyraxStoreDebug("held fruit is not storable", storageKey)
                            return nil
                        end
                        return game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("StoreFruit", originalName, fruit)
                    end)
                    _G.NotAutoEquip = previousNotAutoEquip

                    if success and result == true then
                        xyraxStoreDebug("stored successfully", storageKey)
                    elseif not success then
                        xyraxStoreDebug("store call error", tostring(result))
                    elseif result == false then
                        xyraxStoreDebug("store rejected", storageKey)
                    elseif type(result) == "number" then
                        xyraxStoreDebug("storage full", storageKey .. " (" .. result .. ")")
                    elseif result == nil then
                        xyraxStoreDebug("store not attempted", storageKey)
                    else
                        xyraxStoreDebug("unexpected store result", storageKey .. " = " .. tostring(result))
                    end

                    -- The current client returns true on success; false or a
                    -- number means failure/capacity full.  Skip this fruit
                    -- type for this run so it cannot keep interrupting Farm.
                    if success and (result == false or type(result) == "number") then
                        XyraxAutomation.StoreSkipped[storageKey] = true
                    end
                    xyraxStoreAttemptBusy = false
                end
            end
        end
    end)
   
   Autofruit:Toggle("Auto Tween Fruits", true, function(value)
    XyraxAutomation.Desired.TweenFruit = value
    end)
    -- The scheduler chooses this job only while xyraxFindWorldFruit finds a
    -- real dropped Tool.  Keep validating the same instance while travelling:
    -- a fruit picked up by another player leaves Workspace, so this worker
    -- stops immediately instead of continuing towards its old CFrame.
    XyraxAutomation.FruitMoveTarget = nil
    XyraxAutomation.FruitMoveAt = 0

    -- GhostShip (map dump: workspace.Map.GhostShip / GhostShipInterior) is
    -- not safe to swim to or from directly - the open water around it
    -- damages the character (DangerDistance).  The only confirmed
    -- touch-interest part is "Teleport" inside GhostShip; it is used for
    -- both directions since no separately-named entrance door was found.
    XyraxAutomation.FindGhostShipTeleport = function()
        local map = workspace:FindFirstChild("Map")
        local ship = map and map:FindFirstChild("GhostShip")
        return ship and ship:FindFirstChild("Teleport", true)
    end
    XyraxAutomation.IsOnGhostShip = function(position)
        if not position then
            return false
        end
        local map = workspace:FindFirstChild("Map")
        for _, name in ipairs({"GhostShipInterior", "GhostShip"}) do
            local model = map and map:FindFirstChild(name)
            local part = model and (model:IsA("BasePart") and model
                or model:FindFirstChildWhichIsA("BasePart", true))
            if part and (position - part.Position).Magnitude <= 400 then
                return true
            end
        end
        return false
    end

    local function xyraxTweenWorldFruit(fruit)
        if not xyraxIsWorldFruit(fruit) then
            return false
        end

        local player = game:GetService("Players").LocalPlayer
        local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        local handle = fruit:FindFirstChild("Handle")
        if not (root and handle and handle:IsA("BasePart")) then
            return false
        end

        -- Crossing the GhostShip boundary (root and fruit on opposite
        -- sides): route through the Teleport part first instead of tweening
        -- straight across the open water between them.
        local teleport = XyraxAutomation.FindGhostShipTeleport()
        if teleport and XyraxAutomation.IsOnGhostShip(root.Position) ~= XyraxAutomation.IsOnGhostShip(handle.Position) then
            if (root.Position - teleport.Position).Magnitude <= 10 then
                if type(firetouchinterest) == "function" then
                    pcall(function()
                        firetouchinterest(root, teleport, 0)
                        task.wait(0.1)
                        firetouchinterest(root, teleport, 1)
                    end)
                end
                task.wait(0.5)
                return true
            end
            local tweenPlaying = _G.TweenCache and _G.TweenCache.PlaybackState == Enum.PlaybackState.Playing
            if XyraxAutomation.FruitMoveTarget ~= teleport or not tweenPlaying
                or os.clock() - XyraxAutomation.FruitMoveAt >= 0.8 then
                XyraxAutomation.FruitMoveTarget = teleport
                XyraxAutomation.FruitMoveAt = os.clock()
                TP1(teleport.CFrame)
            end
            return true
        end

        if (root.Position - handle.Position).Magnitude <= 12 then
            local attempts = (xyraxFruitTouchAttempts[fruit] or 0) + 1
            xyraxFruitTouchAttempts[fruit] = attempts
            if type(firetouchinterest) == "function" then
                pcall(function()
                    firetouchinterest(root, handle, 0)
                    task.wait(0.1)
                    firetouchinterest(root, handle, 1)
                end)
            end
            task.wait(0.25)

            -- If the pickup did not register after several touches, do not let
            -- this one stale/uncollectable instance keep the movement job.
            if xyraxIsWorldFruit(fruit) and attempts >= 4 then
                xyraxIgnoredWorldFruits[fruit] = os.clock() + 30
                xyraxFruitTouchAttempts[fruit] = nil
            end
            return xyraxIsWorldFruit(fruit)
        end

        -- Refresh only this fruit's active tween.  TP1/topos remains the
        -- existing shared tween implementation the user has already tuned.
        local tweenPlaying = _G.TweenCache and _G.TweenCache.PlaybackState == Enum.PlaybackState.Playing
        if fruit ~= XyraxAutomation.FruitMoveTarget or not tweenPlaying or os.clock() - XyraxAutomation.FruitMoveAt >= 0.8 then
            XyraxAutomation.FruitMoveTarget = fruit
            XyraxAutomation.FruitMoveAt = os.clock()
            TP1(handle.CFrame)
        end
        return true
    end

    spawn(function()
        while task.wait(0.15) do
            if _G.TweenFruit then
                local fruit = xyraxFindWorldFruit()
                if fruit then
                    xyraxTweenWorldFruit(fruit)
                else
                    XyraxAutomation.FruitMoveTarget = nil
                end
            else
                XyraxAutomation.FruitMoveTarget = nil
            end
        end
    end)
    
