    Status:Seperator("Fighting Styles")

    -- Presentation only - reuses the existing ownership checks the
    -- automation itself already relies on (xyraxOwnsTool and
    -- XyraxAutomation.OwnsSharkmanKarate), no new check logic.  Kept on
    -- XyraxAutomation.StatusLabels for the same 200-local-register reason as
    -- the block above.
    XyraxAutomation.StatusLabels.Superhuman = Status:Label("Superhuman : ❌")
    XyraxAutomation.StatusLabels.DeathStep = Status:Label("Death Step : ❌")
    XyraxAutomation.StatusLabels.SharkmanKarate = Status:Label("Sharkman Karate : ❌")
    XyraxAutomation.StatusLabels.ElectricClaw = Status:Label("Electric Claw : ❌")
    XyraxAutomation.StatusLabels.DragonTalon = Status:Label("Dragon Talon : ❌")
    XyraxAutomation.StatusLabels.Godhuman = Status:Label("Godhuman : ❌")

    spawn(function()
        while wait() do
            pcall(function()
                -- Reuse the exact flag the automation's own gating already
                -- trusts as "Superhuman owned" (GetDeathStepJob/
                -- GetThirdSeaJob/xyraxGetSuperhumanPhaseOneAction all check
                -- XyraxAutomation.SuperhumanBought). xyraxOwnsTool is only a
                -- fallback for the case that flag was never set (e.g. the
                -- account already owned it before this session).
                local superhumanOwned = XyraxAutomation.SuperhumanBought or xyraxOwnsTool("superhuman")
                XyraxAutomation.StatusLabels.Superhuman:Set("Superhuman : "..(superhumanOwned and "✅" or "❌"))
            end)
        end
    end)

    spawn(function()
        while wait() do
            pcall(function()
                -- Same compound check GetDeathStepJob/GetSharkmanKarateJob/
                -- GetThirdSeaJob already use as their own ownership gate.
                local deathStepOwned = XyraxAutomation.DeathStepOwned or xyraxOwnsTool("death step")
                XyraxAutomation.StatusLabels.DeathStep:Set("Death Step : "..(deathStepOwned and "✅" or "❌"))
            end)
        end
    end)

    spawn(function()
        while wait() do
            pcall(function()
                XyraxAutomation.StatusLabels.SharkmanKarate:Set("Sharkman Karate : "..(XyraxAutomation.OwnsSharkmanKarate() and "✅" or "❌"))
            end)
        end
    end)

    spawn(function()
        while wait() do
            pcall(function()
                -- Electric Claw is only a manual TikTokShop buy button
                -- (BuyElectricClaw, no precheck arg used anywhere in this
                -- file) - no Auto job and no dedicated ownership function
                -- exists for it, so xyraxOwnsTool is not a fallback here, it
                -- is the only available check.
                XyraxAutomation.StatusLabels.ElectricClaw:Set("Electric Claw : "..(xyraxOwnsTool("electric claw") and "✅" or "❌"))
            end)
        end
    end)

    spawn(function()
        while wait() do
            pcall(function()
                -- Same situation as Electric Claw: manual-only button
                -- (BuyDragonTalon), no dedicated Auto ownership check exists.
                -- Not to be confused with the unrelated "Dragon Breath"
                -- xyraxSuperhumanStages entry (BlackbeardReward/DragonClaw).
                XyraxAutomation.StatusLabels.DragonTalon:Set("Dragon Talon : "..(xyraxOwnsTool("dragon talon") and "✅" or "❌"))
            end)
        end
    end)

    spawn(function()
        while wait() do
            pcall(function()
                -- Same situation again (manual-only BuyGodhuman button, no
                -- dedicated Auto check).  The buy button's own label ("God
                -- Human") and remote name ("BuyGodhuman") disagree on
                -- spacing, so check both spellings rather than guessing
                -- which one the actual Tool uses.
                local godhumanOwned = xyraxOwnsTool("godhuman") or xyraxOwnsTool("god human")
                XyraxAutomation.StatusLabels.Godhuman:Set("Godhuman : "..(godhumanOwned and "✅" or "❌"))
            end)
        end
    end)

-- Auto Stat spends the actual replicated point balance in one request.  Do not
-- use stat-Level replication as a gate: it can arrive after the point balance
-- and previously left points sitting unused.
XyraxAutomation.PointStats = 1

Status:Toggle("Melee", true, function(value)
 XyraxAutomation.Desired.StatMelee = value
 melee = value
end)
Status:Toggle("Defense", false, function(value)
defense = value
end)
Status:Toggle("Sword", false, function(value)
sword = value
end)
Status:Toggle("Gun", false, function(value)
gun = value
end)
Status:Toggle("Devil Fruit", false, function(value)
demonfruit = value
end)


spawn(function()
	local Players = game:GetService("Players")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")

	while task.wait() do
		local player = Players.LocalPlayer
		local data = player and player:FindFirstChild("Data")
		local pointsValue = data and data:FindFirstChild("Points")
		local points = pointsValue and tonumber(pointsValue.Value) or 0

		if points and points > 0 then
			local target
			if melee and XyraxAutomation.Desired.StatMelee then
				target = "Melee"
			elseif defense then
				target = "Defense"
			elseif sword then
				target = "Sword"
			elseif gun then
				target = "Gun"
			elseif demonfruit then
				target = "Demon Fruit"
			end

			if target then
				local remotes = ReplicatedStorage:FindFirstChild("Remotes")
				local commF = remotes and remotes:FindFirstChild("CommF_")
				if not commF then
					warn("[AutoStat] CommF_ is unavailable; keeping " .. tostring(points) .. " points")
				else
					local amount = math.floor(points)
					local ok, result = pcall(function()
						return commF:InvokeServer("AddPoint", target, amount)
					end)

					if ok then
						print("[AutoStat] Points=" .. amount .. " -> " .. target .. " +" .. amount .. " | Result=" .. tostring(result))
					else
						warn("[AutoStat] Points=" .. amount .. " -> " .. target .. " failed: " .. tostring(result))
					end
				end
			else
				warn("[AutoStat] Points=" .. tostring(points) .. " but no stat toggle is enabled")
			end
		end
	end
end)
	    

Time = StatusTime:Label("Executor Time")

function UpdateTime()
local GameTime = math.floor(workspace.DistributedGameTime+0.5)
local Hour = math.floor(GameTime/(60^2))%24
local Minute = math.floor(GameTime/(60^1))%60
local Second = math.floor(GameTime/(60^0))%60
Time:Set("[Time] : Hours : "..Hour.." Min : "..Minute.." Sec : "..Second)
end

spawn(function()
while task.wait() do
pcall(function()
UpdateTime()
end)
end
end)

